var e={o00dbf62ed1:{mate:`menaion:11-21.c0.great_vespers.lic[4]`,mateHash:`m1b89342fd54c92`,tone:4,score:.32,next:.18,evidence:[`wording 0.32 (next 0.18)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 4 (As one valiant among martyrs)`},why:[`wording below the bar`,`a second hymn is close`],text:`The young girls rej[oice] today, | and with lamps in hand they go before the [spir]itual Lamp, | as she is [led] with reverence into the Holy of [Ho]lies. | They foreshadow the Brightness past [tell]ing | Who is to [shine] [forth] from her // and enlighten by the Spirit those who sat in the darkness of [ig]norance.`,prints:1,dates:[`2026-1121`],mateText:`Rejoicing today * and bearing candles, * the maidens precede the noetic lamp * and escort her with sanctity * to the Holy of holies, * revealing beforehand * the Effulgence which would ineffably shine forth from her * to illumine with the Spirit ** those who sit in darkness of ignorance.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-20.c0.matins.canons[0].odes.5.items[1]`,mateHash:`m08da199020e9da`,score:.18,text:`Strange is thy conception, strange thy nativity, O most pure Virgin, strange thy coming forth and thine entering of the holy place, and strange are Thy most glorious works, past all telling and understanding.`,tones:[4]},{mate:`menaion:11-20.c0.matins.canons[0].odes.4.items[0]`,mateHash:`m0907838e0239b1`,score:.17,text:`Sacred tongues proclaimed thee beforehand to be the dwelling of Him Who is infinite in nature, O pure one. Wherefore, choirs of virgins accompany thee to the Holy of holies, bearing lamps.`,tones:[4]},{mate:`menaion:11-19.c0.matins.canons[1].odes.5.irmos`,mateHash:`m06b8ff09563dee`,score:.17,text:`O Thou Who hast caused the light to shine, * who hast made bright the dawn and revealed the day; * glory be to Thee, glory be to Thee, * O Jesus Thou Son of God.`,tones:[4]}]},o011f19fee6:{mate:`octoechos:tone3.vespers_weekday.sun.aposticha.items[2]`,mateHash:`m1e73e9ee7fa455`,tone:3,score:.49,next:.19,evidence:[`wording 0.49 (next 0.19)`,`tone 3`,`place: vespers`],first:{doc:`2026-1024-texts-tt`,head:`Tone 3 (for the Martyrs, in the Tone of the week)`},why:[`wording below the bar`],text:`Great is the power of Thy [Cross], O Lord, | for it was fixed in one place, yet acts through[out] the world. | It made fishermen into Apostles and Gentiles into martyrs, // so that [they] might [pray] for our souls.`,prints:1,dates:[`2026-1024`],mateText:`Great is the power of Thy Cross, O Lord! For though it was planted in one place, it worketh throughout the whole world, making apostles of fishermen and martyrs of the heathen, that they might pray for our souls.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.7.sat_praises`,mateHash:`m05d940b7572abd`,score:.19,text:`With the apostles and the martyrs, O Virgin, * pray thou that the departed ** find great mercy at the judgment.`,tones:[]},{mate:`octoechos:tone3.matins_weekday.mon.canons[0].odes.5.items[3]`,mateHash:`m1b81f8b56c9139`,score:.18,text:`The world is ever adorned by your sufferings, O martyrs; wherefore, ye have received a dwelling-place with the angels.`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.mon.canons[0].odes.5.items[4]`,mateHash:`m0b9a8297b28b9d`,score:.16,text:`O thou who, at the word of the archangel, didst alone give birth to the Word in the flesh, yet remained a virgin, deliver me from irrational acts, that I may hymn thee with honorable words.`,tones:[3]}]},o01b62e8eb7:{mate:`menaion:11-16.c0.kontakion`,mateHash:`m13bb897baf7fb3`,tone:4,score:.46,next:.14,evidence:[`wording 0.46 (next 0.14)`,`tone 4`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 Kontakion`},why:[`wording below the bar`],text:`Casting aside the bonds of the customs house for the yoke of [jus]tice, | thou wast revealed as an excellent merchant, rich in [wis]dom from on high. | Thou didst proclaim the [word] of truth | rousing the souls of the [sloth]ful // by writing of the hour of J[udg]ment.`,prints:1,dates:[`2026-1116`],mateText:`Casting off the yoke of the office of a publican, * thou didst shoulder the yoke of righteousness * and wast shown to be a most excellent merchant, * bringing in the wisdom from on high as riches. * Wherefore, thou didst preach the Word of truth * uplifting the souls of the despondent, ** describing the hour of judgment.`,mateTones:[4],sections:[`at the Divine Liturgy`],others:[{mate:`octoechos:tone4.matins_weekday.thu.canons[1].odes.8.items[4]`,mateHash:`m12e2103af2c82e`,score:.14,text:`Grant me thy mercy, O blessed and all-pure one who hast given birth to the exceedingly merciful Word; stand before me at the hour of judgment, and deliver me then from damnation, O pure one.`,tones:[4]},{mate:`menaion:11-16.c0.matins.canons[0].odes.9.items[3]`,mateHash:`m1e271f61782f7c`,score:.13,text:`Without leaving the bosom of the beginningless Father, the beginningless Word became incarnate from thee, O pure and all-praised one, wholly clothing Himself in human nature and accepting its traits, as Matthew writeth, proclaiming the glad tidings.`,tones:[4]},{mate:`menaion:11-23.c0.matins.canons[1].odes.8.items[1]`,mateHash:`m05e94a59d00338`,score:.12,text:`The hypostatic Wisdom gave thee riches and the glory of honor, O most wise one, when thou didst piously theologize, casting down the arrogance of heresies and chanting with love: Bless the Lord, all ye works of the Lord!`,tones:[4]}]},o023a737e50:{mate:`octoechos:tone8.compline.tue.canon.odes.8.irmos`,mateHash:`m1d32edaae1701c`,tone:null,score:.45,next:.35,evidence:[`wording 0.45 (next 0.35)`,`tone not printed on one side`,`place: matins`],first:{doc:`2026-0908-texts-tt`,head:`The Praises Tone 1`},why:[`wording below the bar`,`a second hymn is close`],text:`[Praise] Him, all you [An]gels of His! | Praise Him, [all] His hosts! // To Thee, O God, is [due] a song!`,prints:5,dates:[`2026-0908`,`2026-0914`,`2026-1027`,`2026-1121`],mateText:`The King of heaven, * Who is glorified by the hosts of angels, * let us praise and supremely exalt throughout all ages.`,mateTones:[8],sections:[`The Praises Tone 1`,`The Praises Tone 8`],others:[{mate:`octoechos:tone7.compline.sun.canon.odes.1.items[3]`,mateHash:`m0e17520dbdc512`,score:.35,text:`Ever effective words of praise are due thee, O Theotokos; yet we entreat thee, O pure one: From all the sorrows of life save those who have recourse unto thee.`,tones:[7]},{mate:`octoechos:tone1.matins.anabathmoi[0].gloria`,mateHash:`m1e57dc8bc26a29`,score:.31,text:`To the Holy Spirit, as to the Father and the Son, * are due honor and glory; ** thus let us sing to the Trinity, a single power.`,tones:[1]},{mate:`octoechos:tone2.liturgy_weekday.tue.beatitudes.items[5]`,mateHash:`m043cfda3694e05`,score:.3,text:`With songs of praise let us all unceasingly hymn her who, without being consumed, gave birth to the beginningless God.`,tones:[2]}]},o02e71432d7:{mate:`menaion:09-06.c0.vespers.lic_glory`,mateHash:`m133a4959c95d01`,tone:6,score:.35,next:.18,evidence:[`wording 0.35 (next 0.18)`,`tone 6`,`place: vespers`,`same date`],first:{doc:`2026-0906-texts-tt`,head:`Tone 6 (for Archangel Michael, by Byzantius)`},why:[`wording below the bar`],text:`Rejoice with us, O Princes of the angelic [Pow]ers, | for your leader and our champion, the great Chief [Cap]tain, | gloriously appearing in his honored temple, [san]ctifies it! | Therefore, rightfully singing praises to [him], we cry out: | “Save us under the pro[tec]tion of thy wings, // O Michael, the greatest arch[an]gel!”`,prints:2,dates:[`2026-0906`,`2026-1108`],mateText:`Rejoice with us, all ye angelic legions, for the great supreme commander, your superior and our intercessor, appearing most wondrously this day in his honored temple, doth sanctify it. Wherefore, chanting as is meet, let us cry aloud to him: Cover us with the shelter of thy wings, O Michael, thou greatest of the archangels!`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.2.thu_praises`,mateHash:`m1ce034c00496af`,score:.18,text:`All of my hope do I set on thee, * O Mother of God; ** keep me under thy protection.`,tones:[]},{mate:`menaion:09-06.c0.liturgy.beatitudes[3]`,mateHash:`m07704f843af885`,score:.18,text:`The multitude of the faithful rejoiceth, praising thee, O Michael, and it doth glorify the most holy Word Who in His goodness hath united men and angels.`,tones:[]}]},o04ab8f03c0:{mate:`menaion:11-30.c0.vespers.lic_glory`,mateHash:`m0b476c9ad8bc20`,tone:4,score:.32,next:.26,evidence:[`wording 0.32 (next 0.26)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1130-texts-tt`,head:`Tone 4 (by Anatolius)`},why:[`wording below the bar`,`a second hymn is close`],text:`Leaving behind thy fishnets, O Apostle [An]drew, | thou didst catch men with the net of thy [preach]ing. | [Throw]ing to us the bait of [right]eousness, | thou didst deliver all nations from the depths of [er]ror. | O Apostle Andrew, brother of the [fore]most dis[cip]le, | all-glorious and never-failing inter[ces]sor, // may the celebration of thy memory enlighten all who dwell in [dark]ness!`,prints:1,dates:[`2026-1130`],mateText:`Leaving behind the netting of fish, O apostle, thou dost catch men with the rod of thy preaching, lowering the lure of piety as a hook and drawing forth all the nations from the depths of falsehood, O apostle Andrew, who art the blood relation of the pre-eminent one. O trumpet-voiced herald of the whole world, fail not in thy prayers on behalf of us who with love and faith ever praise thine honored memory.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-30.c0.matins.exapostilarion_glory`,mateHash:`m0b87057637cb64`,score:.26,text:`Most gloriously let us praise the apostle Andrew, the brother of Peter, the first of all the disciples, the beholder and servant of Him Who is the Word, for he hath enlightened the nations and, crucified, met his end as a disciple of the Master.`,tones:[]},{mate:`octoechos:tone4.matins_weekday.thu.sessionals[2].items[0]`,mateHash:`m1dda2b0df1b627`,score:.19,text:`The Sun of righteousness emitted you like rays to enlighten the whole earth, O glorious apostles. By your divine prayers ye illumine all with the never-waning light of God, enlightening those who celebrate your holy memory with faith.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.mon.canons[0].odes.3.items[2]`,mateHash:`m0fbcd16edc672f`,score:.17,text:`Truly dyed red by your blood, your feet ran right swiftly to the heavens, leaving behind the world of sin, O martyrs, ye co-conversers with the divine powers.`,tones:[4]}]},o06aeb391f5:{mate:`menaion:11-21.c0.great_vespers.lic[2]`,mateHash:`m0e89cee4012660`,tone:1,score:.47,next:.26,evidence:[`wording 0.47 (next 0.26)`,`tone 1`,`place: vespers`,`melody “O wondrous marvel ...”`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 1 (Oh, the Marvelous Wonder)`},why:[`wording below the bar`],text:`Thou art the [preach]ing of the prophets, O Virgin [Moth]er of God; | the glory of the Apostles and the boast of [Mar]tyrs, | and the re[new]al of all the [earth]-born, | for through [thee], we are [re]conciled to God. | [There]fore, being saved by thine inter[ces]sions, | we honor thy coming into the [Tem]ple of the Lord; | and with the [An]gel we all cry out to [thee] in song: // “Rejoice, O all-revered [La]dy!”`,prints:2,dates:[`2026-1121`,`2026-1125`],mateText:`Thou art the proclamation of the prophets, the glory of the apostles, the boast of the martyrs, the restoration of all mortals, O Virgin Mother of God; for through thee have we been reconciled with God. Wherefore, we honor thine entrance into the temple of the Lord, and with the angel all of us who find salvation through thy supplications cry out to thee in hymns: Rejoice, O most pure one!`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.1.thu_praises`,mateHash:`m09c11b1c1098f4`,score:.26,text:`Rejoice, O Virgin Theotokos, * thou boast of all the world! ** Rejoice, O most pure and blessed Mother of God!`,tones:[]},{mate:`octoechos:tone1.matins_weekday.thu.canons[0].odes.8.items[3]`,mateHash:`m1797bc7dda7278`,score:.26,text:`With the angels, the apostles, the martyrs and prophets, O Mother of God, entreat Christ, that He save those who cry aloud: Bless the Lord, all ye works of the Lord! Hymn and supremely exalt Him throughout the ages!`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.thu.aposticha_theotokion`,mateHash:`m04888193ef8718`,score:.24,text:`Rejoice, O Virgin Theotokos! Rejoice, boast of the whole world! Rejoice, O most pure and blessed Mother of God!`,tones:[1]}]},o0740dc6d30:{mate:`octoechos:tone5.compline.tue.canon.odes.9.items[0]`,mateHash:`m0905f88da317d4`,tone:5,score:.37,next:.26,evidence:[`wording 0.37 (next 0.26)`,`tone 5`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`],first:{doc:`2026-1027-texts-alaska-tt`,head:`Tone 5 (Theotokion)`},why:[`wording below the bar`,`a second hymn is close`],text:`O pure [Vir]gin Lady Theo[to]kos, | our hope that cannot be [put] to shame, | be our pro[tec]tion and our de[liv]erance | from the [griev]ous trials and tribulations that be[set] us. | Together with holy Olga and [all] the saints, // entreat thy Son and our God that He may pour out upon [us] His rich [mer]cy.`,prints:1,dates:[`2026-1027`],mateText:`Unto thee do we pour forth supplication from our pain: Have mercy on us sinners, lest we be put to shame on the day of trial, for we call upon thee, the all- merciful Theotokos.`,mateTones:[5],sections:[`Litya`],others:[{mate:`menaion:11-14.c0.matins.sessional_2[1]`,mateHash:`m12f6ffb040eefb`,score:.26,text:`O most pure Virgin, who art our protection, from divers temptations and evil circumstances and grievous misfortunes do thou free us who have steadfast hope in thee, beseeching thy Son together with His apostles, and save thou all that hymn thee.`,tones:[5]},{mate:`octoechos:tone5.matins_weekday.thu.sessionals[2].closer`,mateHash:`m1fa487bfb347a3`,score:.26,text:`We who have thee as our unashamed hope, O Virgin who art our protection, free us from divers perils, evil circumstances and grievous tribulations, and with His apostles beseech thy Son, that He save all who hymn thee.`,tones:[5]},{mate:`octoechos:tone5.matins_weekday.mon.sessionals[2].closer`,mateHash:`m02d0226446ed11`,score:.22,text:`O fervent and invincible intercessor, * diligent and unashamed hope, * rampart, protection and haven * of those who have recourse to thee, * O pure Ever-virgin do thou, together with the angels, * entreat thy Son and God, ** that He grant peace, salvation and great mercy to the world.`,tones:[5]}]},o080ab14195:{mate:`menaion:11-14.c0.vespers.lic[2]`,mateHash:`m143c4254983638`,tone:6,score:.4,next:.21,evidence:[`wording 0.4 (next 0.21)`,`tone 6`,`place: vespers`,`same date`],first:{doc:`2026-1114-texts-tt`,head:`Tone 6 (Having placed all their hope)`},why:[`wording below the bar`],text:`O God-seer Philip, | thou didst speak with divine inspiration and the teaching of the Holy Spirit, | sounding the Savior's heavenly Gospel in the world with a fiery tongue. | Thou didst burn all deceit to ashes like dried grass, | and didst proclaim to the universe the Lord Christ, // Who is Master over all.`,prints:1,dates:[`2026-1114`],mateText:`Thou wast an instrument * of the Holy Spirit, * sounding with divine phrases and melodies, * chanting in the world * the music of the transcendent Gospel of the Savior * with thy tongue of fire. * For thou didst utterly consume all delusion * as matter fit to be burned, * as the withered grass of the earth. * And thou didst proclaim to the whole world * the Lord Christ Who is Master over all, ** O Philip, beholder of God.`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`menaion:11-14.c0.matins.megalynarion`,mateHash:`m1096d515d90654`,score:.21,text:`We magnify thee, O Philip, apostle of Christ, and we honor thy pangs and labors, wherewith thou didst struggle in the proclamation of the Gospel of Christ.`,tones:[]},{mate:`menaion:11-14.c0.vespers.troparion_alternate`,mateHash:`m0575c5b42721f0`,score:.16,text:`The whole world is splendidly adorned; * Ethiopia doth dance, graced as with a crown, * having been enlightened by thee, * and she doth radiantly celebrate thy memory, O divinely eloquent Philip, * for thou didst teach all to believe in Christ * and didst fittingly finish the course of the Gospel; * wherefore, the land of Ethiopia doth boldly entreat God. ** Beseech Him to grant us great mercy.`,tones:[]},{mate:`menaion:11-28.c0.matins.canons[0].odes.4.items[0]`,mateHash:`m0a10068fea520c`,score:.14,text:`Illumined with the light of the Spirit, O father, thou didst impart light to the blind by thy supplications, emulating thy Master and God, O divinely inspired one.`,tones:[6]}]},o08a2a8050f:{mate:`octoechos:tone7.great_vespers.aposticha[1]`,mateHash:`m0d6447ef7e3a69`,tone:7,score:.42,next:.33,evidence:[`wording 0.42 (next 0.33)`,`tone 7`,`place: vespers`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`[Come], let us worship the One Who [rose] from the dead, | and en[light]ened all cre[a]tion! | By His [death], He saved us from the [tor]ments of hell. // By His Resurrection He has granted us eternal [life] and great [mer]cy.`,prints:2,dates:[`2026-0920`,`2026-1115`],mateText:`Come, let us worship Him Who hath arisen from the dead * and enlightened all things; * for He hath delivered us from the tyranny of Hades * through His Resurrection on the third day, * granting us life and great mercy.`,mateTones:[7],sections:[`Aposticha`],others:[{mate:`octoechos:tone7.matins.praises.stichera[5]`,mateHash:`m008dd8ed4ebecf`,score:.33,text:`Come, let us rejoice in the Lord * and be glad in His Resurrection; * for He hath raised the dead with Himself * from the indestructible bonds of Hades, ** and as God hath bestowed upon the world eternal life and great mercy.`,tones:[7]},{mate:`octoechos:tone7.compline.mon.canon.odes.7.items[1]`,mateHash:`m1d2134afc9409b`,score:.28,text:`Knowing thee to be the Mother of Life, O pure one, I cry to thee: Deliver me from the death of the soul, and grant unto me eternal life!`,tones:[7]},{mate:`octoechos:tone7.liturgy.beatitudes.troparia[2]`,mateHash:`m128977f6f196d1`,score:.28,text:`Thou didst nail our sins to Cross, O compassionate Christ, and by Thy death Thou didst slay death, O Thou who didst raise up the dead from among the dead. Wherefore, we worship Thy holy Resurrection.`,tones:[7]}]},o09ecef2848:{mate:`octoechos:tone7.great_vespers.lic[4]`,mateHash:`m153409c176463a`,tone:7,score:.47,next:.19,evidence:[`wording 0.47 (next 0.19)`,`tone 7`,`place: vespers`],first:{doc:`2026-1115-texts-tt-`,head:`Tone 7 (for the Resurrection)`},why:[`wording below the bar`],text:`Ful[fill]ing the prophecy of [Da]vid, | [Christ] manifested His greatness in Zion to the dis[ci]ples. | He is [praised] and always [glo]rified, | to[get]her with the Father and the Holy [Spir]it. | At [first] as the Word, He was [bod]iless, | but [then] He took flesh and was [slain] for our sake. // He rose in [pow]er as the [Lov]er of man!`,prints:1,dates:[`2026-1115`],mateText:`Fulfilling David’s prophecy Christ revealed His majesty * to His disciples in Zion, * showing that He was praised and ever glorified with the Father and the Holy Spirit; * at first without flesh as the Word, * afterwards for our sake incarnate and put to death as a man, * and risen with authority ** as the Lover of mankind.`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone7.matins_weekday.mon.canons[1].odes.3.items[3]`,mateHash:`m081818797639ae`,score:.19,text:`The Word and Lover of mankind, Who by His will brought all things out of non-existence, in His tender compassion took flesh from thee, O Virgin, becoming a man`,tones:[7]},{mate:`octoechos:tone7.matins_weekday.tue.canons[0].odes.7.items[2]`,mateHash:`m16826a29f6a437`,score:.17,text:`O most wise ones, ye died, desiring everlasting life for the world; and having utterly slain the enemy, ye took wing to the heavens, ever praying for us, O spiritual athletes.`,tones:[7]},{mate:`octoechos:tone7.matins_weekday.fri.canons[1].odes.7.items[1]`,mateHash:`m16ba3dd8ed12ee`,score:.17,text:`David the ancestor of God described thy glory, O all-immaculate Virgin, and manifestly prophesied thee as the Queen of creation, who standeth at the right hand of the God of our fathers.`,tones:[7]}]},o0c8b63db34:{mate:`menaion:11-30.c0.vespers.lic[1]`,mateHash:`m063046869cdffc`,tone:4,score:.38,next:.34,evidence:[`wording 0.38 (next 0.34)`,`tone 4`,`place: vespers`,`melody “Called from on high ...”`,`same date`,`NAMES DIFFER: the OCA text names Andrew, Peter; ours does not`],first:{doc:`2026-1130-texts-tt`,head:`Tone 4 (Called from on high)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Andrew, Peter; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`O all-wise [An]drew, | when the all-holy Word became in[car]nate, | bringing [life] and salvation to [all] the earth, | thou didst hearken to the voice of the [Fore]runner | and wast the [first] to [fol]low Him. | Thou wast offered to Him as the first fruits of the [hu]man race. | Thou didst reveal Him to Peter, thy [broth]er. // Pray that He may save and en[light]en our souls!`,prints:1,dates:[`2026-1130`],mateText:`When the all-holy Word became incarnate, granting us life, heralded by the voice of the Forerunner, announcing the glad tidings of salvation unto those on earth, then didst thou most wisely follow Him, surrendering thyself as an all-holy offering, and proclaiming Him to be our God to thy kinsman. Him do thou beseech, that He save and enlighten our souls.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-30.c0.matins.exapostilarion_glory`,mateHash:`m0b87057637cb64`,score:.34,text:`Most gloriously let us praise the apostle Andrew, the brother of Peter, the first of all the disciples, the beholder and servant of Him Who is the Word, for he hath enlightened the nations and, crucified, met his end as a disciple of the Master.`,tones:[]},{mate:`menaion:11-30.c0.troparion`,mateHash:`m12d50e4c1eea44`,score:.27,text:`As thou art the first-called of the apostles * and the brother of the pre-eminent one, * entreat thou the Master of all, O Andrew, * that He grant peace to the world ** and great mercy to our souls.`,tones:[4]},{mate:`menaion:11-30.c0.matins.exapostilarion`,mateHash:`m06020b61b30129`,score:.22,text:`Finding thee, the beginningless Word revealed thee to be the first-called of all the apostles, O all-blessed and ever-memorable Andrew; and having followed in His footsteps, thou didst show thyself to be a guide for those who are astray, leading them to the divine and heavenly path.`,tones:[]}]},o0d97739cdd:{mate:`menaion:11-21.c0.matins.canons[0].odes.9.irmos`,mateHash:`m034262d24b967a`,tone:4,score:.38,next:.27,evidence:[`wording 0.38 (next 0.27)`,`tone 4`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 4 1st Canon, Ode 9 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`Since she is a living Ark of God let no profane hand touch the Theotokos. But let the lips of believers unceasingly sing to her, praising her in joy with the angel’s song:// “Truly, thou art more exalted than all, O pure Virgin!”`,prints:4,dates:[`2026-1121`,`2026-1122`,`2026-1125`],mateText:`In nowise may the hand of the defiled * touch the animate ark of God; * and let the lips of the faithful * never-silently cry out with joy to the Theotokos, * chanting the words of the angel: * Rejoice, O thou who art full of grace! * The Lord is with thee!`,mateTones:[4],sections:[`Gospel`,`Instead of “It is truly meet…,” we sing:`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.mon_vespers_tue_matins`,mateHash:`m1a547a0980cd58`,score:.27,text:`O Theotokos, we offer unto thee the cry Rejoice!; * for, having given birth unto God, ** thou hast been shown to be more exalted than the angels.`,tones:[]},{mate:`menaion:11-21.c0.matins.canons[0].odes.9.items[1]`,mateHash:`m04b50ae492fc59`,score:.24,text:`O pure Theotokos, as thou hast the most radiant beauty of purity of soul and art full of the grace of God from heaven, with the ever-existent light thou dost ever enlighten those who cry out with joy: Truly thou art more highly exalted than all, O pure Virgin!`,tones:[4]},{mate:`menaion:12-02.c0.matins.canons[0].odes.8.items[3]`,mateHash:`m07a1c30e346f5c`,score:.22,text:`Thou wast truly shown to be the Mother of Him Who shone forth from the Father before all ages; for thou alone wast more holy than all others. Thee, the pure one, do we supremely exalt throughout the ages!`,tones:[4]}]},o129eff17ab:{mate:`octoechos:tone3.little_vespers.lic[2]`,mateHash:`m0b6a62d8a3af0e`,tone:3,score:.47,next:.25,evidence:[`wording 0.47 (next 0.25)`,`tone 3`,`place: vespers`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 (for the Resurrection)`},why:[`wording below the bar`],text:`All has been enlightened by Thy Resur[rec]tion, O Lord. | Paradise has been [o]pened again. | All creation, [prais]ing Thee, // always [of]fers [Thee] a song.`,prints:2,dates:[`2026-0823`,`2026-1018`],mateText:`By Thy Resurrection, O Lord, * the universe hath been filled with light * and paradise hath been opened again, * while all creation, singing Thy praise, ** each evening offers hymns unto Thee.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone3.matins.anabathmoi[1].troparia[1]`,mateHash:`m04786d708fa1bf`,score:.25,text:`The saints, O Christ, fruits of the womb, * are by the Spirit, always sons to Thee, ** as Thou art to the Father.`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.wed.canons[0].odes.8.items[0]`,mateHash:`m12512d8adac7ea`,score:.23,text:`When Thou wast crucified, paradise was opened again, and the sword which was wielded against us was withdrawn, putting to shame the spear which pierced Thy holy side, O greatly merciful Christ.`,tones:[3]},{mate:`octoechos:tone3.ikos`,mateHash:`m03dc084e784223`,score:.19,text:`Let heaven and earth dance today, and with one accord sing the praises of Christ our God, for He hath raised the prisoners from the tombs. All creation rejoiceth together as it offers fitting songs to the Creator of all things and our Redeemer. For today, as Giver of life, He draweth mortals out of Hades raising them to heaven. He layeth low the uprisings of the enemy and hath destroyed the gates of Hades by the divine might of His authority.`,tones:[3]}]},o135b4e8bca:{mate:`octoechos:tone1.vespers_weekday.sun.lic.menaion_fallback[2]`,mateHash:`m1c38df2b24801f`,tone:1,score:.42,next:.24,evidence:[`wording 0.42 (next 0.24)`,`tone 1`,`place: vespers`],first:{doc:`2026-0823-texts-tt`,head:`Tone 1 (for the Feast) Automelon`},why:[`wording below the bar`],text:`The Do[min]ions and Thrones, the Rulers, Principalities and [Pow]ers, | the Cherubim and fearsome Seraphim, glorify thy [fall]ing asleep. | All [those] born of [earth] rejoice, | adorned with honor by thy di[vine] [glo]ry. | Kings fall [down] and sing with the Archangels and [An]gels: | “Rejoice, O full of grace, the Lord is [with] thee, // He that grants the world great [mer]cy through thee!”`,prints:1,dates:[`2026-0823`],mateText:`O archangels, angels, principalities, thrones, dominions, six-winged seraphim and divine and many-eyed cherubim, ye organs of wisdom, powers and most divine authorities: Pray ye unto Christ, that He grant our souls peace and great mercy.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.4.items[0]`,mateHash:`m0baa60542c45d7`,score:.24,text:`As the first adornments of the universe! the thrones, and cherubim and seraphim shone forth directly with divine rays; and ordering themselves now in their deifying sacred ranks, they chant: Glory to Thy power, O Lord!`,tones:[1]},{mate:`octoechos:tone1.compline.sat.canon.odes.4.items[0]`,mateHash:`m19738a9afe42e9`,score:.19,text:`Thee, O Mother of God, hath the ruler of the world described beforehand as comely and all-honored among women, as coming up from the wilderness, and bearing Christ, thine Offspring, in thine arms; and he cried: Glory to Thy power, O Lord!`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.5.items[0]`,mateHash:`m009300676c1ceb`,score:.19,text:`Set afire by divine love, the dominions, principalities and powers, the secondary ranks, hymn the one Essence and Power of the Godhead with unceasing voices.`,tones:[1]}]},o171d37be1e:{mate:`menaion:09-08.c0.matins.praises[1]`,mateHash:`m0980159d70a6db`,tone:1,score:.47,next:.25,evidence:[`wording 0.47 (next 0.25)`,`tone 1`,`place: matins`,`same date`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-0908-texts-tt`,head:`Tone 1 [(Oh, the Marvelous Wonder)]`},why:[`wording below the bar`,`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`[Oh], the marvelous [won]der! | The fruit of a barren [wom]an | has shone [forth] at the behest of the Almighty [Mak]er of all | and mightily destroyed the barrenness of this world, which was [fruit]less in [good] things. | You [moth]ers, dance with the mother of the Theo[to]kos and cry: | “Rejoice, O Full of Grace, the Lord is [with] thee, // He Who grants the world through thee His great [mer]cy!”`,prints:1,dates:[`2026-0908`],mateText:`O wondrous miracle! Fruit hath shone forth from the barren woman at the behest of the Almighty Creator of all. She hath boldly loosed the barrenness of the world. Ye mothers, join chorus with the mother of the Theotokos, crying: O joyous one, rejoice! The Lord is with thee, Who through thee granteth the world great mercy!`,mateTones:[1],sections:[`The Praises Tone 1`],others:[{mate:`menaion:09-05.c1.vespers.aposticha[4]`,mateHash:`m0472c03db5e312`,score:.25,text:`A most glorious fruit of the womb was given by the most compassionate God to thee, a woman barren and past childbearing: the preacher of repentance. Wherefore, calling thee blessed, we magnify the almighty mercy of God.`,tones:[1]},{mate:`menaion:11-30.c0.matins.canons[0].odes.3.items[0]`,mateHash:`m05b2b0a6bdcb59`,score:.22,text:`Dispel all the barrenness of my fruitless thoughts and reveal my soul to be fertile in the virtues, O all-holy Theotokos, thou helper of the faithful.`,tones:[1]},{mate:`menaion:09-08.c0.little_vespers.lic[3]`,mateHash:`m07c792975d6a98`,score:.22,text:`She who before was as a barren land * giveth birth to fertile ground, * and, having given forth a holy fruit from her fruitless womb, * she nurtureth her with milk. * O awesome wonder! The nurturer of our Life, ** who received the Bread of heaven in her womb is nourished with milk at her mother’s breasts!`,tones:[1]}]},o1a2da59abf:{mate:`octoechos:tone3.great_vespers.lic[3]`,mateHash:`m13307807ee4a86`,tone:null,score:.44,next:.35,evidence:[`wording 0.44 (next 0.35)`,`tone not printed on one side`],first:{doc:`2026-0914-texts-tt`,head:`(Instead of the Trisagion, we sing:)`},why:[`wording below the bar`,`a second hymn is close`],text:`Before Thy Cross, we bow down in worship, O Master, | and Thy holy Resurrection we glorify.`,prints:1,dates:[`2026-0914`],mateText:`We worship Thy precious Cross, O Christ, * and we praise and glorify Thy Resurrection, ** for by Thy wounds we have all been healed.`,mateTones:[3],sections:[`Instead of the Trisagion, we sing:`],others:[{mate:`menaion:09-08.c0.matins.canons[1].odes.9.items[3]`,mateHash:`m10694825b83703`,score:.35,text:`To thee, O Theotokos who wast born of Anna, do we faithfully offer up hymnody as a gift, mothers and virgins glorifying thee as the only Mother and Virgin; and we bow down before thee and hymn and glorify thee.`,tones:[8]},{mate:`octoechos:tone2.liturgy.beatitudes.gloria`,mateHash:`m0dcc5b236edd36`,score:.34,text:`Let us all now glorify the Father, worship the Son and praise with faith the Holy Spirit.`,tones:[2]},{mate:`menaion:09-08.c0.matins.canons[1].odes.7.items[0]`,mateHash:`m118fc6c3b51864`,score:.34,text:`We celebrate and bow down with faith before thy holy nativity, O pure one, honoring thy Son, by Whom we have now been delivered from the ancient condemnation of Adam.`,tones:[8]}]},o1a84c562ef:{mate:`octoechos:tone8.matins_weekday.fri.canons[0].odes.5.irmos`,mateHash:`m1c2aeab53bf038`,tone:8,score:.47,next:.34,evidence:[`wording 0.47 (next 0.34)`,`tone 8`,`place: matins`],first:{doc:`2026-0908-texts-tt`,head:`Tone 8 Katavasia, Ode 5`},why:[`wording below the bar`,`a second hymn is close`],text:`O thrice-blessed Tree, on which Christ the King and Lord was stretched! | Through thee the one who deceived us through a tree has fallen, | caught by the bait of God, Who was nailed to thee in the flesh, // and Who grants peace to our souls.`,prints:1,dates:[`2026-0908`],mateText:`O thrice-blessed Tree, on which Christ the king and Lord was stretched! * Through thee the beguiler fell, * who tempted mankind with the tree. * He was caught in the trap set by God, * who was crucified upon thee in the flesh, * granting peace unto our souls.`,mateTones:[8],sections:[`Gospel`],others:[{mate:`menaion:09-08.c0.matins.canons[1].odes.5.items[5]`,mateHash:`m1727b61fe48def`,score:.34,text:`Thy womb became the chariot of the Sun; thy purity remained intact as before, O Virgin; for Christ the Sun hath appeared from thee like a Bridegroom from a bridal chamber. Katavasia: O thrice-blessed Tree, on which Christ the king and Lord was stretched! * Through thee the beguiler fell, * who tempted mankind with the tree. * He was caught in the trap set by God, * who was crucified upon thee in the flesh, * granting peace unto our souls.`,tones:[8]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_lauds`,mateHash:`m0835d754800ce2`,score:.2,text:`Through the prayers of the Theotokos, * grant peace to the life of us who cry out to Thee: ** O merciful Lord, glory be to Thee!`,tones:[]},{mate:`menaion:09-05.c1.matins.canons[0].odes.7.items[2]`,mateHash:`m1a98b777bcd178`,score:.18,text:`O thrice-blessed Zacharias, thou wast wholly a divine instrument of the Spirit, and didst proclaim thy son to be a prophet, who crieth: Blessed art Thou, O Lord our God, throughout the ages!`,tones:[1,8]}]},o1bb12d6c3c:{mate:`menaion:11-16.c0.great_vespers.lic[4]`,mateHash:`m0e31ea98753670`,tone:4,score:.32,next:.33,evidence:[`wording 0.32 (next 0.33)`,`tone 4`,`place: vespers`,`melody “Called from on high ...”`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 (Called from on high)`},why:[`wording below the bar`,`a second hymn is close`],text:`Burning up deception with a [fier]y tongue, | thou, O most wise Matthew, wast highly ex[alt]ed. | After re[ceiv]ing the Comforter, Whose coming en[light]ened thee, | thou didst speak to the people of the majesty of the Al[migh]ty, | bringing amazement to the minds of [those] who [heard] thy words. | Now thy proclamation has gone out into all the earth, O divinely inspired A[pos]tle. // Pray to God that He will be gracious to all who sing thy [prais]es!`,prints:1,dates:[`2026-1116`],mateText:`Thou wast revealed * burning up delusion * with a tongue of fire, * O Matthew all-praised and most wise, * receiving the advent of the Comforter, * Who made thee radiant by His essence; * hence, thou hast astonished every thought * of those who listen to thy words, * relating to mankind the mighty works of the almighty One. * And now thy sound hath gone forth into all the earth, * O divinely inspired one. * Him do thou entreat, ** that He take pity on all who hymn thee.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-16.c0.matins.canons[0].odes.3.items[2]`,mateHash:`m0850b645bf744f`,score:.33,text:`The sound of thy fiery tongue consumed the temples of the demons, O divinely inspired Matthew, thou instrument of the Comforter, through whom Christ, the hypostatic Life of all, hath been proclaimed.`,tones:[4]},{mate:`menaion:11-18.c0.matins.canons[1].odes.4.items[2]`,mateHash:`m14d3329ce9488e`,score:.26,text:`Made wise by the inspiration of the Comforter, the tongue of the boy proclaimed Thee to be the Lord of glory, the Creator of all and God Who art able to save, O Lover of mankind.`,tones:[4]},{mate:`menaion:11-21.c0.matins.canons[0].odes.9.items[1]`,mateHash:`m04b50ae492fc59`,score:.17,text:`O pure Theotokos, as thou hast the most radiant beauty of purity of soul and art full of the grace of God from heaven, with the ever-existent light thou dost ever enlighten those who cry out with joy: Truly thou art more highly exalted than all, O pure Virgin!`,tones:[4]}]},o1eebfe0799:{mate:`octoechos:tone4.great_vespers.lic[3]`,mateHash:`m045a54d65b6756`,tone:4,score:.45,next:.24,evidence:[`wording 0.45 (next 0.24)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`],text:`Come, O [peo]ple, | let us sing of the Savior’s Resurrection on the [third] day! | By [it], we have been freed from the unbreakable [bonds] of hell. | By it, we have received life and incor[rup]tion. | Save us by Thy [Res]ur[rec]tion! // O Life-creating and almighty Savior, [glo]ry to Thee!`,prints:2,dates:[`2026-0830`,`2026-1025`],mateText:`Come O ye peoples, let us hymn the Savior’s rising on the third day, * whereby we were redeemed from the unbreakable bonds of Hades * obtaining incorruption and life, as we cry aloud: * “Thou, who wast crucified and buried and rose again, ** save us by Thy Resurrection, O only Lover of mankind.”`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.matins_weekday.wed.canons[0].odes.1.items[4]`,mateHash:`m1c507d9b3f3d3d`,score:.24,text:`Bound for Christ, Who was willingly bound, and hath destroyed all delusion, O wise and holy ones, ye bound the greatly crafty one with unbreakable bonds; wherefore, ye are called blessed, as is meet.`,tones:[4]},{mate:`octoechos:tone4.great_vespers.lic[4]`,mateHash:`m0df0f56e892074`,score:.22,text:`Angels and mortals hymn Thine arising on the third day, O Savior, * through which the ends of the inhabited world were filled with light, * and we were all redeemed from the slavery of the enemy, as we cry aloud: * “O life-giving, all- powerful Savior, ** save us by Thy Resurrection, O only Lover of mankind.”`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.fri.canons[0].odes.8.items[0]`,mateHash:`m0f3046dfd76c8e`,score:.21,text:`As the Timeless One, Who having entered into time, dost release me from the bonds of time; and willingly bound, O Master, Thou didst send the prideful one into unbreakable bonds, saving me by Thy Cross and sufferings. Wherefore, I bless Thee, O Christ, throughout the ages.`,tones:[4]}]},o20f1fc3c4c:{mate:`octoechos:tone1.matins.anabathmoi[2].troparia[0]`,mateHash:`m15ee5392458daa`,tone:1,score:.36,next:.27,evidence:[`wording 0.36 (next 0.27)`,`tone 1`],first:{doc:`2026-0914-texts-tt`,head:`Tone 1 Troparion`},why:[`wording below the bar`,`a second hymn is close`],text:`Bow down in worship to the Lord in His holy court! (Ps. 98:10)`,prints:1,dates:[`2026-0914`],mateText:`With those who said unto me: * “Let us journey to the courts of the Lord,” ** my Spirit was gladdened and my heart rejoiceth.`,mateTones:[1],sections:[`The Third Antiphon`],others:[{mate:`octoechos:tone1.matins_weekday.thu.canons[1].odes.5.items[0]`,mateHash:`m05bb7509ff7681`,score:.27,text:`Planted in the courts of the Lord, O holy hierarch Nicholas our father, like a fruitful olive-tree, by grace thou now anointest the faces of all with the oil of thy labors.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.sat.canons[1].odes.5.items[1]`,mateHash:`m184f26ebc786a4`,score:.25,text:`O Thou Who didst free mankind from mortality and corruption, the souls of those who have departed in faith do Thou cause to dwell in the courts of Thy saints, from whence all sorrow hath fled, and where gladness abideth.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.sat.canons[1].odes.3.items[1]`,mateHash:`m08cdb0f0d34988`,score:.24,text:`Thou alone hast appeared on the earth, O my sinless Savior Who takest away the sins of the world, in that Thou art full of loving-kindness. In the courts of Thy saints, in the sweetness of paradise, grant rest unto the souls of those who have departed this world in faith, O Lover of mankind.`,tones:[1]}]},o214d17a1b2:{mate:`octoechos:tone2.great_vespers.aposticha[1]`,mateHash:`m0386f2d2e7bf14`,tone:2,score:.54,next:.46,evidence:[`wording 0.54 (next 0.46)`,`tone 2`,`place: vespers`],first:{doc:`2026-1011-texts-tt`,head:`Tone 2 (for the Resurrection)`},why:[`a second hymn is close`],text:`By the Tree Thou didst destroy the curse of the Tree, O [Sav]ior. | By Thy burial Thou didst mortify the [maj]esty of death. | Thou hast en[light]ened our race by Thy Resur[rec]tion. // O Giver of life, Christ our God, [glo]ry to Thee!`,prints:2,dates:[`2026-1011`,`2026-1206`],mateText:`Nullifying the curse of the tree through a Tree, O Savior, * Thou didst slay the might of death by Thy burial, * enlightening our race by Thine arising; * wherefore we cry out to Thee; * “O Giver of life, Christ our God, ** glory be to Thee!”`,mateTones:[2],sections:[`Aposticha`],others:[{mate:`octoechos:tone2.great_vespers.lic[4]`,mateHash:`m188d9ff42ba2da`,score:.46,text:`By Thy Cross Thou hast destroyed the curse of the tree; * by Thy burial Thou didst slay the might of death; * by Thine arising Thou hast enlightened mankind; * wherefore we cry out to Thee; * “O Christ, our God and Benefactor, ** glory be to Thee!”`,tones:[2]},{mate:`octoechos:tone2.matins.canon.odes.9.cross_resurrection.troparia[1]`,mateHash:`m0259ab731b74e9`,score:.24,text:`Let us the faithful all worship God, who by His own death hath destroyed with might the power of death; for He hath raised with Him the dead of all ages, and to all doth He grant life and Resurrection.`,tones:[2]},{mate:`octoechos:tone2.liturgy.beatitudes.troparia[3]`,mateHash:`m080647a3d75858`,score:.21,text:`By Thy death, O Lord, death hath been swallowed up, and by Thy Resurrection, O Savior, Thou hast saved the world.`,tones:[2]}]},o224b6b36f8:{mate:`octoechos:tone5.great_vespers.aposticha[2]`,mateHash:`m09b46214f79f75`,tone:5,score:.3,next:.22,evidence:[`wording 0.3 (next 0.22)`,`tone 5`,`place: vespers`],first:{doc:`2026-0906-texts-tt`,head:`Tone 5 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`Thy cruci[fix]ion and descent into hell are awesome, O [Lov]er of man. | Thou hast captured it, releasing the ancient [pris]oners. | Thou hast [o]pened Paradise and [giv]en it to us. | [Grant] us purifi[ca]tion of sins, | who glorify Thy Resurrection on the [third] day! | Make us [wor]thy of [Par]adise // and [save] us, O [Lov]er of man!`,prints:3,dates:[`2026-0906`,`2026-1101`],mateText:`Wonderful is Thy crucifixion * and Thy descent into Hades, O Lover of mankind, * for having despoiled it and as God gloriously raising with Thyself * those who were captive therein, * Thou hast opened paradise and bidden them welcome. * So too grant unto us who glorify Thine arising on the third day, * the forgiveness of our sins, * making us worthy to be inhabitants of paradise, ** as Thou alone art compassionate.`,mateTones:[5],sections:[`Aposticha`],others:[{mate:`octoechos:tone5.compline.wed.canon.odes.3.irmos`,mateHash:`m08f6fcbf0024c8`,score:.22,text:`By the power of Thy Cross, O Christ, * do Thou make steadfast mine understanding, * that I may hymn and glorify Thine arising on the third day.`,tones:[5]},{mate:`octoechos:tone5.compline.fri.canon.odes.5.items[2]`,mateHash:`m0f3577d3525f85`,score:.19,text:`Grant me cleansing offenses by thy supplications, O pure Virgin who hast given birth for us to Christ the Lord, our divine Purification.`,tones:[5]},{mate:`octoechos:tone5.great_vespers.aposticha[3]`,mateHash:`m0ded6a7e5e855a`,score:.18,text:`O Lover of mankind, * Who for our sake didst accept to suffer the Passion in the flesh, * and arise from the dead on the third day, * heal the passions of our flesh, * and raise us up from our grievous transgressions, ** and save us.`,tones:[5]}]},o23c154bdff:{mate:`octoechos:tone5.great_vespers.dogmatikon`,mateHash:`m0b1ec834351347`,tone:5,score:.49,next:.18,evidence:[`wording 0.49 (next 0.18)`,`tone 5`,`place: vespers`],first:{doc:`2026-0906-texts-tt`,head:`Tone 5 (Theotokion – Dogmatikon)`},why:[`wording below the bar`],text:`[In] the Red [Sea] of old, | a type of the Virgin Bride was pre[fig]ured. | There [Mo]ses divided the [wa]ters; | here [Ga]briel assisted in the [mir]acle. | There Israel crossed the sea without [get]ting wet, | here the [Vir]gin gave birth to [Christ] without seed. | After [Is]rael’s passage, the sea remained im[pas]sable; | after Emmanuel’s birth, the Virgin remained a [Vir]gin. | O [ev]er-existing God Who didst ap[pear] as Man, // O [Lord], have [mer]cy on us!`,prints:3,dates:[`2026-0906`,`2026-1101`],mateText:`In the Red Sea of old * an image of the Bride who knew not wedlock was depicted. * There Moses was the one who parted the sea, * here Gabriel is the minister of the miracle. * At that time Israel marched dry-shod through the deep, * now the Virgin doth seedlessly give birth to Christ. * The sea after Israel’s passage remained impassable; * the immaculate one after bearing Emmanuel remained incorrupt. * O God, Who doth exist and is pre-eternal, * and hath appeared as man, ** have mercy upon us.`,mateTones:[5],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone5.compline.sun.canon.odes.6.items[0]`,mateHash:`m0b99f111c2feab`,score:.18,text:`Without knowing a man, thou hast given birth to Emmanuel, Who hath taken pity on our lowliness, O Theotokos; wherefore, we ever glorify thee as is meet.`,tones:[5]},{mate:`octoechos:tone5.liturgy.beatitudes.theotokion`,mateHash:`m062ec99206712a`,score:.16,text:`Rejoice, O animate temple of God and impassible gate! Rejoice, O fiery throne which burneth yet is not consumed! Rejoice, O Mother of Emmanuel, Christ our God!`,tones:[5]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.wed_eve_aposticha`,mateHash:`m1d9269c0de1dfc`,score:.13,text:`Thee, the most pure Virgin, who remained so even after giving birth, do we hymn as the Mother of God the Word, saying: Glory to thee!`,tones:[]}]},o24993befba:{mate:`octoechos:tone4.matins_weekday.thu.aposticha_theotokion`,mateHash:`m1af5a55282e434`,tone:4,score:.48,next:.3,evidence:[`wording 0.48 (next 0.3)`,`tone 4`,`place: vespers`],first:{doc:`2026-1113-texts-tt`,head:`Tone 4 (Theotokion)`},why:[`wording below the bar`],text:`O undefiled Theo[to]kos, | we have obtained thee as a wall, a calm harbor and [for]tress; | [there]fore, being tossed as by a storm in [life], we pray: // Guide us and [save] us!`,prints:1,dates:[`2026-1113`],mateText:`Thee have we obtained as a rampart, * O most pure Theotokos, * a favorably calm harbor and confirmation. * Wherefore, I who am tempest-tossed in this life beseech thee: ** do thou guide me and save me!`,mateTones:[4],sections:[`Litya`],others:[{mate:`octoechos:tone4.matins_weekday.fri.canons[1].odes.6.items[1]`,mateHash:`m141af469c702cb`,score:.3,text:`Still the raging waves of my passions and calm the storm of mine evil thoughts, O Ever-virgin, thou calm haven of the tempest-tossed.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.fri.canons[1].odes.3.items[0]`,mateHash:`m02244b78d90554`,score:.29,text:`Have mercy upon me, who am cruelly drowning in the deep of life, O Virgin, and guide me to the calm harbor of salvation; for thee have I acquired as mine only hope.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.wed.canons[0].odes.7.items[3]`,mateHash:`m16a212fab08acf`,score:.26,text:`By your divine sufferings, O glorious spiritual athletes, ye truly cast down the walls of the citadel of deception; and ye have been revealed to be bulwarks and fortresses for the faithful, who piously bless you.`,tones:[4]}]},o26c3fcb4c8:{mate:`menaion:11-16.c0.great_vespers.aposticha_closer`,mateHash:`m1395d578f6d6d3`,tone:6,score:.53,next:.22,evidence:[`wording 0.53 (next 0.22)`,`tone 6`,`place: vespers`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-1101-texts-tt-`,head:`Tone 6 (Theotokion)`},why:[`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`My Maker and Redeemer, [Christ] the Lord, | was born of thee, O most pure [Vir]gin. | By accepting my nature, He freed Adam from his [an]cient curse. | Unceasingly we magnify thee as the [Moth]er of God! | “Rejoice, O ce[les]tial Joy! | Rejoice, O [La]dy: // the Protection, Intercession and Sal[va]tion of our souls!”`,prints:2,dates:[`2026-1101`],mateText:`Christ the Lord, my Creator and Redeemer, * Who came forth from thy womb, O all-pure one, * and clothed Himself in my nature, * hath freed Adam from the primal curse. * Wherefore, like the angel * we unceasingly cry out to thee, * O most pure one, * who art truly the Mother of God and Virgin: * Rejoice!, O Lady, ** the intercession, protection and salvation of our souls!`,mateTones:[6],sections:[`Aposticha`],others:[{mate:`octoechos:tone6.matins_weekday.fri.canons[1].odes.3.items[2]`,mateHash:`m025708b5253803`,score:.22,text:`The condemnation of the ancient curse hath been lifted by thy mediation, O Mother of God; for, having appeared to thee, O most pure one, the Lord hath poured forth all blessings in abundance upon all, in that He is supremely good.`,tones:[6]},{mate:`octoechos:tone6.matins_weekday.tue.canons[1].odes.6.items[3]`,mateHash:`m1b956411d0362f`,score:.19,text:`We now offer unto thee hymnody of thanksgiving, O Virgin; for saved from the ancient curse by thee, O pure one, we produce every blessing like fruit.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.fri_eve_aposticha`,mateHash:`m1112a8d2de94d8`,score:.19,text:`To thee do we pray, as the Mother of God: * O blessed one, ** pray thou for the salvation of our souls!`,tones:[]}]},o2715146096:{mate:`octoechos:tone1.kontakion`,mateHash:`m0dfdd3c4fc75c8`,tone:1,score:.42,next:.23,evidence:[`wording 0.42 (next 0.23)`,`tone 1`],first:{doc:`2026-1004-texts-tt`,head:`Tone 1 Kontakion (Resurrection)`},why:[`wording below the bar`],text:`As [God], Thou didst rise from the tomb in [glo]ry, | raising the [world] with Thyself. | Human [na]ture praises Thee as God, for death has [van]ished. | Adam exults, O [Mas]ter! | Eve re[joic]es, for she is freed from bondage and [cries] to Thee: // “Thou art the Giver of Resurrection to [all], O Christ!”`,prints:2,dates:[`2026-1004`,`2026-1129`],mateText:`Thou didst arise from the grave in glory as God * and thus raised up the world with Thee; * and mortal nature singeth Thy praises as God, * and death hath disappeared; * Adam danceth, O Master, * and now Eve, freed from her chains, * rejoiceth as she cries aloud: ** It is Thee, O Christ, who grantest the Resurrection to all.`,mateTones:[1],sections:[`at the Divine Liturgy`],others:[{mate:`octoechos:tone1.matins.sessionals[1].items[1]`,mateHash:`m14541235d2e6dd`,score:.23,text:`O Life of all, Thou wast nailed to the Cross; * O immortal Lord, Thou wast numbered among the dead, * arising on the third day, O Savior, * raising Adam from corruption; * wherefore the heavenly Powers cried out to Thee: * “O Giver of life, * Glory to Thy sufferings, O Christ; * glory to Thy Resurrection; * glory to Thy condescension, ** O only Lover of mankind.”`,tones:[1]},{mate:`octoechos:shared.evlogitaria.troparia[0]`,mateHash:`m0a3200510c563a`,score:.23,text:`The assembly of angels was amazed, * beholding Thee numbered among the dead; * yet, O Savior, * destroying the stronghold of death, * and with Thyself raising up Adam, ** Thou hast freed all from Hades.`,tones:[]},{mate:`octoechos:tone1.ikos`,mateHash:`m04e22bbb6055f1`,score:.19,text:`Let us praise as God all-powerful the One who hath risen on the third day, smashing the gates of Hades and rousing the age-long dead from the grave, who hath appeared to the myrrh-bearers, as it was His good pleasure to say to them first: Rejoice! and thus revealing joy to the apostles, as alone the Giver of life. Therefore with faith the Women proclaim the tokens of victory to the Disciples; Hades groaneth, Death lamenteth, the world exulteth and all rejoice together; for Thou, O Christ, hast granted the Resurrection to all.`,tones:[1]}]},o2a6328d21b:{mate:`octoechos:tone7.great_vespers.lic[3]`,mateHash:`m0d8402cde657b1`,tone:7,score:.41,next:.19,evidence:[`wording 0.41 (next 0.19)`,`tone 7`,`place: vespers`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (for the Resurrection)`},why:[`wording below the bar`],text:`Thou wast [held] by lawless [men], O Christ, | but to [me], Thou art God, and I am [not] ashamed. | Thou wast [smit]ten on the cheek, but I do not de[ny] Thee. | Thou wast [nailed] to the Cross and I do not con[ceal] it, | for I [glo]ry in Thy Resurrection: Thy [death] is my life. // O almighty Lord and Lover of [man], [glo]ry to Thee!`,prints:2,dates:[`2026-0920`,`2026-1115`],mateText:`Though Thou wast seized by lawless men, O Christ, * yet Thou art my God, and I am not ashamed; * Thy back was scourged, but I do not deny Thee; * Thou wast nailed to a Cross, but I do not hide from Thee. * I make my boast in Thine arising; * for Thy death is my life. ** All-powerful Lord who lovest mankind, glory be to Thee!`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone7.liturgy.beatitudes.troparia[2]`,mateHash:`m128977f6f196d1`,score:.19,text:`Thou didst nail our sins to Cross, O compassionate Christ, and by Thy death Thou didst slay death, O Thou who didst raise up the dead from among the dead. Wherefore, we worship Thy holy Resurrection.`,tones:[7]},{mate:`octoechos:tone7.matins_weekday.sat.praises.items[1]`,mateHash:`m1415579fefd9e1`,score:.17,text:`In the midst of the tribunal of the lawless, the passion-bearers cried aloud rejoicing: ‘O Lord, glory be to Thee.’`,tones:[7]},{mate:`octoechos:tone7.little_vespers.lic[2]`,mateHash:`m1159cc6dbad2a9`,score:.17,text:`Thou didst endure the Cross and burial * for our sake, O Christ, * but as God by Thy death Thou hast slain death; * wherefore we worship Thy Resurrection on the third day. ** O Lord, glory be to Thee!`,tones:[7]}]},o2d79b49132:{mate:`octoechos:tone8.great_vespers.aposticha[1]`,mateHash:`m1f6918495bd785`,tone:8,score:.34,next:.2,evidence:[`wording 0.34 (next 0.2)`,`tone 8`,`place: vespers`],first:{doc:`2026-0927-texts-tt--`,head:`Tone 8 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`We [glo]rify Christ, who [rose] from the dead. | He accepted the human [bod]y and soul, | and freed [both] from [suf]fering. | His most pure soul descended to [hell], which He spoiled. | His holy body did not see cor[rup]tion in the tomb. // He is the Re[deem]er of our souls.`,prints:2,dates:[`2026-0927`,`2026-1122`],mateText:`Let us glorify Christ who hath risen from the dead: * for having taken a body and a soul, * He parted them one from another by the Passion. * For His soul hath descended into Hades, * which He despoiled, while the holy body of the Redeemer of our souls ** knew not corruption in the tomb.`,mateTones:[8],sections:[`Aposticha`],others:[{mate:`octoechos:tone8.nocturns.gregory_rubric.stanzas[0]`,mateHash:`m1d8a8b90b4a78c`,score:.2,text:`It is truly meet to glorify Thee, the Word of God, before Whom the cherubim tremble and quake, and Whom the hosts of heaven glorify. And with fear we glorify Christ, the Bestower of life, Who rose from the tomb on the third day.`,tones:[1,3,4,5,6,7,8]},{mate:`octoechos:tone8.great_vespers.lic[4]`,mateHash:`m1ff85f81403021`,score:.19,text:`We glorify Thy Resurrection from the dead, O Christ, * through which Thou hast freed the race of Adam from the tyranny of Hades, * and as God hast granted the world eternal life ** and great mercy.`,tones:[8]},{mate:`octoechos:tone8.great_vespers.aposticha[2]`,mateHash:`m1cd17222db101c`,score:.19,text:`O Christ, in psalms and hymns we glorify Thy Resurrection from the dead. * For through it Thou hast freed us from the tyranny of Hades, ** and as God Thou hast granted us life eternal, ** and Thy great mercy.`,tones:[8]}]},o2eb624df58:{mate:`octoechos:tone1.matins_weekday.wed.sessionals[1].items[0]`,mateHash:`m08eb568868f088`,tone:1,score:.36,next:.2,evidence:[`wording 0.36 (next 0.2)`,`tone 1`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`],first:{doc:`2026-0901-texts-tt`,head:`Tone 1 Idiomela (for the Indiction, by John the Monk)`},why:[`wording below the bar`],text:`O [Christ] our God, Who in wisdom didst [fash]ion all things, | and out of nothing hast brought them into [be]ing, | bless the [crown] of the year, and preserve our [cit]y unharmed; | and make our faithful [glad] by Thy [pow]er, | granting them [vic]tories over their [ad]versaries, // through the Theotokos bestowing upon the world great [mer]cy!`,prints:1,dates:[`2026-0901`],mateText:`Save O Lord, Thy people, and bless Thine inheritance, grant now unto the faithful victory over adversaries, and by Thy power of Thy Cross, do Thou preserve Thy commonwealth.`,mateTones:[1],sections:[`Aposticha`],others:[{mate:`octoechos:tone1.matins.canon.odes.6.theotokos.troparia[1]`,mateHash:`m097b041ef823e6`,score:.2,text:`The Word, who before was without flesh, and who made the universe by His will, who brought the armies of the Bodiless ones into being out of nothing, as All-powerful, became incarnate from thee, O Most pure one.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.sat.canons[0].odes.3.items[3]`,mateHash:`m1b7f4e54718b4b`,score:.19,text:`O Christ Who of Thine own will and with Thine own hand fashioned man out of the earth, grant the good things of heaven unto all Thy servants who have departed from us with faith.`,tones:[1]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.thu_praises`,mateHash:`m1b41dcaaaa997a`,score:.19,text:`We bless thee, O Virgin Theotokos, * for from thee hath shone forth Christ, * the Sun of righteousness, ** Who hath great mercy.`,tones:[]}]},o2f2d000a1e:{mate:`octoechos:tone5.great_vespers.aposticha_theotokion`,mateHash:`m1f0f29a96aa141`,tone:5,score:.46,next:.25,evidence:[`wording 0.46 (next 0.25)`,`tone 5`,`place: vespers`],first:{doc:`2026-1031-texts-tt`,head:`Tone 5 (Theotokion)`},why:[`wording below the bar`],text:`O most [pre]cious [Vir]gin, | thou art the gate, the [tem]ple, | the [pal]ace, the [throne] of the King. | From [thee], my Redeemer, [Christ] the Lord, | appeared to those asleep in [dark]ness. | [He] is the Sun of [Right]eousness, | Who de[sired] to enlighten His image, whom He had cre[at]ed. | Since thou dost possess motherly boldness before Him, O all-praised [La]dy, // pray un[ceas]ingly that our [souls] may be saved!`,prints:1,dates:[`2026-1031`],mateText:`Thou art the temple and portal, * the palace and throne of the King, * O most honored Virgin, * through whom Christ the Lord, my Redeemer, * Who is the Sun of righteousness, * hath revealed Himself unto those who sleep in darkness, * deigning to enlighten those * whom He hath fashioned in His image by His own hand. * Wherefore, O all-hymned one, * as thou hast acquired a mother’s boldness before Him, ** entreat Him without ceasing, that our souls be saved.`,mateTones:[5],sections:[`Aposticha`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.4.fri_eve_aposticha`,mateHash:`m14d9987158a54b`,score:.25,text:`O thou inextinguishable lamp, * and throne of righteousness * most pure Sovereign Lady: * pray thou that our souls be saved.`,tones:[]},{mate:`octoechos:tone5.compline.tue.canon.odes.4.items[2]`,mateHash:`m14ecd8a51da6a2`,score:.19,text:`Hearken unto the entreaty of the lowly who place their hope in thee O Theotokos, hasten to deliver us, since thou hast a mother's boldness.`,tones:[5]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.thu_praises`,mateHash:`m09e64eab57ba01`,score:.17,text:`Ineffably wast Thou born of the Virgin, O Christ, * and Thou hast enlightened those who are in darkness and cry aloud: ** O Lord, glory be to Thee!`,tones:[]}]},o316fddff3d:{mate:`menaion:11-22.c0.vespers.lic[0]`,mateHash:`m12b0ffc8fa19f4`,tone:8,score:.31,next:.18,evidence:[`wording 0.31 (next 0.18)`,`tone 8`,`place: vespers`,`melody “O most glorious wonder ...”`,`same date`],first:{doc:`2026-1122-texts-tt`,head:`Tone 8 (for the Feast) (Oh, most glorious wonder)`},why:[`wording below the bar`,`a second hymn is close`],text:`Oh, most [glo]rious [won]der! | The ineffable that is [come] to pass | is now this day pre[fig]ured be[fore]hand. | That which is apprehended spiritually is seen in visible [fig]ures, | for she who will shine the divine [Light] to the world | is led as a bride to the [Tem]ple where [God] dwells. | Let us praise her as the ever-shining [tem]ple // of the Godhead of Christ, the [Giv]er of Light!`,prints:1,dates:[`2026-1122`],mateText:`O most glorious wonder, * the ineffable future * is now described beforehand, * understood today in visible images; * for she who shone forth the divine light upon the world * is led like a bride into the holy temple. * Let us praise her as the most resplendent temple, * holy and radiant, ** of Christ God, the Bestower of life.`,mateTones:[8],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone8.matins_weekday.tue.canons[1].odes.5.irmos`,mateHash:`m0e0413be444db3`,score:.18,text:`Out of the night of ignorance * hath the day of divine knowledge dawned, * in the light O Christ, of Thy countenance. * May Thy praise shine forth in our hearts * like the light of the dawn.`,tones:[8]},{mate:`octoechos:tone8.vespers_weekday.thu.lic.menaion_fallback[0]`,mateHash:`m0fbd98bca96e58`,score:.16,text:`O the ineffable goodness of Him * Who became incarnate from thee, O all- hymned Theotokos! * For He Who is the Lover of mankind * endured the Cross and death, * that He might save what He created. * Entreat Him, that He may deliver me from torment, * the wretched one who am greatly sick, * and cause me to dwell ** where the never-waning light shines.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.wed.canons[0].odes.7.items[3]`,mateHash:`m0e315bb7b26872`,score:.15,text:`Sanctified, ye have come to dwell amid the splendors of the saints, O divine martyrs, sending down upon all who praise you, sanctification and deliverance; wherefore they sing unto Christ: Blessed is the God of our fathers!`,tones:[8]}]},o34e795a5f7:{mate:`octoechos:tone6.great_vespers.aposticha[2]`,mateHash:`m0889438f7931f6`,tone:6,score:.44,next:.21,evidence:[`wording 0.44 (next 0.21)`,`tone 6`,`place: vespers`],first:{doc:`2026-0913-texts-tt`,head:`Tone 6 (for the Resurrection)`},why:[`wording below the bar`],text:`Desiring to return us to [Par]adise, | Christ was nailed to the Cross and [placed] in a tomb. | The Myrrhbearing Women sought Him with tears, [cry]ing, | “Woe to us, O [Sav]ior! | How dost Thou deign to de[scend] to death? | What place can hold Thy life bearing [bod]y? | Come to us as Thou didst [prom]ise! | Take away our [wail]ing and tears!” | Then the Angel ap[peared] to them: | “Stop your lamen[ta]tions! | Go, proclaim to the A[pos]tles: | ‘The Lord is [ris]en, // granting us purification and great [mer]cy!’”`,prints:2,dates:[`2026-0913`,`2026-1108`],mateText:`Wishing to restore us from our ancient fall, * Christ wast nailed to a Cross and placed in a tomb. * The myrrh-bearing women, as they sought Him with tears, said, lamenting: * Alas, O Savior of all, how is it that Thou deigned to dwell in a tomb? * How is it, that Thou who willingly dwelt there, hast been stolen? * How is it that Thou hast been moved? * What place hath hidden Thy life-bearing body? * O Master, as Thou hast promised, * do Thou appear unto us, and bring to an end our grieving and our tears. * But as they lamented an angel cried unto them saying: * End your lament! Go and tell the apostles that the Lord hath risen, ** granting the world pardon and great mercy.`,mateTones:[6],sections:[`Aposticha`],others:[{mate:`octoechos:tone6.matins.sessionals[0].items[0]`,mateHash:`m13029ee91a65ce`,score:.21,text:`While the tomb lay open and Hades lamented, * Mary, cried unto the apostles who were in hiding saying: * “Come forth, ye workers of the vineyard, * proclaim unto the world the word of the Resurrection, * for the Lord is risen, ** granting the world His great mercy!”`,tones:[6]},{mate:`octoechos:tone6.liturgy.beatitudes.troparia[4]`,mateHash:`m11910d61671ee2`,score:.17,text:`Myrrh-bearing women came to the grave and heard an angel cry aloud, “Christ hath risen, enlightening all things.”`,tones:[6]},{mate:`octoechos:tone6.matins.praises.stichera[2]`,mateHash:`m090ad8b18cd499`,score:.16,text:`With the Father and the Spirit * let us hymn Christ risen from the dead, * and let us cry out to Him: ** “Thou art our Life and Resurrection, have mercy upon us.”`,tones:[6]}]},o3790c6ce7c:{mate:`octoechos:tone2.nocturns.canon.odes.9.irmos`,mateHash:`m1695200f416687`,tone:2,score:.5,next:.34,evidence:[`wording 0.5 (next 0.34)`,`tone 2`,`place: matins`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 9 – Heirmos`},why:[`wording below the bar`],text:`From thy virgin womb thou ineffably gavest a body | to the Light that was before the sun, | even God Who has shone forth upon us, | and in the body came to dwell among us. // Blessed and all-pure Theotokos, we magnify thee!`,prints:1,dates:[`2026-0908`],mateText:`Thee do we magnify, O blessed and all-pure Theotokos, * who through thy virginal womb ineffably brought forth * God incarnate, * the Luminary Who shone forth before the sun * and hath come to us in the flesh.`,mateTones:[2],sections:[`Gospel`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.5.thu_praises`,mateHash:`m1b41dcaaaa997a`,score:.34,text:`We bless thee, O Virgin Theotokos, * for from thee hath shone forth Christ, * the Sun of righteousness, ** Who hath great mercy.`,tones:[]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.5.mon_lauds`,mateHash:`m1e2d1ad57bc117`,score:.27,text:`O Christ God, * Who hath shone forth upon the world from the Virgin * and shown us forth as children of the light: ** have mercy upon us!`,tones:[]},{mate:`octoechos:tone2.matins.canon.odes.1.theotokos.troparia[2]`,mateHash:`m00d473f698483c`,score:.26,text:`The Sun of righteousness came through the sealed and untrodden gateway of thy womb, O pure one, and hath thus shone upon the world: for gloriously hath He been glorified.`,tones:[2]}]},o3bf4aaf8c3:{mate:`octoechos:tone1.vespers_weekday.tue.aposticha.items[0]`,mateHash:`m148ac0bb4b2cb8`,tone:1,score:.44,next:.2,evidence:[`wording 0.44 (next 0.2)`,`tone 1`,`place: vespers`,`NAMES DIFFER: our text names Golgotha; the OCA text does not`],first:{doc:`2026-1204-texts-tt`,head:`Tone 1 (Prosomia of the Cross, from the Octoechos)`},why:[`wording below the bar`,`our text names Golgotha; the OCA text does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`The [Cross] was planted on the [place] of the skull, | and from the e[ter]nal spring | that [flowed] from the side of the [Sav]ior; // it blossomed for us the flower of immor[tal]ity!`,prints:1,dates:[`2026-1204`],mateText:`The Cross was set up on Golgotha, and hath blossomed forth immortality for us from the ever-flowing fountain of the Savior’s side.`,mateTones:[1],sections:[`Aposticha`],others:[{mate:`octoechos:tone1.matins_weekday.fri.canons[0].odes.5.items[2]`,mateHash:`m1745ed7795d781`,score:.2,text:`Ye were shown to be like a divinely planted garden of paradise, O martyrs, having your honored sufferings as fragrant flowers, whereby the soul of each of the faithful is filled with sweet fragrance.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.sat.canons[1].odes.6.items[1]`,mateHash:`m01325b0265a20c`,score:.18,text:`O Christ Who hast redeemed the world by the Blood which flowed from Thy side, by Thy precious sufferings deliver those who have fallen asleep in faith, for Thou didst offer Thyself as a ransom for all mankind.`,tones:[1]}]},o3c250499d3:{mate:`octoechos:tone7.great_vespers.lic[6]`,mateHash:`m06d947ab457be0`,tone:7,score:.51,next:.36,evidence:[`wording 0.51 (next 0.36)`,`tone 7`,`place: vespers`],first:{doc:`2026-1115-texts-tt-`,head:`Tone 7 (for the Resurrection)`},why:[`a second hymn is close`],text:`Thou wast [placed] in the tomb, O Lord, as [one] asleep! | On the [third] day Thou didst rise in [pow]er, | raising [Ad]am with Thyself from the cor[rup]tion of death // [as] the Al[might]y One.`,prints:1,dates:[`2026-1115`],mateText:`Thou wast laid in a tomb, O Lord, as One who sleepeth * and Who hast arisen on the third day as One mighty in strength, * raising with Thyself Adam from the corruption of death, ** as One All-powerful.`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone7.great_vespers.aposticha[3]`,mateHash:`m1e92a30623fea5`,score:.36,text:`Fearful didst Thou appear, O Lord, as Thou lay in the tomb as One sleeping; * and having arisen on the third day as All-powerful * Thou hast raised Adam together with Thyself, who cried aloud: ** “Glory to Thy Resurrection, O only Lover of mankind.”`,tones:[7]},{mate:`octoechos:tone7.great_vespers.aposticha[2]`,mateHash:`m135402a528bb81`,score:.32,text:`Having descended into Hades O Christ, Thou hast despoiled death, * and by rising on the third day, Thou hast raised us also together with Thyself, * wherefore we glorify Thine all-powerful arising. ** O Lord, glory be to Thee!`,tones:[7]},{mate:`octoechos:tone7.liturgy.beatitudes.troparia[4]`,mateHash:`m19b4446d1b2e79`,score:.3,text:`Thou wast laid in the tomb as one dead, O Christ, Thou Life of all; and Thou didst break down the gates of Hades; and having risen again in glory on the third day as One almighty, Thou hast illumined all. Glory to Thine arising!`,tones:[7]}]},o3c78cce60e:{mate:`octoechos:tone5.liturgy_weekday.sat.beatitudes.items[1]`,mateHash:`m125e46a00c038d`,tone:null,score:.31,next:.25,evidence:[`wording 0.31 (next 0.25)`,`tone not printed on one side`,`NAMES DIFFER: the OCA text names Zion; ours does not`],first:{doc:`2026-0914-texts-tt`,head:`The Second Antiphon`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Zion; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Remember Mount Zion, where Thou hast dwelt! (Ps. 73:3b) (Refrain)`,prints:1,dates:[`2026-0914`],mateText:`Dying, O martyrs, ye destroyed the enemy, the author of evil, and, crowned with divine victories, ye mounted on high, where ye stand before God, the King of all.`,mateTones:[5],sections:[`The Second Antiphon`],others:[{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.8.items[4]`,mateHash:`m19a196ac93c3f6`,score:.25,text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tones:[1,2,3,4,5,6,7,8]},{mate:`octoechos:tone3.matins.anabathmoi[0].troparia[0]`,mateHash:`m1e33ff26e83049`,score:.23,text:`Thou, O Word, didst deliver the captivity of Zion from Babylon, * deliver me also ** from the passions unto life.`,tones:[3]},{mate:`octoechos:tone8.little_vespers.lic[3]`,mateHash:`m1555eb9ddb8928`,score:.2,text:`Rejoice holy Zion, * Mother of the Churches, * dwelling-place of God; * for it was thee who first received forgiveness of sins ** through the Resurrection.`,tones:[8]}]},o3d6c0ff508:{mate:`menaion:11-26.c1.matins.psalm50_sticheron`,mateHash:`m1f7dbc0b675f0e`,tone:null,score:.36,next:.34,evidence:[`wording 0.36 (next 0.34)`,`tone not printed on one side`,`place: matins`],first:{doc:`2026-1027-texts-alaska-tt`,head:`Magnification`},why:[`wording below the bar`,`a second hymn is close`],text:`We magnify thee, | O holy and righteous Mother Olga, | and we honor thy holy memory, | O healer of those in afflictions | and loving intercessor before the merciful God.`,prints:1,dates:[`2026-1027`],mateText:`Let my mouth be filled with Thy praise, O Lord, that I may hymn the glory of Thy saint, whom Thou hast glorified with incorruption and the working of wonders, whom Thou hast revealed to be a helper for those who are amid misfortunes, a quick healer for the afflicted, a comforter amid sorrows, and a fervent intercessor for those who honor his holy memory.`,mateTones:[6],sections:[`Magnification`],others:[{mate:`menaion:09-05.c1.matins.megalynarion`,mateHash:`m052bc3e4504d1f`,score:.34,text:`We magnify you, O holy and righteous Zacharias and Elizabeth, and we honor your holy memory; for ye entreat Christ our God on our behalf.`,tones:[]},{mate:`menaion:11-26.c1.matins.megalynarion`,mateHash:`m0ce9de4e81553c`,score:.31,text:`We magnify thee, O hierarch, Father Innocent, and honor thy holy memory, for thou dost pray for us unto Christ our God.`,tones:[]},{mate:`octoechos:tone7.compline.tue.canon.odes.6.irmos`,mateHash:`m1a03b16d9e5289`,score:.22,text:`I cried out to Thee, O Lord, when I was afflicted, * and Thou didst raise up my life, * O greatly Merciful One.`,tones:[7]}]},o3eac07e65a:{mate:`menaion:11-16.c0.great_vespers.aposticha_closer`,mateHash:`m1395d578f6d6d3`,tone:6,score:.53,next:.22,evidence:[`wording 0.53 (next 0.22)`,`tone 6`,`place: vespers`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-0925-texts-tt`,head:`Tone 6 (Theotokion)`},why:[`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`My Maker and Redeemer, [Christ] the Lord, | was born of thee, O most pure [Vir]gin. | By accepting my nature, He freed Adam from his [an]cient curse. | Unceasingly we magnify thee as the [Moth]er of God! | Rejoice, O ce[les]tial Joy! | Rejoice, O [La]dy: // the Protection, Intercession and Sal[va]tion of our souls!`,prints:4,dates:[`2026-0925`,`2026-0926`,`2026-1006`,`2026-1009`],mateText:`Christ the Lord, my Creator and Redeemer, * Who came forth from thy womb, O all-pure one, * and clothed Himself in my nature, * hath freed Adam from the primal curse. * Wherefore, like the angel * we unceasingly cry out to thee, * O most pure one, * who art truly the Mother of God and Virgin: * Rejoice!, O Lady, ** the intercession, protection and salvation of our souls!`,mateTones:[6],sections:[`Litya`,`Aposticha`],others:[{mate:`octoechos:tone6.matins_weekday.fri.canons[1].odes.3.items[2]`,mateHash:`m025708b5253803`,score:.22,text:`The condemnation of the ancient curse hath been lifted by thy mediation, O Mother of God; for, having appeared to thee, O most pure one, the Lord hath poured forth all blessings in abundance upon all, in that He is supremely good.`,tones:[6]},{mate:`octoechos:tone6.matins_weekday.tue.canons[1].odes.6.items[3]`,mateHash:`m1b956411d0362f`,score:.19,text:`We now offer unto thee hymnody of thanksgiving, O Virgin; for saved from the ancient curse by thee, O pure one, we produce every blessing like fruit.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.fri_eve_aposticha`,mateHash:`m1112a8d2de94d8`,score:.19,text:`To thee do we pray, as the Mother of God: * O blessed one, ** pray thou for the salvation of our souls!`,tones:[]}]},o41b1cea1a6:{mate:`menaion:11-30.c0.matins.exapostilarion_glory`,mateHash:`m0b87057637cb64`,tone:2,score:.39,next:.37,evidence:[`wording 0.39 (next 0.37)`,`tone not printed on one side`,`same date`],first:{doc:`2026-1130-texts-tt`,head:`Tone 2 Kontakion`},why:[`wording below the bar`,`a second hymn is close`],text:`Let us praise [An]drew, the [her]ald of God, | the namesake of [cour]age, | the first-[called] of the Savior’s dis[ci]ples | and the brother of [Pe]ter! | As he once [called] to his [broth]er, | he now cries [out] to us: // “Come, for we have found the [One] Whom the [world] desires!”`,prints:1,dates:[`2026-1130`],mateText:`Most gloriously let us praise the apostle Andrew, the brother of Peter, the first of all the disciples, the beholder and servant of Him Who is the Word, for he hath enlightened the nations and, crucified, met his end as a disciple of the Master.`,mateTones:[],sections:[`at the Divine Liturgy`],others:[{mate:`menaion:11-30.c0.kontakion`,mateHash:`m05a25eb541af52`,score:.37,text:`The divinely eloquent namesake of manliness, * the eminent follower of the Church, * the kinsman of Peter, let us praise, * for as of old he was called, so now he calleth us: ** Come ye, we have found the Desired One!`,tones:[2]},{mate:`octoechos:tone2.vespers_weekday.tue.aposticha.items[0]`,mateHash:`m024984abe08372`,score:.18,text:`O Christ God my Savior, Who saved Peter in the sea, save me by the power of the Cross, and have mercy on me.`,tones:[2]},{mate:`menaion:11-30.c0.matins.exapostilarion_closer`,mateHash:`m056047490d0473`,score:.16,text:`O all-immaculate Virgin, with Andrew the first-called entreat God, to Whom thou hast given birth, on behalf of all who piously honor thee, that we may receive the splendor of thy Son and a place to stand with the elect and all the saints; for what thou dost wish, thou canst do.`,tones:[]}]},o425e9f5b11:{mate:`octoechos:tone4.great_vespers.dogmatikon`,mateHash:`m13ec200d417e2d`,tone:4,score:.36,next:.18,evidence:[`wording 0.36 (next 0.18)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (Theotokion – Dogmatikon)`},why:[`wording below the bar`],text:`The Prophet David was a [fa]ther of the Lord | through thee, O [Vir]gin. | He fore[told] in songs the One Who worked [won]der in thee: | “At Thy right hand [stood] the Queen,” | Thy Mother, the medi[at]rix of life, | since God was freely born of her without a [fa]ther. | He wanted to renew His fallen image, made corrupt in [pas]sion, | so He took the lost sheep up[on] His [shoul]der | and brought it to His [Fa]ther, | joining it to the [heav]enly pow’rs. // Christ, Who has great and rich mercy, has saved the world, O Theo[to]kos.`,prints:3,dates:[`2026-0830`,`2026-1025`,`2026-1031`],mateText:`Prophet David, the ancestor of God, * spoke of thee in psalmody unto Him Who hath accomplished great things in thee. * For God was well pleased without father to become a man from thee, * the Queen who standeth at His right hand, * and He - the source of life - showed thee to be His mother, * that He might renew His own image, corrupted by the passions. * Having found the lost sheep wandering on the mountain * He hath laid it upon His shoulders, * that He may bring it to his Father; * and in accordance with His own will * unite it to the heavenly powers * and thus, O Theotokos, save the world, ** Christ, Who is richly and abundantly merciful.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-15.c0.matins.canons[0].odes.9.items[0]`,mateHash:`m0666112e8e1a9d`,score:.18,text:`Following the godly and divinely inspired words of Christ, O divinely radiant confessors, rejoicing, ye took the cross upon your shoulders, following in the steps of the Bestower of life, O right glorious ones.`,tones:[4]},{mate:`octoechos:tone4.little_vespers.lic[0]`,mateHash:`m14bb89f283361f`,score:.18,text:`Unceasingly worshiping Thy life-giving Cross, O Christ God, * we glorify Thy Resurrection on the third day, * for through it, O all-powerful One, * Thou hast renewed corrupted human nature * and shown us the way to heaven, ** since Thou alone art good and the Lover of mankind.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.tue.sessionals[2].closer`,mateHash:`m0ebb51e0fe993f`,score:.17,text:`By thy divine birthgiving, O pure one, * thou hast renewed the mortal nature of those born on earth, * which had become corrupt through the passions, * raising up all from death to a life of incorruption. * Wherefore, as is meet we all bless thee, ** O most glorious Virgin, as thou didst foretell.`,tones:[4]}]},o42885caa9a:{mate:`menaion:11-21.c0.great_vespers.litiya[2]`,mateHash:`m1c9bf93a1b3713`,tone:4,score:.45,next:.28,evidence:[`wording 0.45 (next 0.28)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 4 (by George of Nicomedia)`},why:[`wording below the bar`],text:`Come, all [peo]ples, | let us praise her who alone is without [blem]ish, | who was pro[claimed] by the prophets and now is offered in the [Tem]ple: | the Mother foreordained before the [a]ges, | who in the last days has been shown forth as [The]o[to]kos. | By her inter[ces]sions, O Lord, // grant us Thy peace and great [mer]cy!`,prints:1,dates:[`2026-1121`],mateText:`Come, all ye faithful, let us praise her who alone is immaculate, who was proclaimed beforehand by the prophets, and is brought into the temple, the Mother chosen before all ages, the Theotokos who hath appeared in the latter days. O Lord, through her supplications grant us Thy peace and great mercy.`,mateTones:[4],sections:[`Litya`],others:[{mate:`menaion:11-29.c0.matins.canons[0].odes.8.items[3]`,mateHash:`m1e08862373db86`,score:.28,text:`The shadow of the law and the proclamations of the prophets foreordained thee, O pure one full of the grace of God, as her who would ineffably become the Mother of our God. To Him do we all chant: Bless the Lord, all ye works of the Lord!`,tones:[4]},{mate:`menaion:09-07.c0.vespers.aposticha_closer`,mateHash:`m0d74971d682a6f`,score:.19,text:`Universal joy hath shone forth upon us from the righteous Joachim and Anna, O all-praised Virgin who, in thine exceeding purity, didst become the animate temple of God, and who alone art truly known to be the Theotokos. Through her prayers, O Christ God, grant peace unto the world and great mercy unto our souls.`,tones:[4]},{mate:`menaion:12-02.c0.matins.canons[0].odes.8.items[3]`,mateHash:`m07a1c30e346f5c`,score:.17,text:`Thou wast truly shown to be the Mother of Him Who shone forth from the Father before all ages; for thou alone wast more holy than all others. Thee, the pure one, do we supremely exalt throughout the ages!`,tones:[4]}]},o4364775dc2:{mate:`octoechos:tone8.matins_weekday.sat.sessionals[1].items[2]`,mateHash:`m026f5e22737e2c`,tone:8,score:.34,next:.19,evidence:[`wording 0.34 (next 0.19)`,`tone 8`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-1024-texts-tt`,head:`Tone 8 Troparion`},why:[`wording below the bar`,`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Thou only Cre[a]tor Who, with [wis]dom profound, mercifully orderest [all] things, | and givest [that] which is [use]ful to [all] men: | Give rest, O [Lord], to the [souls] of Thy servants who have [fall]en asleep, // for they have [placed] their [trust] in Thee, our Maker and [Fash]ioner, and our God.`,prints:2,dates:[`2026-1024`],mateText:`O Thou Who by the depth of Thy wisdom dost provide all things out of love for mankind, and grantest unto all that which is profitable, O only Creator: Grant rest, O Lord, to the souls of Thy servants; for in Thee have they placed their hope, O Creator and Fashioner and God.`,mateTones:[8],sections:[`at Vespers`,`at the Divine Liturgy`],others:[{mate:`octoechos:tone8.matins_weekday.sat.canons[0].odes.7.items[3]`,mateHash:`m057dd3cd22c525`,score:.19,text:`Grant rest, O Christ, unto the souls of all who have fallen asleep in the hope of life, in Thy great loving-kindness overlooking the offenses they committed in this life, O only compassionate Savior. O God of our fathers, blessed art Thou!`,tones:[8]},{mate:`octoechos:tone8.vespers_weekday.tue.lic.menaion_fallback[0]`,mateHash:`m0466fa747cf16c`,score:.17,text:`“I cannot bear to see Thee Who givest wakefulness to all, asleep upon the Tree, that Thou mightest give divine and saving watchfulness to those who have fallen into pernicious sleep through the fruit of disobedience!”, said the Virgin, whom we magnify, weeping.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.fri.aposticha_theotokion`,mateHash:`m11f745e0b63b70`,score:.17,text:`“I cannot bear to see Thee asleep upon the Tree, Who givest wakefulness to all, that Thou mightest give divine and saving watchfulness to those who have fallen into most pernicious sleep through the fruit of disobedience!”, the Virgin, whom we magnify, said, weeping.`,tones:[8]}]},o471cfcf177:{mate:`octoechos:tone8.matins_weekday.sat.sessionals[1].closer`,mateHash:`m0a26b86e5aec82`,tone:8,score:.39,next:.28,evidence:[`wording 0.39 (next 0.28)`,`tone 8`,`PLACE DIFFERS: OCA prints it at vespers/liturgy, the mate is at matins`],first:{doc:`2026-1024-texts-tt`,head:`Tone 8 Theotokion`},why:[`wording below the bar`,`a second hymn is close`],text:`We have thee [as] a [wall] and a [hav]en | and an inter[ces]sor well-[pleas]ing to God, Whom [thou] [hast] borne, // O Virgin [The]o[to]kos, the salvation of the [faith]ful.`,prints:2,dates:[`2026-1024`],mateText:`In thee we have a rampart and a haven and an intercessor acceptable to God, Whom thou didst bear, O Theotokos unwedded, salvation of the faithful.`,mateTones:[8],sections:[`at Vespers`,`at the Divine Liturgy`],others:[{mate:`octoechos:tone8.matins_weekday.mon.canons[1].odes.7.items[2]`,mateHash:`m04592cec279359`,score:.28,text:`Having thee as a haven of salvation, O Virgin Theotokos, we flee the tribulations and tumults of life, crying out to thy Son: O God of our fathers, blessed art Thou!`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.mon.canons[1].odes.1.items[2]`,mateHash:`m1971623606c3b8`,score:.26,text:`Be thou a refuge, haven, bulwark and intercessor for me, O Virgin Mother of God, who hast given birth in the flesh unto God, the all- compassionate Redeemer.`,tones:[8]},{mate:`octoechos:tone8.little_vespers.lic[2]`,mateHash:`m1c6f1e2b3793d4`,score:.26,text:`O Lord, cast us not away * from Thy presence; * but be well-pleased to have mercy on us ** through the Resurrection.`,tones:[8]}]},o481ec81363:{mate:`menaion:11-30.c0.matins.canons[1].odes.7.items[1]`,mateHash:`m13ab1e4d96688e`,tone:1,score:.3,next:.24,evidence:[`wording 0.3 (next 0.24)`,`tone 1`],first:{doc:`2026-0914-texts-tt`,head:`Tone 1 Troparion`},why:[`wording below the bar`,`a second hymn is close`],text:`The Lord is great in Zion; He is exalted over all the people. (Ps. 98:2)`,prints:1,dates:[`2026-0914`],mateText:`Commanded to ascend the mountain of the noetic Zion, O apostle, and having passed over death to divine life, rejoicing, thou dost bestow the cup of salvation of the praised and supremely glorious God of our fathers, having received it within thyself.`,mateTones:[1],sections:[`The Third Antiphon`],others:[{mate:`octoechos:tone1.little_vespers.lic[2]`,mateHash:`m0e5f960ef9d44a`,score:.24,text:`Go around Zion, O ye peoples, * and encompass her, * and give glory to him who in her midst hath arisen from the dead; * for he is our God, ** and hath delivered us from our iniquities.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.wed.sessionals[1].items[0]`,mateHash:`m08eb568868f088`,score:.23,text:`Save O Lord, Thy people, and bless Thine inheritance, grant now unto the faithful victory over adversaries, and by Thy power of Thy Cross, do Thou preserve Thy commonwealth.`,tones:[1]},{mate:`menaion:11-21.c0.matins.canons[1].odes.1.katavasia`,mateHash:`m0662436b3ce570`,score:.23,text:`Christ is born, render ye glory. * Christ cometh from heaven, meet ye Him. * Christ is on earth, be ye exalted. * O all the earth, sing unto the Lord, * and sing praises in gladness, O ye people, * for He hath been glorified.`,tones:[1]}]},o482237acae:{mate:`menaion:11-21.c0.great_vespers.aposticha_closer`,mateHash:`m0a1c1abe2992cb`,tone:6,score:.34,next:.2,evidence:[`wording 0.34 (next 0.2)`,`tone 6`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 6 (by Sergius of Jerusalem)`},why:[`wording below the bar`,`a second hymn is close`],text:`Today let us, the crowds of the assembled [faith]ful, | celebrate a [spir]itual feast: | let us reverently praise the Virgin Theotokos and [child] of God, | as she is brought into the [Tem]ple of the Lord! | She was forechosen from all gener[at]ions | to be the dwelling-place of Christ, the Lord and [God] of all. | O Virgins, bearing lamps, go be[fore] her, | honoring the majestic advance of the ever-[Vir]gin! | Mothers, lay aside every sorrow and ac[com]pany them with joy, | singing the praises of her who became the [Moth]er of God, | the cause of [joy] for the world! | Therefore, let us all join with the [an]gel, | and joyfully cry out: “Rejoice!” to her who is [full] of grace, // and who ever inter[cedes] for our souls.`,prints:2,dates:[`2026-1121`,`2026-1125`],mateText:`Assembling today, ye councils of the faithful, let us keep spiritual festival, and let us piously praise the divine maiden, the Virgin Theotokos, who is led into the temple of the Lord, she who was chosen before out of all generations to be the habitation of Christ God, the King of all. Bearing candles, O virgins, go ye on before, doing homage to the honored entry of the Ever-virgin! Ye mothers, setting aside all grief, follow joyously her who is to become the Mother of God, the mediatress of joy for the world! And with the angel let us all joyfully cry out to the joyous one “Rejoice!”, for she ever prayeth for our souls.`,mateTones:[6,4],sections:[`Aposticha`],others:[{mate:`menaion:11-21.c0.matins.psalm50_sticheron`,mateHash:`m05f97e70532aec`,score:.2,text:`Today the Theotokos, the temple who contained God, was led into the temple of the Lord, and Zachariah received her. Today the Holy of holies rejoiceth, and the choir of angels keepeth mystic festival. And with them we also, celebrating today, cry out with Gabriel: Rejoice, O thou who art full of grace, the Lord is with thee, Who hath great mercy!`,tones:[6]},{mate:`menaion:11-20.c0.matins.exapostilarion_closer`,mateHash:`m02b0fd33007169`,score:.2,text:`The temple doth now observe a day of pre-festival for the most pure entrance of Mary, the Theotokos, whom the angels hymn and we call blessed, and whom is accompanied by virgins, bearing lamps and rejoicing, into the temple of the Lord.`,tones:[]},{mate:`menaion:09-06.c0.vespers.lic_closer`,mateHash:`m08cd29ddac2e8e`,score:.19,text:`Rejoice with us, all ye choirs of virgins, for our intercessor, mediator, protection and great refuge doth today on her divine and honored feast comfort the sorrowful. Wherefore, hymning her at length as is meet, let us cry aloud: Protect us with thy divine intercession, O most pure Lady Theotokos!`,tones:[6]}]},o490759cc3d:{mate:`menaion:11-29.c0.vespers.lic_closer`,mateHash:`m1ea1966baac850`,tone:4,score:.5,next:.19,evidence:[`wording 0.5 (next 0.19)`,`tone 4`,`place: vespers`],first:{doc:`2026-0926-texts-tt`,head:`Tone 4 (Theotokion)`},why:[`wording below the bar`],text:`The Son, Who with the Father and the Spirit is [glo]rified | by the Cherubim in the [high]est, | de[sired] to refashion the [first]-created man. | He ineffably emptied Himself into thy womb, O all-praised Theo[to]kos, | and shining forth from thee, He enlightened the whole [world] with His [God]head, | delivering it from the folly of [id]ols. | Making human nature divine in Himself, He joined it to [heav]en. // He is Christ our God and the [Sav]ior of our souls.`,prints:1,dates:[`2026-0926`],mateText:`The Son who together with the Father and the Spirit * is glorified in the highest by the seraphim, * wishing to refashion the First-formed man, * ineffably emptied His entire being into thy womb, * O all-praised Theotokos. * Dawning forth from thee * He hath enlightened the whole world * by His Godhead, * delivering it from the deception of idolatry, * and by this He hath rendered * the race of mankind divine, * having raised it on high to the heavens; ** Christ God the Savior of our souls.`,mateTones:[4],sections:[`Litya`],others:[{mate:`octoechos:tone4.little_vespers.aposticha.theotokos[1]`,mateHash:`m0cda385fd5f801`,score:.19,text:`Thou didst hold in thy womb, O divinely blessed one, * the incarnate Creator of all things * as He refashioned mankind, * which through the serpent had once fallen by the transgression. * For thou hast given birth ineffably to our God in the flesh, * and through thy birthgiving thou hast freed from corruption, * the nature of that which had become corrupt. * Therefore we praise and glorify thy grace, * O Virgin unwedded, ** cease not to intercede that our souls may be saved.`,tones:[4]},{mate:`octoechos:tone4.liturgy.beatitudes.troparia[4]`,mateHash:`m0f277e20f22950`,score:.18,text:`For our sakes the Impassible became a man, subject to suffering, and willingly nailed on the Cross He hath raised us with Himself; therefore with the Cross we also glorify the Passion and Resurrection, through which we have been refashioned, and through which we are saved, as we cry, “Remember us also in Thy kingdom.”`,tones:[4]},{mate:`octoechos:tone4.nocturns.canon.odes.5.items[3]`,mateHash:`m12ef319ab270a9`,score:.17,text:`Upon beholding him who of old had become corrupt, He Who created us in His image, and revealed the divine form therein, desired to deify us, and through thee became a man, proclaiming the one, triune Godhead.`,tones:[4]}]},o4b4b822948:{mate:`octoechos:tone6.great_vespers.aposticha_theotokion`,mateHash:`m09f0055241cbfd`,tone:6,score:.54,next:.21,evidence:[`wording 0.54 (next 0.21)`,`tone 6`,`place: vespers`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-1027-texts-alaska-tt`,head:`Tone 6 (Theotokion)`},why:[`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`My Maker and Redeemer, [Christ] the Lord, | came forth from thy womb, O all-[pure] one: | by being clothed with me, he freed Adam from the [an]cient curse. | Wherefore, O Theo[to]kos, | to thee, the true Mother of God and [Vir]gin, | we, together with Saint Olga of A[las]ka, | unceasingly cry out with the angel's [greet]ing: | “Rejoice, O [full] of grace! | Rejoice, O [La]dy, // Protection, Shelter, and Sal[va]tion of our souls!”`,prints:2,dates:[`2026-1027`],mateText:`Christ the Lord, my Creator and Redeemer, * Who came forth from thy womb, O most pure one, * and clothed Himself in my nature, * hath freed Adam from the primal curse. * Wherefore, like the angel * we unceasingly cry out to thee, O all-pure one, * who art truly the Mother of God and Virgin: * Rejoice!, O Sovereign Lady, ** the intercession, protection and salvation for our souls!`,mateTones:[6],sections:[`The Praises Tone 1`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.5.sun_vespers_mon_matins`,mateHash:`m03060fcf9364e0`,score:.21,text:`O Theotokos, thou who art of heaven with the angels * and of the earth with mankind, * we cry out to thee with a call of joy: * Rejoice, gate wider than the heavens! * Rejoice, thou who alone art the salvation of those born on earth! * Rejoice, O pure one, full of grace, ** who hast given birth unto God incarnate.`,tones:[]},{mate:`octoechos:tone6.matins_weekday.fri.canons[1].odes.3.items[2]`,mateHash:`m025708b5253803`,score:.19,text:`The condemnation of the ancient curse hath been lifted by thy mediation, O Mother of God; for, having appeared to thee, O most pure one, the Lord hath poured forth all blessings in abundance upon all, in that He is supremely good.`,tones:[6]},{mate:`octoechos:tone6.matins.canon.odes.1.resurrection.closer`,mateHash:`m1aa2cdb82c87ad`,score:.19,text:`Having received thy Maker ineffably incarnate within thy seedless womb, as He Himself hath willed, thou hast been revealed, O pure one, as truly the Sovereign Lady of all creation.`,tones:[6]}]},o4d4caa6619:{mate:`octoechos:tone2.vespers_weekday.wed.lic.menaion_fallback[0]`,mateHash:`m1a6e72d6410548`,tone:2,score:.4,next:.16,evidence:[`wording 0.4 (next 0.16)`,`tone 2`,`place: vespers`],first:{doc:`2026-1206-texts-tt`,head:`Tone 2 (for St. Nicholas) (Joseph of Arimathea)`},why:[`wording below the bar`],text:`O Nicholas, living in [My]ra, | thou wast anointed with [spir]itual myrrh, | and wast re[vealed] to be truly myrrh, O [bish]op of Christ. | Thou makest fragrant with myrrh those who keep thy memorial with [faith] and love, | freeing them from misery, danger and af[flic]tion, // by thine intercessions to Christ, O holy [Fa]ther.`,prints:1,dates:[`2026-1206`],mateText:`Having lived bodily in Myra, * thou wast truly revealed to be myrrh; * and, anointed with noetic myrrh, * O holy Nicholas, hierarch of Christ, * thou didst spread the sweet-smelling fragrance of immortality * upon those who with faith have recourse to thy protection, * releasing them from perils, * misfortunes and tribulations ** by thy supplications to the Lord, O father.`,mateTones:[2],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone2.matins_weekday.thu.canons[1].odes.6.items[0]`,mateHash:`m1bcea4c270ed9a`,score:.16,text:`O Nicholas, primate of the people of Myra, with thy good works thou didst perfume the assemblies of the faithful. Deliver me from fetid transgressions.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.wed.canons[1].odes.5.items[3]`,mateHash:`m08a07760b10c70`,score:.16,text:`As thou art our intercessor, salvation and the hope of Christians, O Lady, save those who ever hymn thee with faith and love, O all-hymned Virgin.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.thu.canons[1].odes.9.items[1]`,mateHash:`m0ffa60c0890fa9`,score:.15,text:`As a most sacred vessel deemed worthy of the divine Myrrh which is mercifully poured forth upon the earth, perfume the hearts of us all, O wise one who wast the chief hierarch of the people of Myra, dispelling the stench of temptation by thy supplications.`,tones:[2]}]},o4dd669295d:{mate:`menaion:09-07.c0.matins.exapostilarion_closer`,mateHash:`m0301afa8291593`,tone:null,score:.7,next:.31,evidence:[`wording 0.7 (next 0.31)`,`tone not printed on one side`,`place: matins`,`NAMES DIFFER: our text names Mary; the OCA text does not`],first:{doc:`2026-0908-texts-tt`,head:`2nd Exapostilarion Tone 2`},why:[`our text names Mary; the OCA text does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Be renewed, O Adam, and be magnified, O Eve, | you prophets dance with the apostles and the righteous; | let there be common joy in the world among angels and mankind. // For the Theotokos is born today of righteous Joachim and Anna.`,prints:1,dates:[`2026-0908`],mateText:`Be renewed, O Adam, and be thou magnified, O Eve! Ye prophets, join chorus with the apostles and the righteous! For the common joy of angels and mortals hath shone forth today from the righteous Joachim and Anna: Mary the Theotokos.`,mateTones:[],sections:[`2nd Exapostilarion Tone 2`],others:[{mate:`menaion:09-08.c0.little_vespers.aposticha[0]`,mateHash:`m0a139934c0a9b2`,score:.31,text:`Rejoice, O Joachim and Anna! * Rejoice, for the Virgin, * the Mediatress of joy and salvation * is born unto us ** from a barren woman!`,tones:[2]},{mate:`menaion:11-24.c0.matins.aposticha[4]`,mateHash:`m10c041aaf5928b`,score:.26,text:`Good was the sacred * and divine union * of Joachim and Anna, * from whom the pure one was born ** who hath now been brought to her Creator.`,tones:[2]},{mate:`menaion:09-08.c0.little_vespers.aposticha[4]`,mateHash:`m1e283ceaf674bf`,score:.25,text:`Put away all grief, * O Adam and Eve; * for the Mother of Joy * springeth forth today most gloriously ** from a barren woman.`,tones:[2]}]},o4e5b856b0e:{mate:`menaion:09-08.c0.great_vespers.lic[4]`,mateHash:`m15a284e756b3a3`,tone:6,score:.49,next:.24,evidence:[`wording 0.49 (next 0.24)`,`tone 6`,`place: vespers`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 6 Idiomela (by Stephen of Jerusalem)`},why:[`wording below the bar`],text:`Today is the prelude of uni[ver]sal joy; | today the winds blow that herald sal[va]tion, | and the barrenness of our [na]ture is dispelled; | for the barren woman is revealed as the [moth]er | of her who remained a [vir]gin | after giving birth to the Cre[at]or. | From her the One Who is God by [na]ture | takes what is foreign to Him and [makes] it His own, | and works salvation through the flesh for those who have [gone] astray. // He is Christ, the Lover of man and the Re[deem]er of our souls.`,prints:1,dates:[`2026-0908`],mateText:`Today is the pronouncement of universal joy! Today the winds have blown which herald salvation, and our nature is released from barrenness! For the barren woman is shown to be the mother of her who remaineth virgin even after giving birth to the Creator, from whom God taketh upon Himself that which is alien to Him by nature, and Christ, the Redeemer of our souls, the Lover of mankind, doth accomplish salvation for the lost by means of flesh.`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`menaion:11-28.c0.compline.canon.odes.4.items[4]`,mateHash:`m1553a39ccd880d`,score:.24,text:`Thou didst remain a Virgin after giving birth, as thou wast before giving birth, O all-immaculate one, for thou hast given birth to God the Word Who hath delivered us through thy mediation.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.wed_eve_aposticha`,mateHash:`m1d9269c0de1dfc`,score:.23,text:`Thee, the most pure Virgin, who remained so even after giving birth, do we hymn as the Mother of God the Word, saying: Glory to thee!`,tones:[]},{mate:`menaion:09-08.c0.great_vespers.lic[3]`,mateHash:`m001d0bd1ac83b7`,score:.21,text:`Today the gateway of the barren woman hath been opened, and the divine Virgin portal cometh forth! Today grace beginneth to bear fruit, revealing to the world the Mother of God, through whom those on earth are united to those in heaven, for the salvation of our souls.`,tones:[6]}]},o4ebe4fff12:{mate:`octoechos:tone4.compline.sat.canon.odes.3.items[2]`,mateHash:`m1199ca19586fdb`,tone:null,score:.35,next:.3,evidence:[`wording 0.35 (next 0.3)`,`tone not printed on one side`],first:{doc:`2026-0914-texts-tt`,head:`The First Antiphon`},why:[`wording below the bar`,`a second hymn is close`],text:`God, my God, attend to me! Why hast Thou forsaken me? (Ps. 21:1a)`,prints:1,dates:[`2026-0914`],mateText:`Attend unto the voice of thy servant who am in need of thy help, O Mother of God. O my hope, hearken unto me and rescue me from perils!`,mateTones:[4],sections:[`The First Antiphon`],others:[{mate:`menaion:11-23.c0.matins.canons[1].odes.4.items[1]`,mateHash:`m0a58f804fe9c5b`,score:.3,text:`As an attendant of the Church, the bride in Christ, O God-bearer, thou didst adorn her with the beauty of thy discourses and render her radiant with the comeliness of Orthodoxy.`,tones:[4]},{mate:`menaion:11-19.c0.matins.canons[0].odes.4.items[2]`,mateHash:`m0763585240ebf6`,score:.26,text:`Thou wast revealed to be like a wedding attendant of the Church, the Bride of Christ, O all-blessed one, proclaiming that the Savior would come forth from Zion, to Whom we cry aloud: Glory to Thy power, O Lord!`,tones:[5]},{mate:`octoechos:tone5.compline.wed.canon.odes.1.items[3]`,mateHash:`m04f3ff1f5e3930`,score:.26,text:`Why hast thou wasted all thy life in great despondency, O my soul? Wherefore, hasten thou and cry out to the Mother of the Lord: Cleanse thou and save me, O Birthgiver of God!`,tones:[5]}]},o4f51eb74c3:{mate:`octoechos:tone3.little_vespers.lic[0]`,mateHash:`m186246a64faf76`,tone:3,score:.41,next:.27,evidence:[`wording 0.41 (next 0.27)`,`tone 3`,`place: vespers`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`By Thy Cross, O Christ our [Sav]ior, | death’s dominion has been [shat]tered; | the devil’s de[lu]sion destroyed. | The race of man, being [saved] by faith, // always [of]fers [Thee] a song.`,prints:2,dates:[`2026-0823`,`2026-1018`],mateText:`By Thy Cross, O Christ our Savior, * the dominion of death hath been abolished, * the devil’s deception hath been dispelled, * while mankind, saved by faith, ** each evening offers hymns unto Thee.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_vespers_wed_matins`,mateHash:`m005c8e536cdc0c`,score:.27,text:`Christ God Who wast crucified for us and destroyed the dominion of death, * do thou unceasingly entreat, O Virgin Theotokos, ** that He save our souls.`,tones:[]},{mate:`octoechos:tone3.matins.anabathmoi[1].troparia[1]`,mateHash:`m04786d708fa1bf`,score:.23,text:`The saints, O Christ, fruits of the womb, * are by the Spirit, always sons to Thee, ** as Thou art to the Father.`,tones:[3]},{mate:`octoechos:tone3.matins.sessionals[0].items[0]`,mateHash:`m0a1d0adce59d7f`,score:.21,text:`Christ hath arisen from the dead, * the first fruits of those that sleep. * The first-born of creation * and Creator of all that hath come to be, * hath renewed in Himself the corrupted nature of our race. * Death, no longer art thou lord, ** for the Master of all things hath destroyed thy dominion.`,tones:[3]}]},o50aa811d8f:{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.8.items[4]`,mateHash:`m19a196ac93c3f6`,tone:null,score:.38,next:.26,evidence:[`wording 0.38 (next 0.26)`,`tone not printed on one side`],first:{doc:`2026-0914-texts-tt`,head:`The First Antiphon`},why:[`wording below the bar`,`a second hymn is close`],text:`Refrain: Through the prayers of the Theotokos, O Savior, save us!`,prints:1,dates:[`2026-0914`],mateText:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,mateTones:[1,2,3,4,5,6,7,8],sections:[`The First Antiphon`],others:[{mate:`octoechos:tone7.matins_weekday.mon.aposticha_theotokion`,mateHash:`m06e6b96f390223`,score:.26,text:`Through the prayers of the Theotokos, * grant peace to the life of us who cry unto Thee: ** O merciful Lord, glory be to Thee!`,tones:[7]},{mate:`menaion:11-25.c0.matins.canons[1].odes.8.items[3]`,mateHash:`m1f854352d5d189`,score:.25,text:`O Mary, Virgin Theotokos, who for our sake hast given birth to God the Savior in the flesh: Save those who hymn thy birthgiving with faith and supremely exalt thee throughout all ages.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.sat.canons[1].odes.8.items[3]`,mateHash:`m0924fb79f6bf71`,score:.25,text:`O Virgin Mary, Theotokos, who hast given birth in the flesh to God, the Savior of mankind: Save those who with faith hymn and supremely exalt thine Offspring throughout all ages.`,tones:[8]}]},o515d87dd81:{mate:`menaion:11-22.c0.vespers.lic[1]`,mateHash:`m17df918dccc8f4`,tone:8,score:.49,next:.24,evidence:[`wording 0.49 (next 0.24)`,`tone 8`,`place: vespers`,`melody “O most glorious wonder ...”`,`same date`],first:{doc:`2026-1122-texts-tt`,head:`Tone 8 (for the Feast) (Oh, most glorious wonder)`},why:[`wording below the bar`],text:`The wise [Jo]achim, together with [An]na, | have brought the godly maiden, the Virgin [Ma]ry, | as a truly ac[cept]able [first] fruit | to Him Who had given her to them as a di[vine] fruit, | through Whom the debt of grief has been [driv]en away. | Let us praise her in [songs] and de[vout]ly rejoice, // for she is become the provider of joy to [all] the world!`,prints:1,dates:[`2026-1122`],mateText:`Truly the wise Joachim and Anna * have manifestly offered * their right acceptable first-fruits, * the Virgin Mary, the divine maiden, * unto Him Who willed to grant her to them as a divine fruit, * whereby the debt of grief hath been cancelled. * In gladness let us piously hymn her, * for she hath been made the mediatress of joy ** for all the world.`,mateTones:[8],sections:[`Lord I Call...`],others:[{mate:`menaion:09-08.c0.ikos`,mateHash:`m0cf6c0c14be734`,score:.24,text:`The supplication of Joachim over his childlessness, together with the sighing of Anna over her barrenness, were right acceptable to God: they entered the ears of the Lord and brought forth life-bearing fruit for the world. For the one made supplication on the mountain, and the other bore her reproach in the garden; and with joy the barren woman giveth birth to the Theotokos, the nurturer of our Life.`,tones:[]},{mate:`menaion:11-21.c0.matins.sessional_polyeleos[0]`,mateHash:`m12174d329228af`,score:.21,text:`Let David the psalmist rejoice, and let Joachim and Anna join chorus, for the radiant Mary, the divine lamp, issued forth from them like a holy fruit, and she rejoiceth, entering the temple. Beholding her, the son of Barachiah blessed her, and, rejoicing; cried aloud: “Rejoice, O wonder of the world!”`,tones:[8]},{mate:`menaion:09-08.c0.matins.exapostilarion_closer`,mateHash:`m18509298ffbb80`,score:.19,text:`Be thou renewed, O Adam! Be thou magnified, O Eve! Join ye chorus with the apostles and the righteous! For Mary the Theotokos, the common joy of the angels and mortals, hath shone forth today from the righteous Joachim and Anna.`,tones:[]}]},o5192221a5d:{mate:`menaion:11-21.c0.great_vespers.aposticha[0]`,mateHash:`m047c986a1399f0`,tone:5,score:.48,next:.17,evidence:[`wording 0.48 (next 0.17)`,`tone 5`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 5 (Rejoice, O Life-giving Cross)`},why:[`wording below the bar`],text:`[Heav]en and [earth] rejoice, | beholding the spiritual Heaven, the only Virgin without [blem]ish, | as she [en]ters the house of God, there to be reared in [rev]erence. | Zacha[ri]ah cried to her in a[maze]ment: | “O Gate of the Lord, to thee I open the gates of the [Tem]ple; | re[joice] and go around it [danc]ing. | For I [know] and believe that the deliverance of [Is]rael | will now come to dwell [o]penly in our midst, | and that from [thee] shall be born [God] the Word, // Who grants the [world] His great [mer]cy!”`,prints:2,dates:[`2026-1121`,`2026-1125`],mateText:`Rejoice, O heaven and earth, beholding the only immaculate Virgin, the noetic heaven, coming forth to be raised in honor in the house of God! To her Zachariah cried out, marveling: “O portal of the Lord, I open unto thee the gates of the temple! Rejoice therein, joining chorus! For I have come to know and believe that the deliverance of Israel is manifestly coming, and that God the Word will be born through thee, granting the world great mercy!”`,mateTones:[5],sections:[`Aposticha`],others:[{mate:`octoechos:tone5.little_vespers.lic_theotokion`,mateHash:`m124d16fa94b004`,score:.17,text:`Let us honor the God-worthy and honorable maiden, * more honorable than the cherubim. * For the Creator of all things, having deigned to become a man * ineffably made His abode within her. * O strangest of deeds and wondrous mysteries! * Who would not be amazed upon hearing that God hath become a man? * Yet there was no change in Him, * having passed through the gates of virginity without diminishing it, * as the prophet hath said; * No man shall ever pass through this gate, ** except the Lord, the God of Israel, who hath great mercy.`,tones:[5]},{mate:`octoechos:tone5.matins_weekday.mon.sessionals[1].closer`,mateHash:`m0eea342e299dd0`,score:.14,text:`O Theotokos, thou who art of heaven with the angels * and of the earth with mankind, * we cry out to thee with a call of joy: * Rejoice, gate wider than the heavens! * Rejoice, thou who alone art the salvation of those born on earth! * Rejoice, O pure one, full of grace, * who hast given birth unto God incarnate.`,tones:[5]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.5.sun_vespers_mon_matins`,mateHash:`m03060fcf9364e0`,score:.14,text:`O Theotokos, thou who art of heaven with the angels * and of the earth with mankind, * we cry out to thee with a call of joy: * Rejoice, gate wider than the heavens! * Rejoice, thou who alone art the salvation of those born on earth! * Rejoice, O pure one, full of grace, ** who hast given birth unto God incarnate.`,tones:[]}]},o5384973565:{mate:`octoechos:tone2.matins_weekday.tue.canons[1].odes.9.irmos`,mateHash:`m0252c5288d21bf`,tone:2,score:.52,next:.46,evidence:[`wording 0.52 (next 0.46)`,`tone 2`,`place: matins`],first:{doc:`2026-1027-texts-alaska-tt`,head:`Tone 2 Ode 9 – Heirmos`},why:[`a second hymn is close`],text:`The Son of the Father without beginning, | God the Lord, has appeared to us | made flesh of a Virgin, | to give light to what is darkened | and to gather together what is scattered: | therefore we magnify the all-praised Theotokos.`,prints:2,dates:[`2026-1027`],mateText:`The beginningless Son of God the Father and the Lord, * became flesh from the Virgin, * to give light to those in darkness, * and to gather the dispersed. * Wherefore we magnify the all-hymned Theotokos!`,mateTones:[2],sections:[`Ikos`],others:[{mate:`octoechos:tone2.matins.canon.odes.9.irmos`,mateHash:`m15e0108dc8d7c0`,score:.46,text:`The Son of the beginningless Father, God and Lord, * hath appeared to us incarnate of a virgin, * to enlighten those in darkness, * and to gather the dispersed; * therefore the all-hymned Theotokos do we magnify`,tones:[2]},{mate:`octoechos:tone2.liturgy_weekday.wed.beatitudes.items[4]`,mateHash:`m16e11ff5de0aae`,score:.24,text:`Let the beginningless Father, the Son Who is equally without beginning, and the Holy Spirit, be hymned in one worship and glory.`,tones:[2]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.1.mon_vespers_tue_matins`,mateHash:`m14ffde8906cea1`,score:.19,text:`Thou hast conceived the divine Fire without being consumed, * and dist give birth without seed to the Lord the Source of life: * O Theotokos full of grace ** save thou those who magnify thee!`,tones:[]}]},o5619a5fd1c:{mate:`octoechos:tone4.troparion`,mateHash:`m0a39354a4ff70a`,tone:4,score:.44,next:.19,evidence:[`wording 0.44 (next 0.19)`,`tone 4`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 Troparion (Resurrection)`},why:[`wording below the bar`],text:`When the women dis[ci]ples of the Lord | learned from the angel the joyous message of Thy Resur[rec]tion, | they cast away the an[ces]tral curse | and elatedly told the a[pos]tles: | “[Death] is overthrown! | Christ God is [ris]en, // granting the world great [mer]cy!”`,prints:4,dates:[`2026-0830`,`2026-1025`],mateText:`Having learned the joyful proclamation of the Resurrection from the angel, * and having cast off the ancestral condemnation, * the women disciples of the Lord spake exultantly to the apostles: * “Death is despoiled and Christ God is risen, ** granting the world great mercy.`,mateTones:[4],sections:[`at Great Vespers`,`at the Divine Liturgy`],others:[{mate:`octoechos:tone4.matins.sessionals[1].items[0]`,mateHash:`m14b1e265832c0e`,score:.19,text:`O Savior, Thou didst rise from Hades as immortal, * raising the world together with Thee by Thy might O Christ our God. * With strength hast Thou overthrown the dominion of death, * revealing the Resurrection to all O merciful One. ** Wherefore we also glorify Thee, O only Lover of mankind.`,tones:[4]},{mate:`octoechos:tone4.matins.hypakoe`,mateHash:`m03d386f13ecb95`,score:.17,text:`The myrrh-bearing women hastened to proclaim to the apostles * the news of Thy wondrous rising, O Christ: * that as God Thou hast arisen, ** granting the world great mercy.`,tones:[4]},{mate:`menaion:11-18.c0.matins.canons[1].odes.9.items[2]`,mateHash:`m14c3199f3251d9`,score:.16,text:`O Virgin, thou hast delivered mortals from the primal curse of our ancestors, and opened unto us the life of Eden by thy birthgiving, which transcendeth nature. Wherefore, in gladness we magnify thee, O Theotokos.`,tones:[4]}]},o564d0f5f19:{mate:`octoechos:tone2.matins_weekday.wed.canons[0].odes.5.items[0]`,mateHash:`m067e71e6453f5a`,tone:2,score:.33,next:.26,evidence:[`wording 0.33 (next 0.26)`,`tone 2`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`],first:{doc:`2026-0920-texts-tt`,head:`Tone 2 (for the Feast, from the Vespers Aposticha) (O House of Ephratha)`},why:[`wording below the bar`,`a second hymn is close`],text:`Ex[alt]ing the Cross, | along with the [spear] and the nails | and [all] by [which] | Christ’s life-bearing [Bod]y was pierced; // let us [wor]ship Him!`,prints:1,dates:[`2026-0920`],mateText:`Nailed to the Cross, Thou didst shake the foundations of the earth; and pierced by the spear, Thou didst slay the serpent, the author of evil, pouring forth streams of salvation upon all, O Christ.`,mateTones:[2],sections:[`Litya`],others:[{mate:`octoechos:tone2.matins_weekday.fri.canons[0].odes.1.items[4]`,mateHash:`m142b2ab3155f23`,score:.26,text:`The word of the honorable prophet hath been fulfilled, for a sword pierced thy heart, O Lady, when thou didst see thy Son nailed to the Cross.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.fri.canons[0].odes.4.items[0]`,mateHash:`m0ef71ee904a32a`,score:.25,text:`Thou wast suspended upon the Tree, O Almighty, Who suspended the earth upon the waters; and, pierced in the side by a spear, Thou didst pour forth blood and water for the salvation of all.`,tones:[2]},{mate:`octoechos:tone2.compline.thu.canon.odes.4.items[1]`,mateHash:`m0539efde958485`,score:.24,text:`Disdain me not, who has been pierced by the sword of pleasure and lie in my wounds, O most pure one, but heal me with the spear and blood of thy crucified Son and our God.`,tones:[2]}]},o56ea40b09c:{mate:`octoechos:tone7.great_vespers.dogmatikon`,mateHash:`m14efb184c59dd4`,tone:7,score:.39,next:.26,evidence:[`wording 0.39 (next 0.26)`,`tone 7`,`place: vespers`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (Theotokion – Dogmatikon)`},why:[`wording below the bar`,`a second hymn is close`],text:`No [tongue] can speak of thy wonderful [child]bearing, | for the [or]der of nature was over[ruled] by God. | Thou wast re[vealed] to be a Mother above [na]ture, | for thou didst re[main] a Virgin beyond reason and under[stand]ing. | Thy con[cep]tion was most glorious, O Theo[to]kos! | The [man]ner of thy giving birth was ineffable, O [Vir]gin! | [Know]ing thee to be the [Mothe]r of God, | de[vout]ly we [pray] to thee: // “Be[seech] Him to [save] our souls!”`,prints:3,dates:[`2026-0920`,`2026-0926`,`2026-1115`],mateText:`Thou hast been known to have become a mother * in a manner surpassing nature O Theotokos, * and hast remained a virgin in a manner beyond all telling and understanding; * no tongue can expound the wonder of thy birthgiving. * For while thy conceiving O pure one, was most glorious, * the manner of thy birthgiving transcends comprehension; * for where God so willeth, the order of nature is overthrown. * Wherefore, we all, knowing thee to be the Mother of God, * do earnestly entreat thee: ** Pray thou that our souls be saved!`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.1.fri_eve_aposticha`,mateHash:`m1c8a5d9eec4f7a`,score:.26,text:`Truly wondrous beyond understanding * are the mighty works of thy birthgiving O Bride of God, * of which all the prophets proclaimed, * and thy conception and birth giving are most glorious, * O all-hymned one, * whereby thine Offspring hath incomprehensibly and ineffably saved the world, ** in that He is merciful.`,tones:[]},{mate:`octoechos:tone7.matins_weekday.mon.canons[1].odes.4.items[3]`,mateHash:`m0747f8b826e2ce`,score:.24,text:`O all-hymned and most pure Mother of God, who ineffably hast given birth unto God: We beseech thee: Pray that we be saved.`,tones:[7]},{mate:`octoechos:tone7.compline.mon.canon.odes.4.items[3]`,mateHash:`m104c91afa6802e`,score:.21,text:`We hymn thee who even after giving birth didst remain a virgin, O most pure one, and we glorify thee as the Mother of our God.`,tones:[7]}]},o58b437deda:{mate:`octoechos:tone7.great_vespers.lic[5]`,mateHash:`m0738f5ce7d2d23`,tone:7,score:.5,next:.42,evidence:[`wording 0.5 (next 0.42)`,`tone 7`,`place: vespers`],first:{doc:`2026-1115-texts-tt-`,head:`Tone 7 (for the Resurrection)`},why:[`a second hymn is close`],text:`Thou didst des[cend] into hell as Thou didst [will], O Christ, | over[throw]ing death as God and rising on the third day as [Mas]ter! | With Thy[self] Thou didst raise Adam from the bonds of hell and from cor[rup]tion! // Glory to Thy Resur[rec]tion, O only [Lov]er of man!`,prints:1,dates:[`2026-1115`],mateText:`By willingly descending into Hades O Christ, * Thou didst despoil death, * and by arising on the third day as God and Lord, * Thou didst raise together with Thyself from the bonds and corruption of Hades, * those who cried aloud: “Glory to Thine all-powerful Resurrection. ** O Lord, glory be to Thee!”`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone7.great_vespers.aposticha[2]`,mateHash:`m135402a528bb81`,score:.42,text:`Having descended into Hades O Christ, Thou hast despoiled death, * and by rising on the third day, Thou hast raised us also together with Thyself, * wherefore we glorify Thine all-powerful arising. ** O Lord, glory be to Thee!`,tones:[7]},{mate:`octoechos:tone7.great_vespers.aposticha[3]`,mateHash:`m1e92a30623fea5`,score:.32,text:`Fearful didst Thou appear, O Lord, as Thou lay in the tomb as One sleeping; * and having arisen on the third day as All-powerful * Thou hast raised Adam together with Thyself, who cried aloud: ** “Glory to Thy Resurrection, O only Lover of mankind.”`,tones:[7]},{mate:`octoechos:tone7.little_vespers.lic[2]`,mateHash:`m1159cc6dbad2a9`,score:.3,text:`Thou didst endure the Cross and burial * for our sake, O Christ, * but as God by Thy death Thou hast slain death; * wherefore we worship Thy Resurrection on the third day. ** O Lord, glory be to Thee!`,tones:[7]}]},o5ca2673a31:{mate:`octoechos:tone1.little_vespers.lic[2]`,mateHash:`m0e5f960ef9d44a`,tone:1,score:.32,next:.26,evidence:[`wording 0.32 (next 0.26)`,`tone 1`,`place: vespers`],first:{doc:`2026-1004-texts-tt`,head:`Tone 1 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`En[cir]cle [Zi]on | and surround her, O [peo]ple! | Give [glo]ry in her to the One Who [rose] from the dead! | For [He] is [our] God, // Who has delivered us from our trans[gres]sions!`,prints:2,dates:[`2026-1004`,`2026-1129`],mateText:`Go around Zion, O ye peoples, * and encompass her, * and give glory to him who in her midst hath arisen from the dead; * for he is our God, ** and hath delivered us from our iniquities.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`menaion:09-06.c0.liturgy.beatitudes[0]`,mateHash:`m08121bc734eb87`,score:.26,text:`With divine might dost thou encircle all the earth, O all-praised chief among the angels, rescuing us that call upon thy divine name from the cruel enemy.`,tones:[]},{mate:`octoechos:tone1.compline.fri.canon.odes.3.items[0]`,mateHash:`m12e7d950d6c358`,score:.18,text:`The darkness of transgressions surroundeth my heart, O Lady, and I dare not lift up mine eyes to heaven. Wherefore, I cry: Enlighten my mind, soul and heart with the precepts of Christ!`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.fri.canons[0].odes.9.items[2]`,mateHash:`m07a5dfb5b08859`,score:.17,text:`To the light of Thine ineffable glory and radiance didst Thou guide those who rose at dawn unto Thee, and who, led by Thy hand, traversed the darkness of sufferings, O Christ, Thou never-setting Sun. Wherefore, by their supplications enlighten us.`,tones:[1]}]},o63636dacb3:{mate:`octoechos:tone7.little_vespers.lic[0]`,mateHash:`m18ae1a4dff8afd`,tone:7,score:.71,next:.29,evidence:[`wording 0.71 (next 0.29)`,`tone 7`,`place: vespers`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (for the Resurrection)`},why:[`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`[Come], let us re[joice] in the Lord, | Who de[stroyed] the do[min]ion of death! | Let us [sing] to Him with the [bod]iless hosts, | for He en[light]ened the [race] of man! // O our Maker and [Sav]ior, [glo]ry to Thee!`,prints:2,dates:[`2026-0920`,`2026-1115`],mateText:`O Come, let us rejoice in the Lord * who hath destroyed the dominion of death * and enlightened the race of mankind, * as we cry aloud with the bodiless powers: ** “Our Creator and Savior, glory be to Thee!”`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_vespers_wed_matins`,mateHash:`m005c8e536cdc0c`,score:.29,text:`Christ God Who wast crucified for us and destroyed the dominion of death, * do thou unceasingly entreat, O Virgin Theotokos, ** that He save our souls.`,tones:[]},{mate:`octoechos:tone7.matins.sessionals[0].closer`,mateHash:`m188a0ca54480f7`,score:.23,text:`O Virgin Theotokos * unceasingly entreat Christ our God, * who wast crucified for us * and arose again destroying the dominion of death, ** that He save our souls.`,tones:[7]},{mate:`octoechos:tone7.matins_weekday.wed.sessionals[1].items[1]`,mateHash:`m0bf489f63e9f04`,score:.22,text:`O Christ God, Who hast dominion over the incorporeal hosts and knowest the slothfulness of my soul, save me by Thy Cross, in that Thou lovest mankind.`,tones:[7]}]},o64552a55f1:{mate:`octoechos:tone7.great_vespers.aposticha[3]`,mateHash:`m1e92a30623fea5`,tone:7,score:.39,next:.3,evidence:[`wording 0.39 (next 0.3)`,`tone 7`,`place: vespers`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`When [Thou] wast placed in the tomb as [one] asleep, | the [sight] was great and [awe]some. | But when [Thou] didst rise on the third day as al[might]y God, | [Thou] didst resurrect [Ad]am with Thyself. // Glory to Thy Resur[rec]tion, only [Lov]er of man!`,prints:2,dates:[`2026-0920`,`2026-1115`],mateText:`Fearful didst Thou appear, O Lord, as Thou lay in the tomb as One sleeping; * and having arisen on the third day as All-powerful * Thou hast raised Adam together with Thyself, who cried aloud: ** “Glory to Thy Resurrection, O only Lover of mankind.”`,mateTones:[7],sections:[`Aposticha`],others:[{mate:`octoechos:tone7.matins.canon.odes.3.cross_resurrection.troparia[1]`,mateHash:`m11974acd5d49bf`,score:.3,text:`Thou didst arise from the tomb on the third day making life dawn forth upon all the world, as the giver of life and as God; do Thou establish my mind to do Thy will, O only Lover of mankind.`,tones:[7]},{mate:`octoechos:tone7.great_vespers.lic[6]`,mateHash:`m06d947ab457be0`,score:.3,text:`Thou wast laid in a tomb, O Lord, as One who sleepeth * and Who hast arisen on the third day as One mighty in strength, * raising with Thyself Adam from the corruption of death, ** as One All-powerful.`,tones:[7]},{mate:`octoechos:tone7.liturgy.beatitudes.troparia[4]`,mateHash:`m19b4446d1b2e79`,score:.28,text:`Thou wast laid in the tomb as one dead, O Christ, Thou Life of all; and Thou didst break down the gates of Hades; and having risen again in glory on the third day as One almighty, Thou hast illumined all. Glory to Thine arising!`,tones:[7]}]},o6669637697:{mate:`menaion:09-07.c0.vespers.aposticha_closer`,mateHash:`m0d74971d682a6f`,tone:4,score:.5,next:.42,evidence:[`wording 0.5 (next 0.42)`,`tone 4`,`place: vespers`],first:{doc:`2026-0908-texts-tt`,head:`Tone 4 Idiomela (by Patriarch Germanus)`},why:[`a second hymn is close`],text:`The joy of all the world has dawned for us from the [right]eous ones: | the all-praised Virgin who springs from Joachim and [An]na. | Through the a[bun]dance of goodness she becomes the living [tem]ple of God, | and she alone is acknowledged as truly the Theo[to]kos. | Through her [prayers], O [Christ] God, // send peace to the world and to our souls great [mer]cy!`,prints:1,dates:[`2026-0908`],mateText:`Universal joy hath shone forth upon us from the righteous Joachim and Anna, O all-praised Virgin who, in thine exceeding purity, didst become the animate temple of God, and who alone art truly known to be the Theotokos. Through her prayers, O Christ God, grant peace unto the world and great mercy unto our souls.`,mateTones:[4],sections:[`Aposticha`],others:[{mate:`menaion:09-08.c0.great_vespers.aposticha[0]`,mateHash:`m04fa0d56632a1d`,score:.42,text:`The joy of the whole world hath shone forth upon us from the righteous Joachim and Anna: the most laudable Virgin who, because of her surpassing purity, hath become the animate temple of God and is known as the one true Theotokos. Through her prayers, O Christ God, send down peace upon the world and great mercy upon our souls.`,tones:[4]},{mate:`menaion:09-08.c0.great_vespers.aposticha[2]`,mateHash:`m0b77fbec8862a4`,score:.25,text:`In accordance with the angel’s prophecy, thou didst issue forth from the righteous Joachim and Anna, as a most pure fruit, heaven and the throne of God, a receptacle of purity, heralding forth joy to all the world, O Virgin, mediatress of our life, removal of the curse, bestowal of blessing. Wherefore, on the feast of thy nativity, O divinely called Virgin, ask peace for the world and great mercy for our souls.`,tones:[4]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.thu_praises`,mateHash:`m1b41dcaaaa997a`,score:.21,text:`We bless thee, O Virgin Theotokos, * for from thee hath shone forth Christ, * the Sun of righteousness, ** Who hath great mercy.`,tones:[]}]},o6985a21da8:{mate:`octoechos:tone3.compline.sun.canon.odes.5.items[0]`,mateHash:`m08312827ffc4e4`,tone:3,score:.34,next:.22,evidence:[`wording 0.34 (next 0.22)`,`tone 3`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 (Theotokion – Dogmatikon)`},why:[`wording below the bar`,`a second hymn is close`],text:`The highest Powers of heaven were also present with their Master,`,prints:1,dates:[`2026-0823`],mateText:`As our deliverance, thy Son hath delivered all from corruption, O Virgin; wherefore, deliver me from a carnal understanding and from the presence of the passions.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone3.matins_weekday.fri.canons[1].odes.5.items[2]`,mateHash:`m17d7868718de3a`,score:.22,text:`O pure Virgin, who hast given peace to the world and salvation to all, in that with fear and love, thou hast given birth to divine Peace; Christ the Savior, bring an end to the present aggression of the passions of my soul and body.`,tones:[3]},{mate:`octoechos:tone3.matins.canon.odes.7.theotokos.troparia[0]`,mateHash:`m1f55fdd5f84f37`,score:.21,text:`O Lord of glory and ruler of the powers on high, Thou who art seated with the Father and wast carried in the arms of the Virgin; “Blessed art Thou, O Lord, the God of our fathers.”`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.wed.canons[1].odes.5.items[1]`,mateHash:`m1c886d08d2e905`,score:.19,text:`Full of every sin, O Virgin, I now present thee as my mediatress and advocate before Him Who was born from thee. Be thou the surety and correction of life for me, and guidance to the ways of divine knowledge.`,tones:[3]}]},o6a8a72720e:{mate:`octoechos:tone5.matins.canon.odes.3.cross_resurrection.closer`,mateHash:`m1b8e1a888dfa05`,tone:5,score:.34,next:.24,evidence:[`wording 0.34 (next 0.24)`,`tone 5`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`],first:{doc:`2026-0823-texts-tt`,head:`Tone 5`},why:[`wording below the bar`,`a second hymn is close`],text:`[Sing], O people! Sing the praises of the [Moth]er of our God; | for today she delivers her [soul], full of light, | into the [hands] of Him Who became incarnate of her with[out] seed. | And she en[treats] Him without [ceas]ing // to grant the earth [peace] and great [mer]cy.`,prints:2,dates:[`2026-0823`,`2026-0829`],mateText:`O pure one, without ceasing implore the One who became incarnate from thy loins that those who hymn thee, O pure Virgin, may be delivered from the snares of the devil.`,mateTones:[5],sections:[`Litya`],others:[{mate:`octoechos:tone5.compline.thu.canon.odes.9.items[0]`,mateHash:`m06a1458896ab78`,score:.24,text:`O Lady Theotokos, entreat the adored Trinity, to Whom alone thou hast given birth for us without suffering in the flesh, that He grant peace to those on earth, and that remission of sins be granted to those who hymn thee.`,tones:[5]},{mate:`octoechos:tone5.great_vespers.aposticha_theotokion`,mateHash:`m1f0f29a96aa141`,score:.24,text:`Thou art the temple and portal, * the palace and throne of the King, * O most honored Virgin, * through whom Christ the Lord, my Redeemer, * Who is the Sun of righteousness, * hath revealed Himself unto those who sleep in darkness, * deigning to enlighten those * whom He hath fashioned in His image by His own hand. * Wherefore, O all-hymned one, * as thou hast acquired a mother’s boldness before Him, ** entreat Him without ceasing, that our souls be saved.`,tones:[5]},{mate:`octoechos:tone5.matins_weekday.wed.sessionals[1].items[2]`,mateHash:`m0f2ca1df451b99`,score:.23,text:`Zealous for the cup of Thy sufferings, O Lord, the passion- bearers forsook the beauties of life and became communicants with the angels. Through their entreaties, O Christ, grant peace and great mercy to our souls.`,tones:[5]}]},o6dc0c1e22e:{mate:`menaion:11-20.c0.matins.canons[2].odes.7.items[1]`,mateHash:`m073a6b08a73c6f`,tone:1,score:.38,next:.27,evidence:[`wording 0.38 (next 0.27)`,`tone 1`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`,`NAMES DIFFER: the OCA text names Romanus; ours does not`],first:{doc:`2026-1001-texts-tt`,head:`Tone 1 (for St. Romanus) (Joy of the Heavenly Hosts)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Romanus; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Now thou standest with boldness, O Father, before the Master of all. | Pray that we who celebrate thy memory and thy splendid feast | may be delivered from misfortunes and dangers, // O divinely blessed Romanus!`,prints:1,dates:[`2026-1001`],mateText:`Having acquired boldness before Christ, O holy one, pray thou that those who with hymnody praise thy glorious memory on earth, hymning the praised and supremely glorious God, may be delivered from all manner of dangers.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`menaion:11-20.c0.vespers.lic[3]`,mateHash:`m11e6d514e2c2a9`,score:.27,text:`Dwelling with gladness in the mansions of heaven, O father, * and standing boldly with the angels * before the throne of the Lord, * pray thou that He grant * release from sins and the passions ** unto those who on earth celebrate thy memory.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.1.items[0]`,mateHash:`m0019ef9a039a53`,score:.26,text:`Standing in splendor before the throne of the Master, Who is equally eternal with the Father, and is His angel of great Counsel, O all-holy angels, pray for me who hymn you, that He may inspire my words.`,tones:[1]},{mate:`octoechos:tone1.compline.fri.canon.odes.6.items[0]`,mateHash:`m1c96c533b62162`,score:.24,text:`Thou preservest me alive, delivering me from dangers. In thy loving-kindness do thou also stand before me when I depart this earth for life everlasting, O Virgin Mother.`,tones:[1]}]},o70a4add5d9:{mate:`octoechos:tone1.great_vespers.dogmatikon`,mateHash:`m12ef14b0bb9d7e`,tone:1,score:.38,next:.21,evidence:[`wording 0.38 (next 0.21)`,`tone 1`,`place: vespers`],first:{doc:`2026-1004-texts-tt`,head:`Tone 1 (Theotokion – Dogmatikon)`},why:[`wording below the bar`],text:`Let us [praise] the Virgin [Ma]ry! | The gate of heaven, the [glo]ry of the world! | The [song] of the angels, the beauty of the [faith]ful! | She was born of [man], yet gave [birth] to God! | She was re[vealed] as the heaven, as the temple of the [God]head! | She destroyed the wall of [en]mity! | She com[menced] the peace; she opened the [King]dom! | Since she is [our] foun[da]tion of faith, | our de[fen]der is the [Lord] Whom she bore! | Courage! Courage! O [Peo]ple of God! | For [Christ] will destroy our [en]emies // since He is all [pow]erful.`,prints:3,dates:[`2026-1004`,`2026-1129`,`2026-1205`],mateText:`Let us hymn the whole world’s glory, * who sprang forth from mankind and who gave birth to the Master, * the Portal of heaven, Mary the Virgin, * the hymn of the Bodiless Powers and adornment of the faithful; * for she hath been revealed as the Heaven and Temple of the Godhead. * By destroying the middle wall, she hath brought forth peace, * and opened wide the Kingdom. * Therefore, holding fast to her as a firm confirmation of the faith, * we have as our champion the Lord born from her. * Take courage therefore, take courage, O ye people of God; ** for as the Invincible one he shall conquer our adversaries.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`menaion:11-30.c0.matins.canons[2].odes.1.items[5]`,mateHash:`m08dc457d74ee13`,score:.21,text:`God is born an Infant through the Virgin, and He reneweth that which, through Adam, had become corrupt; and breaking down the middle-wall of partition and the chamber of enmity with His flesh, He came forth from His most pure Mother, abolishing the curse of our first mother. Katavasia: Christ is born, render ye glory. * Christ cometh from heaven, meet ye Him. * Christ is on earth, be ye exalted. * O all the earth, sing unto the Lord, * and sing praises in gladness, O ye people, * for He hath been glorified.`,tones:[1]},{mate:`menaion:11-24.c0.matins.aposticha_closer`,mateHash:`m077ebca45dc92a`,score:.21,text:`O gate of heaven, * accept ye the Virgin Mary * who hath not known a man, * the pure Theotokos, ** from whom came forth the deliverance of mankind.`,tones:[]},{mate:`octoechos:tone1.matins.canon.odes.8.theotokos.troparia[1]`,mateHash:`m0d7db4013bd5cd`,score:.17,text:`Rejoice!, glorious throne of God! Rejoice! wall of the faithful, through whom Christ, the light, hath dawned for those in darkness, who call Thee blest and cry: “All ye His works bless the Lord, praise and supremely exalt Him throughout all ages.”`,tones:[1]}]},o71bae04f5b:{mate:`octoechos:tone8.matins_weekday.fri.canons[0].odes.5.irmos`,mateHash:`m1c2aeab53bf038`,tone:8,score:.44,next:.4,evidence:[`wording 0.44 (next 0.4)`,`tone 8`,`place: matins`],first:{doc:`2026-0914-texts-tt`,head:`Tone 8 Canon, Ode 5 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`O thrice-blessed Tree, on which Christ the King and Lord was stretched! | Through thee the one who deceived us through a tree has fallen, | caught by the bait of God, Who was nailed to thee in the flesh, // and Who grants peace to our souls. | Katavasia: “O thrice-blessed Tree…”`,prints:1,dates:[`2026-0914`],mateText:`O thrice-blessed Tree, on which Christ the king and Lord was stretched! * Through thee the beguiler fell, * who tempted mankind with the tree. * He was caught in the trap set by God, * who was crucified upon thee in the flesh, * granting peace unto our souls.`,mateTones:[8],sections:[`“Having beheld the Resurrection of Christ…” [is] sung, and then Psalm 50.`],others:[{mate:`menaion:09-08.c0.matins.canons[1].odes.5.items[5]`,mateHash:`m1727b61fe48def`,score:.4,text:`Thy womb became the chariot of the Sun; thy purity remained intact as before, O Virgin; for Christ the Sun hath appeared from thee like a Bridegroom from a bridal chamber. Katavasia: O thrice-blessed Tree, on which Christ the king and Lord was stretched! * Through thee the beguiler fell, * who tempted mankind with the tree. * He was caught in the trap set by God, * who was crucified upon thee in the flesh, * granting peace unto our souls.`,tones:[8]},{mate:`menaion:11-25.c0.matins.canons[2].odes.5.items[3]`,mateHash:`m199636dc9a50b1`,score:.19,text:`We hymn thee, as Virgin after giving birth, O Theotokos, who for the sake of the world thou hast given birth in the flesh unto God the Word. Katavasia: As Thou art the God of peace and Father of compassions, * Thou hast sent unto us Thine angel of great counsel, * granting us peace. * Wherefore guided towards the light of the knowledge of God, * and watching by night we glorify Thee, * O Lover of mankind.`,tones:[8]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_lauds`,mateHash:`m0835d754800ce2`,score:.18,text:`Through the prayers of the Theotokos, * grant peace to the life of us who cry out to Thee: ** O merciful Lord, glory be to Thee!`,tones:[]}]},o7572552dc7:{mate:`menaion:11-16.c0.great_vespers.aposticha[0]`,mateHash:`m11dfc20fca8328`,tone:4,score:.38,next:.2,evidence:[`wording 0.38 (next 0.2)`,`tone 4`,`place: vespers`,`melody “Thou hast given a sign ...”`,`same date`,`NAMES DIFFER: the OCA text names Matthew; ours does not`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 (Thou hast given a sign)`},why:[`wording below the bar`,`the OCA text names Matthew; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`O all-praised [Mat]thew, | thy words are a trumpet drawing men to the [know]ledge of God. | They have de[liv]ered the inhabitants of the earth from enslavement to [ev]il, | leading us into the true faith, the unity of [right]eousness. // Pray to Christ our God to deliver us from corruption and [dan]ger!`,prints:1,dates:[`2026-1116`],mateText:`With the trumpet of thy words * thou didst summon all * to the knowledge of God, O ever-praised one; * and, having driven the assemblies of the deceived from the earth, * thou didst guide the faithful to one unity of mind. * and prayest now * that those who ever celebrate * thine honored memory with faith ** may be delivered from corruption and misfortunes.`,mateTones:[4],sections:[`Aposticha`],others:[{mate:`menaion:11-16.c0.matins.canons[0].odes.3.items[3]`,mateHash:`m0211d21d94db15`,score:.2,text:`The trumpet of theology which soundeth forth mightily hath illumined the divinely wise Matthew to proclaim to the peoples, the Effulgence of the Trinity and the incarnation of the Word from thee, O most pure one, in a manner transcending understanding.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.fri.canons[0].odes.3.items[1]`,mateHash:`m0dfbe2998c0a6f`,score:.17,text:`Unjustly condemned, Thou didst stand before the judge, O Thou Who dost judge the whole earth with righteousness; and Thou didst endure smiting on Thy cheek, O Lord, desiring to free me, who am enslaved to the evil prince of this world.`,tones:[4]},{mate:`menaion:11-16.c0.great_vespers.troparion_alternate`,mateHash:`m05ea1881a2c652`,score:.16,text:`Zealously following Christ the Master, * Who in His goodness appeared to mankind on the earth, and called thee from thy tax-booth, * thou wast shown to be a chosen apostle * and a trumpet-voiced proclaimer of the Gospel to the whole world. * Wherefore, we honor thy precious memory, O divinely eloquent Matthew. * Entreat the merciful God, ** that He granteth remission of sins unto our souls.`,tones:[]}]},o75e5b0f9c1:{mate:`menaion:11-14.c0.vespers.litiya.stichera[2]`,mateHash:`m127e4e1d6aee28`,tone:4,score:.36,next:.28,evidence:[`wording 0.36 (next 0.28)`,`tone 4`,`place: vespers`,`NAMES DIFFER: the OCA text names Luke; ours does not`],first:{doc:`2026-1018-texts-tt`,head:`Tone 4 (for St. Luke) (As one valiant among the martyrs)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Luke; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`With the lightning bolts of thy [preach]ing, | thou didst enlighten those who sat in the darkness of ignorance, O [glo]rious Luke. | Through [faith], thou hast revealed them to be the children of God the [Mas]ter. | Thou didst love Him through [suf]fering and death | and so hast inherited His [glo]ry, // O wise, faithful, and inspired dis[ci]ple.`,prints:1,dates:[`2026-1018`],mateText:`Having illumined with the lightning flashes of thy preaching * those who sit in the darkness of unbelief, * O glorious one, * thou didst show them to be sons of our God and Master * through their faith. * Thou didst emulate His sufferings and death * and didst become an heir to His glory, * in that thou art a wise proclaimer of God, ** a disciple of Truth.`,mateTones:[4],sections:[`Litya`],others:[{mate:`octoechos:tone4.matins_weekday.thu.sessionals[1].items[1]`,mateHash:`m187022009c8183`,score:.28,text:`O Savior, Thou hast shown Thy disciples to the world as preachers of the Faith, through them guiding the world to the knowledge of Thee; for with rays of the word they shed light upon all, dispelling the darkness of ignorance with faith. By their supplications save Thou our souls.`,tones:[4]},{mate:`octoechos:tone4.compline.mon.canon.odes.5.irmos`,mateHash:`m1f38742318cff0`,score:.18,text:`Thou, O Lord, who camest into the world, * art my light, * a holy Light turning from the darkness of ignorance * those who sing Thy praises in faith.`,tones:[4]},{mate:`menaion:11-16.c0.matins.canons[0].odes.8.items[1]`,mateHash:`m0405fdc2cdce35`,score:.17,text:`The Word sent the theologian forth like lightning to the whole world, driving away the darkness and enlightening the nations with the dogmas of theology. Wherefore, he chanted: Hymn the Lord, O ye works, and supremely exalt Him throughout all ages!`,tones:[4]}]},o7602ad4818:{mate:`menaion:09-08.c0.matins.canons[0].odes.5.irmos`,mateHash:`m0882f6030f9cf0`,tone:2,score:.37,next:.22,evidence:[`wording 0.37 (next 0.22)`,`tone 2`,`place: matins`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 5 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`Thou hast dispelled the mist of dark sayings obscurely worded, | and hast illumined the hearts of the faithful | by the fulfillment of the truth through the Maiden of God; // guide us also by Thy light, O Christ!`,prints:1,dates:[`2026-0908`],mateText:`Having destroyed the darkness of shadowy images * and illumined the hearts of the faithful * by the coming of Truth through the divine maiden, O Christ, * do Thou guide us by Thy light.`,mateTones:[2],sections:[`Gospel`],others:[{mate:`octoechos:tone2.matins_weekday.thu.canons[0].odes.5.items[1]`,mateHash:`m08d91b04b673d9`,score:.22,text:`With divine light ye illumined the hearts of those who languished in the darkness of delusion, O apostles; wherefore, I beseech you: Enlighten me who have been darkened by dark pleasures, O divinely blessed ones.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.tue.canons[1].odes.3.items[0]`,mateHash:`m0bce9f99ae7d11`,score:.22,text:`Heal the stripes of my soul, O Forerunner of the Lord, and with thy divine mediation illumine my mind, which hath been obscured by indifference; and deliver me from every machination of the adversary, I pray.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.mon.canons[1].odes.6.items[2]`,mateHash:`m1a238bcb696dcc`,score:.19,text:`The Lord swore in truth unto David, as He said of old; and in issuing forth from thy womb He fulfilled His word, for thou hast given birth unto Him Who reigneth over heaven and earth, O maiden.`,tones:[2]}]},o76b6848697:{mate:`menaion:11-16.c0.great_vespers.lic[0]`,mateHash:`m19d69fb55edce1`,tone:4,score:.4,next:.21,evidence:[`wording 0.4 (next 0.21)`,`tone 4`,`place: vespers`,`melody “Called from on high ...”`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 (Called from on high)`},why:[`wording below the bar`],text:`The Searcher of the [hearts] of men | inspired thy mind, O Apostle, with His divine [know]ledge. | He [called] thee to Himself, ransoming thee from the [world’s] deceit, | for He is the Light whose rays shine to the [ends] of the earth. | He commanded [thee] to pro[claim] His word. | He made thee worthy to write His holy [Gos]pel; // pray that He may save and en[light]en our souls!`,prints:1,dates:[`2026-1116`],mateText:`When He who trieth our hearts * perceived thy godly mind, O apostle, * with His divine foreknowledge, * He delivered thee from injustice and the world; * then, making thee a universal light, * and commanding thee to illumine and shine upon * the ends of the whole world, * He manifestly deemed thee worthy * to write His divine Gospel. * Him do thou entreat, ** that He save and enlighten our souls.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-26.c1.matins.exapostilarion_closer`,mateHash:`m0e0d1dd4d8fe14`,score:.21,text:`In thy birthgiving thou didst illumine the world, O most pure Theotokos. Wherefore, illumining our minds with the knowledge of thy Son, wound thou our hearts with love for the divine commandments, strengthening us in faith and the doing of good by thy supplications.`,tones:[]},{mate:`octoechos:tone4.matins_weekday.thu.sessionals[1].items[1]`,mateHash:`m187022009c8183`,score:.19,text:`O Savior, Thou hast shown Thy disciples to the world as preachers of the Faith, through them guiding the world to the knowledge of Thee; for with rays of the word they shed light upon all, dispelling the darkness of ignorance with faith. By their supplications save Thou our souls.`,tones:[4]},{mate:`menaion:11-15.c0.matins.canons[0].odes.5.items[1]`,mateHash:`m04a23e14ec00fe`,score:.18,text:`The miracles of the martyrs have been manifestly proclaimed unto all the ends of the world, and have made all steadfast through faith.`,tones:[4]}]},o776de68ccd:{mate:`octoechos:tone3.great_vespers.aposticha_theotokion`,mateHash:`m1afcd6769c574c`,tone:3,score:.42,next:.35,evidence:[`wording 0.42 (next 0.35)`,`tone 3`,`place: vespers`],first:{doc:`2026-1011-texts-tt`,head:`Tone 3 (Theotokion)`},why:[`wording below the bar`,`a second hymn is close`],text:`By the will of the [Fa]ther, | without seed, of the Holy Spirit thou didst conceive the [Son] of God. | He was born of the Father before eternity without a [moth]er, | but now for our sake He didst come from thee without a [fa]ther! // Do not cease entreating Him to de[liv]er our [souls] from harm!`,prints:2,dates:[`2026-1011`,`2026-1025`],mateText:`By the will of the Father and without seed * thou didst conceive through the divine Spirit the Son of God * Who hath existed from the Father without a mother from before the ages, * and Who for our sake came forth from Thee in the flesh without a father, * and Him hast thou suckled as a babe. * Wherefore, cease not to beseech Him, ** that our souls be delivered from tribulations.`,mateTones:[3],sections:[`Litya`,`Aposticha`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.3.tue_praises`,mateHash:`m05fce683321875`,score:.35,text:`Without seed didst thou conceive by the Holy Spirit; * and glorifying thee, we hymn thee: ** Rejoice, most holy Virgin!`,tones:[]},{mate:`octoechos:tone3.matins_weekday.tue.aposticha_theotokion`,mateHash:`m1ed49a610616fd`,score:.33,text:`Without seed thou didst conceive by the Holy Spirit; we glorify thee and sing thy praises: Rejoice, O most holy Virgin!`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.sat.praises.theotokion`,mateHash:`m06f79b643554ba`,score:.32,text:`Without seed thou didst conceive by the Holy Spirit; we glorify thee and hymn thy praises: Rejoice, O most holy Virgin!`,tones:[3]}]},o7b02d3559f:{mate:`octoechos:tone1.little_vespers.lic[3]`,mateHash:`m074cc8a8158ba6`,tone:1,score:.38,next:.27,evidence:[`wording 0.38 (next 0.27)`,`tone 1`,`place: vespers`],first:{doc:`2026-1004-texts-tt`,head:`Tone 1 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`[Come], O [peo]ple, | let us hymn and fall [down] before Christ, | [glo]rifying His Resur[rec]tion from the dead! | For [He] is [our] God, // Who has delivered the world from the [En]emy’s deceit!`,prints:2,dates:[`2026-1004`,`2026-1129`],mateText:`Come O ye peoples, * let us hymn and worship Christ * glorifying his Resurrection from the dead: * for he is our God, ** who hath redeemed the world from the deception of the adversary.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone1.matins.praises.stichera[0]`,mateHash:`m025e78739c798c`,score:.27,text:`We sing the praise of Thy saving Passion, * O Christ, ** and we glorify Thy Resurrection.`,tones:[1]},{mate:`octoechos:tone1.matins.sessionals[0].items[0]`,mateHash:`m06ff088d7ae54a`,score:.27,text:`While watching Thy grave, the soldiers * became as dead men from the lightning flash of the angel * who appeared and proclaimed to the Women the Resurrection. * We glorify Thee, the destroyer of corruption; * we fall down before Thee, * who hath risen from the grave ** and who alone art our God.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.tue.canons[0].odes.1.items[0]`,mateHash:`m1e8f517ba37245`,score:.22,text:`Enslaved by the passions of sin, I fall down before Thee, O Lord, that Thou mightest show me to be free of them, for I ardently glorify Thy goodness.`,tones:[1]}]},o7d49f68533:{mate:`octoechos:theotokia.doxasticon_theotokia.3.mon_praises`,mateHash:`m02de15499ac880`,tone:1,score:.32,next:.3,evidence:[`wording 0.32 (next 0.3)`,`tone not printed on one side`],first:{doc:`2026-1001-texts-tt`,head:`Tone 1 (for the Protection) (Oh, the Marvelous Wonder)`},why:[`wording below the bar`,`a second hymn is close`],text:`Oh, how marvelous an adornment art thou to all the faithful! | Thou art the true fulfillment of the prophecies, | the glory of the Apostles and the beauty of the Martyrs, | the boast of virginity and the marvelous protection of the whole world. | O sovereign Lady, protect with the omophorion of thy tender mercy | all the people who cry out to thee: | “Rejoice, O Virgin, full of grace, | the Lord is with thee, // granting the world great mercy through thee!”`,prints:1,dates:[`2026-1001`],mateText:`O Sovereign Lady, thou foremost holy and pure boast of the heavenly ranks, * thou hymn of the apostles and fulfillment of the prophets: ** accept thou our supplications.`,mateTones:[],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone1.matins_weekday.thu.aposticha_theotokion`,mateHash:`m04888193ef8718`,score:.3,text:`Rejoice, O Virgin Theotokos! Rejoice, boast of the whole world! Rejoice, O most pure and blessed Mother of God!`,tones:[1]},{mate:`menaion:11-21.c0.great_vespers.lic[2]`,mateHash:`m0e89cee4012660`,score:.25,text:`Thou art the proclamation of the prophets, the glory of the apostles, the boast of the martyrs, the restoration of all mortals, O Virgin Mother of God; for through thee have we been reconciled with God. Wherefore, we honor thine entrance into the temple of the Lord, and with the angel all of us who find salvation through thy supplications cry out to thee in hymns: Rejoice, O most pure one!`,tones:[1]},{mate:`octoechos:theotokia.doxasticon_theotokia.1.thu_praises`,mateHash:`m09c11b1c1098f4`,score:.24,text:`Rejoice, O Virgin Theotokos, * thou boast of all the world! ** Rejoice, O most pure and blessed Mother of God!`,tones:[]}]},o7ff1fdea78:{mate:`octoechos:tone4.matins_weekday.mon.canons[1].odes.9.irmos`,mateHash:`m00f8e0dbc08210`,tone:4,score:.3,next:.18,evidence:[`wording 0.3 (next 0.18)`,`tone 4`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`,`NAMES DIFFER: the OCA text names Gabriel; ours does not`],first:{doc:`2026-1108-texts-tt-`,head:`Tone 4 (for Archangel Gabriel) (Thou hast given a sign)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Gabriel; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`The Eternal Wisdom established thee, O [Ga]briel, | as a second light reflecting [things] divine, | il[lum]ining the whole cre[a]tion, | and revealing to us the divine mystery hidden from before the [ag]es: | the bodiless One made [flesh] in a [vir]gin womb // and become Man that He might [save] mankind.`,prints:1,dates:[`2026-1108`],mateText:`The ineffable hidden mystery of God hath been revealed in thee, * O most pure Virgin; * for in His tender compassion * God become incarnate of thee. * Wherefore, we magnify thee as the Theotokos.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.dismissal_theotokion`,mateHash:`m10c575843a8d04`,score:.18,text:`The mystery hidden from all ages * and unknown to the ranks of angels, * hath been revealed to those on earth through thee, O Theotokos: * God incarnate in an uncommingled union, * Who willingly accepted the Cross for our sake, * and through it hath raised up the first-formed man, ** and saved our souls from death.`,tones:[4]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.4.fri_vespers_sat_matins`,mateHash:`m11d1149d65af8f`,score:.18,text:`The mystery hidden from all ages * and unknown to the ranks of Angels, * hath been revealed to those on earth through thee, O Theotokos: * God incarnate in an uncommingled union, * Who willingly accepted the Cross for our sake, * and through it hath raised up the first-formed man, ** and saved our souls from death.`,tones:[]},{mate:`octoechos:tone4.matins.canon.odes.7.cross_resurrection.closer`,mateHash:`m1ae04bc156088c`,score:.16,text:`Following the divine teachings we glorify the one Godhead, as a flame of three Lights, without commingling and undivided, eternally enlightening the whole of creation which doth sing: “O supremely exalted Lord and God of our fathers, blessed art Thou.”`,tones:[4]}]},o8087883da2:{mate:`octoechos:tone1.nocturns.gregory_rubric.stanzas[6]`,mateHash:`m0a40798c41e5a2`,tone:1,score:.39,next:.35,evidence:[`wording 0.39 (next 0.35)`,`tone 1`],first:{doc:`2026-0914-texts-tt`,head:`Tone 1 Troparion`},why:[`wording below the bar`,`a second hymn is close`],text:`The Lord reigns, let the people tremble! He sits enthroned upon the cherubim; let the earth quake! (Ps. 98:1)`,prints:1,dates:[`2026-0914`],mateText:`With fear let us glorify Christ the Bestower of life, Who ineffably became incarnate from the Virgin, for the cherubim tremble and quake before Him, and the angelic armies glorify Him.`,mateTones:[1,5,6],sections:[`The Third Antiphon`],others:[{mate:`octoechos:tone1.nocturns.gregory_rubric.stanzas[0]`,mateHash:`m1d8a8b90b4a78c`,score:.35,text:`It is truly meet to glorify Thee, the Word of God, before Whom the cherubim tremble and quake, and Whom the hosts of heaven glorify. And with fear we glorify Christ, the Bestower of life, Who rose from the tomb on the third day.`,tones:[1,3,4,5,6,7,8]},{mate:`menaion:11-21.c0.matins.canons[1].odes.9.items[5]`,mateHash:`m0f25ed04a89e0e`,score:.18,text:`O ye faithful, with the angel let us fittingly cry out to the Theotokos “Rejoice!” Rejoice, O most comely Bride! Rejoice, O radiant cloud, from whom the Lord hath shone forth upon us who sit in the darkness of ignorance! Rejoice, thou hope of all!`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.sat.canons[0].odes.9.items[3]`,mateHash:`m0781b3c871dd4a`,score:.16,text:`O Power Who reignest over all, those whom Thou hast taken from the earth do Thou show to share with Thy saints in Thy kingdom; and in Thine all-great goodness, O God of all, overlook the things they have committed.`,tones:[1]}]},o8236e2ce86:{mate:`menaion:09-08.c0.matins.canons[0].odes.8.irmos`,mateHash:`m072b0cd1fe199d`,tone:2,score:.39,next:.31,evidence:[`wording 0.39 (next 0.31)`,`tone 2`,`place: matins`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 8 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`In the furnace of the Children, | once Thou didst prefigure Thine own Mother, O Lord; | and this type delivered them from the fire | as they walked in the midst of it unconsumed. | To her do we sing praises | as Thou hast manifested her today to the ends of the earth, // and we exalt her above all forever.`,prints:1,dates:[`2026-0908`],mateText:`Of old in the furnace of the holy children, * Thou didst prefigure Thy Mother, O Lord, * in the image of those who entered therein, * and rescued therefrom remained unconsumed. * Her who hath been revealed today do we hymn * unto the ends of the earth, * supremely exalting her throughout all ages.`,mateTones:[2],sections:[`Gospel`],others:[{mate:`octoechos:tone2.matins_weekday.thu.canons[0].odes.8.items[3]`,mateHash:`m027a89c8a72f34`,score:.31,text:`The furnace which once failed to burn the children prefigured thy birthgiving, O all-immaculate Virgin; wherefore, I beseech thee: With the apostles and all the prophets, pray that I be delivered from the fire of Gehenna.`,tones:[2]},{mate:`octoechos:tone2.compline.sat.canon.odes.7.irmos`,mateHash:`m135e65022f47de`,score:.27,text:`That Thou mightest prefigure * Thy most glorious nativity from a virgin, O Christ, * Thou didst preserve unconsumed in the furnace * the youths who chanted to Thee with hymns: * Blessed art Thou O God of our fathers!`,tones:[2]},{mate:`octoechos:tone2.compline.thu.canon.odes.7.items[2]`,mateHash:`m19eebb2a634c05`,score:.25,text:`The furnace prefigured thy birthgiving, O all-immaculate one, for it did not consume the children, just as the unbearable Fire did not consume thy womb. Wherefore, we entreat thee: Deliver thy servants from eternal fire.`,tones:[2]}]},o8283b5bbe9:{mate:`octoechos:tone4.little_vespers.lic[3]`,mateHash:`m1914219017c19e`,tone:4,score:.46,next:.28,evidence:[`wording 0.46 (next 0.28)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`],text:`Thou didst smash the gates of [hell], O Lord, | and by Thy death Thou didst demolish the [king]dom of death. | Thou didst de[liv]er the race of men from cor[rup]tion, // granting the world life, incorruption and great [mer]cy.`,prints:2,dates:[`2026-0830`,`2026-1025`],mateText:`Thou hast shattered the gates of Hades, O Lord, * and by Thy death Thou hast destroyed the dominion of death; * delivering mankind from corruption, * granting the world life, incorruption, ** and great mercy.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.great_vespers.lic[5]`,mateHash:`m0c38b926ce47b6`,score:.28,text:`Thou hath shattered the gates of brass and smashed their bars, O Christ God, * raising the fallen race of mankind; * wherefore with one accord we cry unto Thee: * “O Lord risen from the dead, ** glory be to Thee!”`,tones:[4]},{mate:`octoechos:tone4.matins.canon.odes.1.cross_resurrection.troparia[0]`,mateHash:`m1ef0a1637bc4ef`,score:.21,text:`O Lord by Thy precious Blood, Thou hast healed the ruined race of mankind, demolishing the dominion of the mighty one, who of old spoiled the creature that Thou didst fashion.`,tones:[4]},{mate:`octoechos:tone4.ikos`,mateHash:`m016fe4c5d899a9`,score:.2,text:`Let all of us, born of earth, hymn Christ the giver of life, who arose from the dead on the third day. For today, by His power He hath smashed the gates of death, slaughtering Hades and crushing the sting of death, setting Adam free with Eve. Therefore with thanksgiving we cry out aloud our fervent praises, for He alone, as almighty God and Master, hath risen on the third day.`,tones:[4]}]},o836e6bbc5e:{mate:`menaion:09-05.c1.vespers.aposticha_closer`,mateHash:`m1fd64709c6821c`,tone:2,score:.47,next:.2,evidence:[`wording 0.47 (next 0.2)`,`tone 2`,`place: vespers`],first:{doc:`2026-1031-texts-tt`,head:`Tone 2 (Theotokion)`},why:[`wording below the bar`],text:`A new miracle surpasses all ancient [mir]acles! | Who knows of a Mother who gave birth with[out] a man, | who [car]ried in her arms her Cre[a]tor? | This birth is the [will] of God! | Since thou didst carry Him as an infant in thine arms, O most [pure] one, | and since [thou] dost possess motherly boldness be[fore] Him, | do not cease praying for us who [hon]or thee, // that He may be bountiful and [save] our souls!`,prints:4,dates:[`2026-1031`,`2026-1114`,`2026-1115`,`2026-1205`],mateText:`O new wonder greater than all the wonders of old! * For who hath ever known a mother to give birth without having known a man, * and to bear on her arm Him Who sustaineth all creation? * Yet it was the will of God to be born. * O most pure one, who carried Him as an infant in Thine embrace * and before Whom thou hast a mother’s boldness: * cease not to pray on behalf of those who honor thee, ** that He have compassion and save our souls.`,mateTones:[2],sections:[`Litya`,`Aposticha`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.4.sat_praises`,mateHash:`m1ffa54c848d980`,score:.2,text:`O only pure and most pure Virgin, * who hath given birth without seed unto God: ** pray thou that our souls be saved.`,tones:[]},{mate:`octoechos:tone2.compline.fri.after_ode6.sessional`,mateHash:`m142b81fdee64b9`,score:.19,text:`Thou didst conceive the Word without seed, and hast given birth to the one Christ; for thou didst bear a new Child, thy Creator. Wherefore, we magnify thee, O Theotokos.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.tue.sessionals[2].closer`,mateHash:`m1cbf6e0c3147b2`,score:.17,text:`Who hath seen, who hath heard of a mother giving birth to her own Creator, without knowing a man, and giving suck unto Him Who gives nourishment to all flesh? O the wonder! Thy womb hath been revealed to be the throne of the cherubim, O gracious Theotokos. Pray for our souls.`,tones:[2]}]},o8682b9a3a5:{mate:`menaion:11-21.c0.great_vespers.lic[0]`,mateHash:`m19a3548f0e9433`,tone:1,score:.5,next:.26,evidence:[`wording 0.5 (next 0.26)`,`tone 1`,`place: vespers`,`melody “O wondrous marvel ...”`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 1 (Oh, the Marvelous Wonder)`},why:[`wording below the bar`],text:`To[day], let us dance, O [faith]ful, | singing to the Lord in [psalms] and hymns | and [hon]oring His sanctified Tabernacle, the [liv]ing Ark, | that contained the [Word] Who can[not] be contained; | for in [won]drous fashion she is [of]fered to the Lord | as a young [child] in the flesh, | and Zacha[ri]ah, the great High Priest, joyfully re[ceives] her // as the dwelling [place] of God.`,prints:2,dates:[`2026-1121`,`2026-1125`],mateText:`Let us join chorus today, O ye faithful, chanting to the Lord in psalms and hymns, and honoring His sacred tabernacle, the animate ark, who contained the uncontainable Word; for she is brought to the Lord, having become a babe in a manner transcending nature. And Zachariah, the great high priest, receiveth her with gladness as the dwelling-place of God.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`menaion:11-21.c0.little_vespers.lic[0]`,mateHash:`m1fe31802f05801`,score:.26,text:`Having received from the Lord * the fruit of the promise, the Mother of God, * the right acceptable sacrifice, * Joachim and Anna lead her into the temple today; * and Zachariah, the great high priest, ** receiveth her with his blessing.`,tones:[1]},{mate:`menaion:11-21.c0.matins.canons[1].odes.8.items[2]`,mateHash:`m0692856f77d447`,score:.24,text:`The most pure Mary, the animate tabernacle, is brought today into the house of God; and Zachariah taketh her in his arms as the sanctified treasure of the Lord.`,tones:[1]},{mate:`menaion:09-05.c0.matins.canons[0].odes.8.items[3]`,mateHash:`m05767c5f14d6b9`,score:.2,text:`Rejoicing, Zacharias, the high priest and preacher of God, paid homage to the Virgin and Mother who beareth the Lord of creation. Her do we supremely exalt throughout all ages.`,tones:[1,8]}]},o875983610b:{mate:`menaion:11-25.c0.matins.praises[0]`,mateHash:`m0275a10494ebd0`,tone:1,score:.48,next:.32,evidence:[`wording 0.48 (next 0.32)`,`tone 1`,`place: matins`,`melody “Joy of the ranks of heaven ...”`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 1 (Joy of the Heavenly Hosts)`},why:[`wording below the bar`],text:`[Vir]gins, bearing lamps to light the way for the ever-[Vir]gin, | truly prophesy in the Spirit that which [is] to come. | For the Theo[to]kos is the [Tem]ple of God, // and from infancy is led into the Temple in virginal [glo]ry.`,prints:1,dates:[`2026-1121`],mateText:`Virgins bearing lamps, * escorting the Ever-virgin with splendor, * truly prophesy the future in the Spirit; * for the Theotokos, as the temple of God, * is led as a child with virginal glory ** into the temple.`,mateTones:[4,1],sections:[`The Praises Tone 1`],others:[{mate:`menaion:11-21.c0.matins.canons[1].odes.3.items[2]`,mateHash:`m0e0256ca63cea9`,score:.32,text:`Mary, the Theotokos, the habitation of God, is led into the holy temple, being three years of age in the flesh; and, going before her, virgins bear lighted lamps.`,tones:[1]},{mate:`menaion:11-24.c0.vespers.aposticha[0]`,mateHash:`m1fe28d0c21ba3c`,score:.23,text:`Come, all ye who love the feasts of the Church, * and with hymns let us honor * her who alone is the pure Theotokos and Virgin, * for she is led into the Temple of God, * to now splendidly dwell therein, the truly most holy temple of Christ, ** and mediatress of all joy.`,tones:[1]},{mate:`menaion:11-20.c0.matins.exapostilarion_closer`,mateHash:`m02b0fd33007169`,score:.23,text:`The temple doth now observe a day of pre-festival for the most pure entrance of Mary, the Theotokos, whom the angels hymn and we call blessed, and whom is accompanied by virgins, bearing lamps and rejoicing, into the temple of the Lord.`,tones:[]}]},o8d2956b047:{mate:`octoechos:tone8.vespers_weekday.fri.aposticha.items[1]`,mateHash:`m14732c6145b313`,tone:8,score:.47,next:.19,evidence:[`wording 0.47 (next 0.19)`,`tone 8`,`place: vespers`],first:{doc:`2026-1024-texts-tt`,head:`Tone 8 (for the Departed, by St. John of Damascus)`},why:[`wording below the bar`],text:`I [weep] and I lament when I [con]template death, | and see our beauty, fashioned in God's [im]age, | laid in the grave without form or [hon]or or [glo]ry. | Oh, great [mys]tery! | What is this fearful end a[wait]ing us? | Why have we been handed [o]ver to cor[rup]tion? | Why have we been [wed]ded to death? | Truly, as it is written, this is or[dained] by God, // Who granteth rest to the de[part]ed!`,prints:1,dates:[`2026-1024`],mateText:`I weep and lament when I contemplate death and behold our beauty, which hath been created according to the image of God, lying in the grave, bereft of form, devoid of glory, unsightly. O the wonder! What is this mystery concerning us? How have we been given over to corruption? How have we been yoked together with death? Truly, as it is written, this is by the command of God, Who giveth rest unto the departed.`,mateTones:[8],sections:[`Lord I Call...`],others:[{mate:`menaion:11-25.c0.matins.canons[1].odes.4.items[3]`,mateHash:`m00daf2556e225a`,score:.19,text:`We have acquired thee, with God, as our helper; for thou wast the Mother of God, the Creator and Fashioner, Who took upon Himself our image and saved it from corruption and death, and glorified it with divine glory, O all-immaculate one.`,tones:[8]},{mate:`octoechos:tone8.matins.sessionals[0].items[1]`,mateHash:`m154d8636f1a20e`,score:.16,text:`When Thou wast indeed risen from the tomb * Thou didst command the holy women to announce the Resurrection to the apostles, * as it is written; * and Peter, having arrived quickly, * stood by the grave and seeing the light in the tomb was affrightened. * observing the grave clothes lying therein, * without the divine body, * and believing he cried aloud: * “Glory be to Thee O Christ God our Savior, * Who hast saved us all, ** for Thou art the effulgence of the Father.”`,tones:[8]},{mate:`octoechos:tone8.compline.wed.canon.odes.4.items[3]`,mateHash:`m18e15e82d46b81`,score:.16,text:`After God it is thee whom we have acquired as an intercessor, O most immaculate one; for thou wast the Mother of God the Creator and Fashioner, Who took upon Himself our form, saved it from corruption and tribulations, and glorified it with divine glory.`,tones:[8]}]},o8f213d8f63:{mate:`octoechos:tone7.little_vespers.lic[3]`,mateHash:`m123437d72e2e06`,tone:7,score:.31,next:.22,evidence:[`wording 0.31 (next 0.22)`,`tone 7`,`place: vespers`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-0920-texts-tt`,head:`Tone 7 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`When the A[pos]tles beheld the Resurrection of the [Mak]er, | they were a[mazed] and sang the an[gel]ic praise. | [This] is the [glo]ry of the Church. | [This] is the richness of the [King]dom. // O Lord, crucified for our [sake], [glo]ry to Thee!`,prints:2,dates:[`2026-0920`,`2026-1115`],mateText:`The apostles were struck with amazement when they saw the Creator’s arising * and they cried aloud the angelic hymn of praise: * “This is the glory of the Church, this is the wealth of the kingdom. ** O Lord, who hath suffered for us, glory be to Thee!”`,mateTones:[7],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone7.matins_weekday.wed.aposticha.items[1]`,mateHash:`m0417559dd8d657`,score:.22,text:`The Vine of life was nailed to the Cross, and the nations embraced paradise with the thief. This is the glory of the Church! These are the riches of the kingdom! O Lord Who suffered for our sake, glory be to Thee!`,tones:[7]},{mate:`octoechos:tone7.matins.canon.odes.7.resurrection.troparia[1]`,mateHash:`m0d7ad0d5349e23`,score:.21,text:`When Thou, O Christ, didst arise from the tomb, all creation sang Thy praises; for Thou hast blossomed forth with life; the resurrection of the dead unto those in Hades, and the most glorious light unto those lying in darkness.`,tones:[7]},{mate:`octoechos:tone7.matins_weekday.wed.sessionals[1].closer`,mateHash:`m1e2cffa5b35a92`,score:.16,text:`When the Virgin beheld Thee crucified, O Lord, she cried out to Thee weeping: “I hymn Thine ineffable longsuffering, O my Son, and Thine utter and divine condescension toward mankind!”`,tones:[7]}]},o9378d0a06e:{mate:`menaion:09-06.c0.kontakion`,mateHash:`m0089223dcd2dc6`,tone:2,score:.47,next:.27,evidence:[`wording 0.47 (next 0.27)`,`tone 2`],first:{doc:`2026-1108-texts-tt-`,head:`Tone 2 Kontakion (Bodiless Powers)`},why:[`wording below the bar`],text:`Com[mand]ers of God’s [ar]mies | and ministers of the divine [glo]ry, | [prin]ces of the bodiless [an]gels | and [guides] of mankind; | [ask] for what is good for us, and for great [mer]cy, // O Supreme Com[mand]ers of the [Bod]iless Hosts.`,prints:2,dates:[`2026-1108`,`2026-1207`],mateText:`O chief commander of God, minister of divine glory, * captain of the angels and instructor of all mankind: * beg thou great mercy and that which is profitable for us, * for thou art the supreme commander ** of the bodiless hosts.`,mateTones:[2],sections:[`at the Divine Liturgy`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.2.sun_vespers_mon_matins`,mateHash:`m0970eb9dc6a174`,score:.27,text:`As thou art a well-spring of loving compassion, O Theotokos, * grant mercy unto us. * Look upon us a sinful people, * and ever show forth thy power; * for, trusting in thee, we cry out to thee, Rejoice! ** as once did Gabriel, the supreme commander of the bodiless hosts.`,tones:[]},{mate:`menaion:09-06.c0.ikos`,mateHash:`m00cb68d20734e2`,score:.22,text:`In Thy Scriptures, O immortal Lover of mankind, Thou didst say that a multitude of angels rejoiceth in heaven over one man that repenteth. Wherefore, O Sinless One, Who alone knowest the hearts of men, amid our transgressions we ever make bold to beseech Thee to have compassion and to send down compunction upon us, unworthy though we be, granting us forgiveness, O Master, in that Thou art compassionate; for the supreme commander of the bodiless hosts doth entreat Thee on behalf of us all.`,tones:[]},{mate:`octoechos:tone2.matins_weekday.sat.canons[0].odes.1.items[1]`,mateHash:`m1e0db96bd8786b`,score:.21,text:`The ministers and holy hierarchs of God, shining clearly with noetic light, guided the fullness of all the pious to the light of piety.`,tones:[2]}]},o93c3ea1f0d:{mate:`octoechos:tone8.matins_weekday.fri.canons[0].odes.1.irmos`,mateHash:`m08bbf670825680`,tone:8,score:.49,next:.41,evidence:[`wording 0.49 (next 0.41)`,`tone 8`,`place: matins`],first:{doc:`2026-0908-texts-tt`,head:`Tone 8 Katavasia, Ode 1 (from the Canon of the Elevation of the Cross,`},why:[`wording below the bar`,`a second hymn is close`],text:`Moses traced out a cross, | as with his staff he divided the Red Sea in two, | so that Israel could go across on foot; | and then striking it again crosswise, | and uniting it over Pharoah and his chariots, | he inscribed the Invincible Weapon. // Therefore let us sing to Christ our God, for He has been glorified.`,prints:2,dates:[`2026-0908`,`2026-0914`],mateText:`Inscribing the invincible weapon of the Cross upon the waters, * Moses marked a straight line before him with his staff * and divided the Red Sea, * opening a path for Israel who went over dry-shod. * Then he marked a second line across the waters * and united them in one, * overwhelming the chariots of Pharaoh. * Therefore let us sing to Christ our God, * for He hath been glorified.`,mateTones:[8],sections:[`Gospel`,`“Having beheld the Resurrection of Christ…” [is] sung, and then Psalm 50.`],others:[{mate:`octoechos:tone8.nocturns.canon.odes.1.irmos`,mateHash:`m1502f044d08209`,score:.41,text:`The wonderworking staff of Moses, * striking and dividing the sea in the figure of a cross, * once drowned pharaoh the pursuing charioteer, * while it saved the fleeing people of Israel * as they fled on foot, * chanting a hymn unto God.`,tones:[8]},{mate:`menaion:09-08.c0.matins.canons[1].odes.1.items[5]`,mateHash:`m178d2730388bdc`,score:.4,text:`Who hath seen a Babe fed with milk Whom a father hath now sown? Or where hath there been seen a Mother who is a Virgin? Truly past understanding are both of these things, O pure Birthgiver of God. Katavasia: Inscribing the invincible weapon of the Cross upon the waters, * Moses marked a straight line before him with his staff * and divided the Red Sea, * opening a path for Israel who went over dry-shod. * Then he marked a second line across the waters * and united them in one, * overwhelming the chariots of Pharaoh. * Therefore let us sing to Christ our God, * for He hath been glorified.`,tones:[8]},{mate:`octoechos:tone8.liturgy_weekday.wed.beatitudes.items[1]`,mateHash:`m19a24633dfe141`,score:.25,text:`Forming a cross with his staff, Moses parted the deep and led the people of Israel across; and we, making the sign thereof, vanquish the noetic foe.`,tones:[8]}]},o96df99ad30:{mate:`octoechos:tone5.great_vespers.lic[4]`,mateHash:`m0b93694728083e`,tone:5,score:.5,next:.23,evidence:[`wording 0.5 (next 0.23)`,`tone 5`,`place: vespers`],first:{doc:`2026-0906-texts-tt`,head:`Tone 5 (for the Resurrection)`},why:[`wording below the bar`],text:`We [glo]rify the Leader of our sal[va]tion; | by His Resur[rec]tion from the dead, | the [world] was [saved] from deceit. | The as[sem]bly of Angels re[joic]es | as the deceit of demons is [ov]erthrown. // Fallen Adam [ris]es as the [dev]il falls.`,prints:3,dates:[`2026-0906`,`2026-1101`],mateText:`Let us glorify Christ the Author of our salvation; * for by His arising from the dead, * the world hath been saved from delusion; * the choir of angels rejoiceth, * the deception of demons fleeth, * fallen Adam hath arisen, ** and the devil hath been overthrown.`,mateTones:[5],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone5.little_vespers.aposticha.resurrection[0]`,mateHash:`m134f43dcf8529f`,score:.23,text:`With voices of song we magnify Thee, O Christ, * the Savior incarnate, * yet not separated from heaven, * for as the Lord who lovest mankind * Thou hast suffered the Cross and death for the sake of our race, * overthrowing the gates of Hades, * and rising on the third day, ** saving our souls.`,tones:[5]},{mate:`octoechos:tone5.great_vespers.aposticha[0]`,mateHash:`m096426e95f93c3`,score:.22,text:`With voices of song we magnify Thee, O Christ, * the Savior incarnate, * yet not separated from heaven, * for as the Lord who lovest mankind * Thou hast suffered the Cross and death for the sake of our race, * overthrowing the gates of Hades, * and rising on the third day, ** thus saving our souls.`,tones:[5]},{mate:`octoechos:tone5.little_vespers.lic[0]`,mateHash:`m04d6fe4f4142ce`,score:.2,text:`By Thy precious Cross, O Christ, * Thou hast shamed the devil, * and by Thy Resurrection Thou hast blunted the sting of sin, * and saved us from the gates of death: ** we glorify Thee, the only-begotten One.`,tones:[5]}]},o98b7baa528:{mate:`octoechos:tone2.matins_weekday.tue.canons[1].odes.5.items[0]`,mateHash:`m0ba9a0a0573547`,tone:2,score:.31,next:.3,evidence:[`wording 0.31 (next 0.3)`,`tone 2`],first:{doc:`2026-0829-texts-tt-`,head:`Tone 2 Troparion`},why:[`wording below the bar`,`a second hymn is close`],text:`The [mem]ory of the righteous is celebrated with [hymns] of praise, | but the Lord’s testimony is sufficient for thee, O [Fore]runner. | Thou wast [shown] in truth to be the most honorable of the [Proph]ets, | for thou wast deemed worthy to baptize in the streams of the Jordan [Him] Whom they foretold. | [There]fore, having suffered for the [truth] with joy, | thou didst proclaim to those in hell God Who ap[peared] in the flesh, | Who [takes] away the [sin] of the world // and grants us [great] [mer]cy.`,prints:5,dates:[`2026-0829`,`2026-0830`],mateText:`O Forerunner, who baptized Christ, the Stream of incorruption, in the torrents of the Jordan: Beseech Him to dry up the stench of my passions, that I may inherit torrents of sweetness and the beautiful joy of the righteous.`,mateTones:[2],sections:[`at Great Vespers`,`at Vigil`,`at the Divine Liturgy`],others:[{mate:`octoechos:tone2.matins_weekday.tue.canons[1].odes.7.items[1]`,mateHash:`m0690c28a4861b5`,score:.3,text:`As thou didst baptize in the streams of the Jordan the Lord Who covereth His chambers with the waters, beseech Him ever to give the water of divine compunction to mine eyes, O glorious Forerunner.`,tones:[2]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.8.sun_vespers_mon_matins`,mateHash:`m07ae39435240a2`,score:.23,text:`Rejoice, thou who through the Angel * didst receive the joy of the world! * Rejoice, thou that hast given birth unto thy Creator and Lord! ** Rejoice, thou that wast deemed worthy to be the Mother of God!`,tones:[]},{mate:`octoechos:tone2.matins_weekday.fri.canons[1].odes.6.items[3]`,mateHash:`m075eca572f0b0c`,score:.19,text:`O all-immaculate one who having conceived, hast given birth to the most pure Lamb Who taketh away the sins of the world, cease not to pray to Him, that He grant me the forgiveness of my sins.`,tones:[2]}]},o9b0a2e8faa:{mate:`menaion:11-30.c0.vespers.lic[2]`,mateHash:`m19708002c5d79d`,tone:4,score:.32,next:.22,evidence:[`wording 0.32 (next 0.22)`,`tone 4`,`place: vespers`,`melody “Called from on high ...”`,`same date`],first:{doc:`2026-1130-texts-tt`,head:`Tone 4 (Called from on high)`},why:[`wording below the bar`,`a second hymn is close`],text:`When He Who clothed Himself in [hu]man flesh, | taking our nature from the fruitful womb of the [Vir]gin, | ap[peared] on earth as the Teacher of [right]eousness, | thy heart was made glad, O Andrew, lover of [pur]ity. | He raised thee from earth to the ineffable [glo]ry of [Christ] our God. // Pray that He may save and en[light]en our souls!`,prints:1,dates:[`2026-1130`],mateText:`Having been the disciple of Him that sprang forth from a barren woman, the teacher of piety and chastity, who showed the way to purity, when the Offspring of the Virgin shone forth, being thou a most fervent lover of virtue, O blessed Andrew, and, thou didst make ascent within thy heart, and wast caught up from glory to the ineffable glory of Christ our God. Him do thou beseech, that He save and enlighten our souls.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-17.c0.matins.aposticha[0]`,mateHash:`m1da98ba2227628`,score:.22,text:`Thy priests shall be clothed with righteousness, * and Thy righteous shall rejoice.`,tones:[]},{mate:`menaion:11-20.c0.vespers.aposticha[3]`,mateHash:`m0e2e33e797773e`,score:.22,text:`Thy priests shall be clothed with righteousness, * and thy righteous shall rejoice.`,tones:[4]},{mate:`menaion:11-16.c0.matins.canons[0].odes.5.items[3]`,mateHash:`m12af93fbf129aa`,score:.21,text:`O Virgin, thou hast given birth to the pre-eternal son Who clothed Himself in human nature and saved it from corruption in His absolute goodness, as as the divinely eloquent one said in his teaching; thou didst remain a Virgin.`,tones:[4]}]},o9c4b409d6c:{mate:`octoechos:tone2.compline.sat.canon.odes.8.items[3]`,mateHash:`m0fdc9409cec6d0`,tone:null,score:.35,next:.35,evidence:[`wording 0.35 (next 0.35)`,`tone not printed on one side`,`place: matins`],first:{doc:`2026-0914-texts-tt`,head:`The Praises Tone 8`},why:[`wording below the bar`,`a second hymn is close`],text:`Let [ev]erything that breathes [praise] the Lord! | Praise the Lord from the [heav]ens! | Praise [Him] in the [high]est! // To Thee, O God, is [due] a song!`,prints:1,dates:[`2026-0914`],mateText:`That thy name might be glorified on the earth, O Theotokos, He Who shone forth from thee hath given thee to sinners as a mighty hope and rampart; for through thee doth everything that hath breath hasten to God.`,mateTones:[2],sections:[`The Praises Tone 8`],others:[{mate:`octoechos:tone6.matins.anabathmoi[2].gloria`,mateHash:`m1dfce8a7a772e9`,score:.35,text:`In the Holy Spirit is sovereignty over all creation; * Him the armies of hosts above worship * and by everything that hath breath below ** is He worshiped.`,tones:[6]},{mate:`octoechos:tone2.matins.praises.stichera[0]`,mateHash:`m040a251f1a42ee`,score:.34,text:`Everything that hath breath and every creature doth glorify Thee, O Lord, * for through Thy Cross Thou hast destroyed death * and thus shown the multitude of peoples Thy Resurrection from the dead, ** as Thou alone lovest mankind.`,tones:[2]},{mate:`octoechos:tone7.compline.sun.canon.odes.1.items[3]`,mateHash:`m0e17520dbdc512`,score:.27,text:`Ever effective words of praise are due thee, O Theotokos; yet we entreat thee, O pure one: From all the sorrows of life save those who have recourse unto thee.`,tones:[7]}]},o9e771f001f:{mate:`menaion:11-21.c0.matins.canons[1].odes.9.katavasia`,mateHash:`m19d3257db6bbe0`,tone:1,score:.54,next:.43,evidence:[`wording 0.54 (next 0.43)`,`tone 1`,`place: matins`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 1 Ode 9 – Katavasia`},why:[`a second hymn is close`],text:`I behold a strange, most glorious mystery: | heaven—the cave; | the cherubic throne—the Virgin; | the manger—the place where Christ lay: | the uncontainable God, Whom we magnify in song.`,prints:1,dates:[`2026-1121`],mateText:`A strange and most wondrous mystery do I see: * the cave is heaven; * the Virgin the throne of the cherubim; * the manger a room, in which Christ God, * whom nothing can contain, is laid. * Whom we praise and magnify.`,mateTones:[1],sections:[`Gospel`],others:[{mate:`menaion:11-30.c0.matins.canons[2].odes.9.items[5]`,mateHash:`m0621b00119d7e9`,score:.43,text:`We flee with faith to thy tender compassion, piously worshipping thy Son, O Virgin Birthgiver of God. Him do thou entreat as the God and Lord of all the world, that He deliver us from corruption, misfortune and every temptation. Katavasia: A strange and most wondrous mystery do I see: * the cave is heaven; * the Virgin the throne of the cherubim; * the manger a room, in which Christ God, * whom nothing can contain, is laid. * Whom we praise and magnify.`,tones:[1]},{mate:`octoechos:tone1.compline.thu.canon.odes.9.irmos`,mateHash:`m0e889bda9c7666`,score:.3,text:`Ineffable is the mystery of the Virgin: * for she is heaven and the throne of the cherubim, * and hath been revealed as the radiant bridal- chamber * of Christ God Almighty. * Wherefore we piously magnify her as the Theotokos.`,tones:[1]},{mate:`octoechos:tone1.nocturns.canon.odes.7.items[2]`,mateHash:`m1c7ef1cef51ca7`,score:.18,text:`The King of all, Who is up-borne upon the throne of the cherubim, made His abode within thy virginal womb, O most pure one, to deliver all from corruption, in that He is the Lover of mankind. Preserve us now by thy supplications.`,tones:[1]}]},o9f4537e8ec:{mate:`octoechos:tone6.great_vespers.aposticha[1]`,mateHash:`m1cd1518344aefd`,tone:6,score:.3,next:.27,evidence:[`wording 0.3 (next 0.27)`,`tone 6`,`place: vespers`],first:{doc:`2026-0913-texts-tt`,head:`Tone 6 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`Destroying the [gates] of hell, | breaking the [chains] of death, | Thou didst resurrect the fallen human race as al[might]y God! // O Lord Who didst rise from the dead, [glo]ry to thee!`,prints:2,dates:[`2026-0913`,`2026-1108`],mateText:`Thou as all-powerful God hast smashed the gates of brass and shattered the bars of Hades, * and Thou hast raised the fallen human race. * Therefore with one accord we also cry out to Thee: ** O Lord, risen from the dead, glory be to Thee!`,mateTones:[6],sections:[`Aposticha`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.7.tue_praises`,mateHash:`m0aaab6fb2d0346`,score:.27,text:`O Christ, Thou Light, * Thou didst spring forth from the Virgin, * and hast illumined the human race. ** O Lord, glory be to Thee!`,tones:[]},{mate:`octoechos:tone6.great_vespers.lic[4]`,mateHash:`m1b74c4d723ec79`,score:.26,text:`Ever blessing the Lord * we hymn His Resurrection; * for having endured the Cross, ** He hath destroyed death by death.`,tones:[6]},{mate:`octoechos:tone6.kontakion`,mateHash:`m024b20d887c63f`,score:.2,text:`Having raised all the dead from the valleys of darkness * by His life-giving hand, * Christ our God hath granted resurrection to the race of mankind. * For He is the Savior of all, * the Resurrection and the Life ** and the God of all.`,tones:[6]}]},oa06c521a85:{mate:`octoechos:tone4.little_vespers.lic[2]`,mateHash:`m12f8a32987ead6`,tone:4,score:.44,next:.28,evidence:[`wording 0.44 (next 0.28)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`],text:`Thou didst loose the Tree’s verdict of disobedience, O [Sav]ior, | by being voluntarily nailed to the [tree] of the Cross. | By de[scend]ing to hell, O al[might]y God, | Thou didst break the [bonds] of death. | Therefore, we adore Thy Resurrection from the [dead], [sing]ing in joy: // “Glory to Thee, O all-[pow]erful Lord!”`,prints:2,dates:[`2026-0830`,`2026-1025`],mateText:`By being willingly nailed to the tree of the Cross, O Savior, * Thou hast abolished the penalty of the tree of disobedience; * and by descending into Hades, O all- powerful One, * as God Thou hast torn asunder the bonds of death. * Wherefore we worship Thy Resurrection from the dead, and we cry out with joy: ** O all- powerful Lord, glory be to Thee!`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.matins.praises.stichera[0]`,mateHash:`m057ec2b1be319b`,score:.28,text:`O all-powerful Lord, * Who didst endure the Cross and death, * and arose from the dead, ** we glorify Thy Holy Resurrection.`,tones:[4]},{mate:`octoechos:tone4.compline.fri.canon.odes.8.items[2]`,mateHash:`m11faabc808b3c5`,score:.19,text:`Dry up the depths of mine evils, O thou who hast given birth to the Abyss of loving-kindness, the Redeemer and Lord, and before the end loose thou the bonds of mine evils, O thou who hast given birth to the Savior of all.`,tones:[4]}]},oa0db7e3374:{mate:`octoechos:tone6.matins.canon.odes.9.cross_resurrection.troparia[0]`,mateHash:`m119783e8885786`,tone:null,score:.4,next:.3,evidence:[`wording 0.4 (next 0.3)`,`tone not printed on one side`,`place: matins`],first:{doc:`2026-0914-texts-tt`,head:`Magnification`},why:[`wording below the bar`,`a second hymn is close`],text:`We magnify Thee, | O Christ, the Giver of life, | and we honor Thy precious Cross | by which Thou hast saved us | from the bondage of the enemy.`,prints:1,dates:[`2026-0914`],mateText:`Although Thou didst descend into the grave as one dead, O Life-giver, Thou didst destroy the power of Hades, Thou didst raise together with Thyself, O Christ, those who were in bondage therein, and as God Thou dost grant resurrection unto all who with faith and love magnify Thee.`,mateTones:[6],sections:[`Magnification`],others:[{mate:`octoechos:tone4.matins_weekday.wed.canons[0].odes.5.items[1]`,mateHash:`m1db31c5087c095`,score:.3,text:`Thy precious Cross is victory over the enemy, for Thou hast given it to us for the salvation our souls who hymn Thee with faith, O Word.`,tones:[4]},{mate:`octoechos:tone2.compline.mon.canon.odes.5.items[2]`,mateHash:`m09ddd74d0c28ff`,score:.29,text:`Thou hast released the whole race of mankind from bitter bondage, O Virgin, and hast honored the nature of women with the freedom of Christ in thy divine birthgiving.`,tones:[2]},{mate:`octoechos:tone7.matins.canon.odes.6.resurrection.troparia[0]`,mateHash:`m1d3592bdaa204c`,score:.24,text:`The souls of the righteous, who were held in bondage and forsaken in Hades, remembered Thee and prayed for salvation from Thee, which Thou didst grant unto them through Thy Cross, O Christ, when in Thy compassion Thou didst descend into the nether regions of the earth.`,tones:[7]}]},oa339e9faaf:{mate:`menaion:11-14.c0.vespers.lic_glory`,mateHash:`m0b505e84329c5b`,tone:6,score:.34,next:.23,evidence:[`wording 0.34 (next 0.23)`,`tone 6`,`place: vespers`,`same date`,`NAMES DIFFER: our text names Archetype; the OCA text does not`],first:{doc:`2026-1114-texts-tt`,head:`Tone 6 (by Byzantius)`},why:[`wording below the bar`,`a second hymn is close`,`our text names Archetype; the OCA text does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Thou didst burn with the brilliance of a great light, O Philip, | shining as a light of the universe. | Seeking the light of God, thou didst find illumination in the Son, | Whose image is equal to the First Image. // Implore Him, O Apostle, to save those sealed by divine blood!`,prints:1,dates:[`2026-1114`],mateText:`Burning with rays of the great Light, O Philip, thou didst shine forth as a universal beacon; and having sought, thou didst find the Father of lights within the Son, for light is revealed in light, just as a seal is identical, disclosing the Archetype. Him do thou beseech, O Philip, that we who have been sealed by His divine blood may be saved.`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone6.compline.sat.canon.odes.5.irmos`,mateHash:`m10a24aabae35d5`,score:.23,text:`O Christ Who shineth Thy light upon the world, * illumine my heart * for I cry out to Thee in the night, * and save me.`,tones:[6]},{mate:`octoechos:tone6.matins.anabathmoi[1].gloria`,mateHash:`m1e04ddf55ce0e0`,score:.19,text:`In the Holy Spirit all find divine inspiration, * goodness, understanding, peace and blessing; * for He is equal in activity ** to the Father and the Word.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.sat_praises`,mateHash:`m05d940b7572abd`,score:.19,text:`With the apostles and the martyrs, O Virgin, * pray thou that the departed ** find great mercy at the judgment.`,tones:[]}]},oa44c15737c:{mate:`menaion:11-21.c0.great_vespers.lic[3]`,mateHash:`m1183f12ea941e8`,tone:4,score:.47,next:.26,evidence:[`wording 0.47 (next 0.26)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 4 (As one valiant among martyrs)`},why:[`wording below the bar`],text:`Led by the Holy [Spir]it, | the holy Maiden without blemish is brought to dwell in the Holy of [Hol]ies, | where she is [fed] by an [an]gel. | She is truly the most holy Temple of our [ho]ly God, | Who has made all things holy by [dwell]ing in her, // and has made God-like the fallen nature of [mor]tals.`,prints:1,dates:[`2026-1121`],mateText:`Into the Holy of holies * is the holy and immaculate one * led by the Holy Spirit; * and she is fed by a holy angel, * in that she is the most holy temple * of our holy God, * Who hath sanctified all things by her entry * and hath deified the nature of mortal men ** which had fallen.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-20.c0.matins.canons[0].odes.1.items[0]`,mateHash:`m1a3306b003b6dc`,score:.26,text:`The all-holy and immaculate one cometh forth to make her abode within the Holy of holies, that she may become the sanctified temple of our Most holy God; and virgin maidens precede her.`,tones:[4]},{mate:`menaion:11-20.c0.vespers.lic_closer`,mateHash:`m11012d27bb282a`,score:.23,text:`Today the Theotokos, the temple which contained God, is brought into the temple of the Lord, and Zachariah receiveth her; today the Holy of holies rejoiceth, and the choir of the angels doth mystically keep festival. And we, celebrating with them today, cry out with Gabriel: Rejoice, O thou who art full of grace! The Lord Who hath great mercy, is with thee!`,tones:[4]},{mate:`menaion:11-20.c0.matins.canons[0].odes.4.items[0]`,mateHash:`m0907838e0239b1`,score:.22,text:`Sacred tongues proclaimed thee beforehand to be the dwelling of Him Who is infinite in nature, O pure one. Wherefore, choirs of virgins accompany thee to the Holy of holies, bearing lamps.`,tones:[4]}]},oa4879033f3:{mate:`octoechos:tone8.great_vespers.lic[6]`,mateHash:`m089fac58888af0`,tone:8,score:.42,next:.29,evidence:[`wording 0.42 (next 0.29)`,`tone 8`,`place: vespers`],first:{doc:`2026-0927-texts-tt--`,head:`Tone 8 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`We [glo]rify [Thee], O Lord, | for Thou didst voluntarily endure the [Cross] for our sake. | We fall down in worship before Thee, O al[might]y [Sav]ior. | Do not cast us a[way] from Thy face | but hear us and save us, O [Lov]er of man, // by Thy Resur[rec]tion!`,prints:1,dates:[`2026-0927`],mateText:`We glorify Thee, O Lord, * and we worship Thee, O all-powerful Savior, * who willingly endured the Cross for our sake; * cast us not away from Thy presence, * but hearken unto us and save us through Thy Resurrection, ** O only Lover of mankind.`,mateTones:[8],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone8.matins.canon.odes.5.cross_resurrection.troparia[0]`,mateHash:`m0063e957852be8`,score:.29,text:`Guide us and grant us peace by the power of Thy Cross, O Christ, for by it we fall down before Thee, O Lover of mankind.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.mon.canons[0].odes.6.items[3]`,mateHash:`m17db392202f80f`,score:.29,text:`Thou didst show Thy martyrs to be mighty in Thy power, O Lord, and they cast down all the power of him who of old caused man to fall. By their prayers, O Lord, save Thou our souls.`,tones:[8]},{mate:`octoechos:tone8.vespers_weekday.tue.lic.octoechos[1]`,mateHash:`m0c2f3c2ca09ee6`,score:.27,text:`Thou didst endure suffering, O Master, that Thou mightest bestow dispassion upon all who worship Thy sufferings and voluntary sacrifice: the spear, nails and reed, which Thou didst willingly endure with long-suffering: that for the sake of Thy sufferings, O Lord, Thou mightest win dispassion for me.`,tones:[8]}]},oa9028a7f61:{mate:`menaion:11-14.c0.vespers.lic[0]`,mateHash:`m146c2a1140dd23`,tone:6,score:.36,next:.18,evidence:[`wording 0.36 (next 0.18)`,`tone 6`,`place: vespers`,`same date`],first:{doc:`2026-1114-texts-tt`,head:`Tone 6 (Having placed all their hope)`},why:[`wording below the bar`],text:`Having established action, O blessed one, | as an entrance into true vision, | and vision as the end of divine action, | thou didst implore Christ to show thee the ineffable glory of the Father, | for every reasonable creature desires witness of God. | Thou didst receive Him Whom thou didst desire, O glorious one, | of Whom the Son is the image. // Pray to Him boldly for our souls!`,prints:1,dates:[`2026-1114`],mateText:`Having made activity * the ascent to true vision, * and the end of vision, love for God, * O blessed one, * thou didst beseech Christ * to show thee the ineffable glory of the Father, * for every rational being, O glorious one, * doth desire God the Creator, * and thou didst obtain * that which thou didst desire, * straightway receiving the seal of His Son. ** Entreat Him with boldness on behalf of our souls.`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`menaion:11-28.c0.compline.canon.odes.4.items[2]`,mateHash:`m1ef8578324ac1d`,score:.18,text:`The deep, receiving thee, in no wise covered thee, O all-blessed martyr, recognizing thee as a godly witness of the divine sufferings of Christ most true, O Irenarchus.`,tones:[6]},{mate:`menaion:11-14.c0.vespers.lic[1]`,mateHash:`m1285fbbd493e84`,score:.16,text:`Ever instructed * by divine ascents, * as Moses had been in the past, * thou didst desire to behold God; * and noetically thou didst behold His image, * having received His likeness. * For the Son is the immaculate knowledge * and disclosure of the Father; * and the Son is known to be * of the same essence as the Father, * and their unity, kingdom, power, glory and worship ** are exalted with honor by all.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.fri_eve_aposticha`,mateHash:`m1112a8d2de94d8`,score:.16,text:`To thee do we pray, as the Mother of God: * O blessed one, ** pray thou for the salvation of our souls!`,tones:[]}]},oabd0ebc81a:{mate:`octoechos:tone6.little_vespers.lic[2]`,mateHash:`m1d8c80a84ef395`,tone:6,score:.42,next:.25,evidence:[`wording 0.42 (next 0.25)`,`tone 6`,`place: vespers`],first:{doc:`2026-0913-texts-tt`,head:`Tone 6 (for the Resurrection)`},why:[`wording below the bar`],text:`Today Christ [tram]ples on death, | for He is [ris]en as He said! | Let us all [sing] this song, | for He has granted [joy] to the world: | O Light unapproachable, O [Foun]tain of life! // O Savior almighty, have [mer]cy on us!`,prints:2,dates:[`2026-0913`,`2026-1108`],mateText:`Today Christ, having trampled on death, * hath arisen as He foretold, * granting joy to the world, * that we may all shout aloud the hymn and say: * O Source of life, O unapproachable Light, * O all-powerful Savior, ** have mercy upon us.`,mateTones:[6],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone6.matins.praises.stichera[2]`,mateHash:`m090ad8b18cd499`,score:.25,text:`With the Father and the Spirit * let us hymn Christ risen from the dead, * and let us cry out to Him: ** “Thou art our Life and Resurrection, have mercy upon us.”`,tones:[6]},{mate:`octoechos:tone6.matins.praises.stichera[0]`,mateHash:`m02360e7b1f9797`,score:.21,text:`Thy Cross, O Lord, * is the Life and Resurrection of Thy people, * and trusting in it we sing Thy praises: ** O our risen God, have mercy upon us.`,tones:[6]},{mate:`octoechos:tone6.little_vespers.lic[3]`,mateHash:`m0928e5db456616`,score:.2,text:`Where shall we sinners escape Thee, O Lord, * who art present in all creation? * In heaven? Thou dwellest there. * In Hades? There Thou didst trample on death. * In the depths of the sea? Thy hand is also there O Master. * To Thee we flee and falling down before Thee we implore: ** O Lord risen from the dead, have mercy upon us.`,tones:[6]}]},oae52052f60:{mate:`menaion:09-08.c0.matins.megalynarion`,mateHash:`m177fb878bfff55`,tone:2,score:.35,next:.34,evidence:[`wording 0.35 (next 0.34)`,`tone not printed on one side`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 9 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`Magnify, O my soul, the most glorious birth of the Mother of God!`,prints:3,dates:[`2026-0908`,`2026-0909`],mateText:`We magnify thee, O most holy Virgin, we honor thy holy parents, and we glorify thy most glorious nativity.`,mateTones:[],sections:[`Gospel`,`Instead of “It is truly meet…,” we sing:`],others:[{mate:`octoechos:tone8.compline.wed.canon.odes.9.items[2]`,mateHash:`m0963d45d6c9f60`,score:.34,text:`O pure and most glorious Mother of God, save those who hymn thee with love from all perils, mercifully subduing our turmoil, in that thou hast given birth unto God; for thou canst freely do all that thou dost desire, O Virgin. Wherefore, we all magnify thee.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.fri.canons[1].odes.9.items[3]`,mateHash:`m1eba5a984b6f0c`,score:.34,text:`O pure and most glorious Mother of God, save those who hymn thee with love, mercifully quelling the tumults of temptation; for as thou hast given birth unto God, O Virgin, thou art able to do whatsoever dost will, and freely grantest mercy. Wherefore, we all magnify thee.`,tones:[8]},{mate:`octoechos:tone2.matins_weekday.mon.canons[1].odes.9.irmos`,mateHash:`m1db02993438604`,score:.32,text:`Thou art all desire, Thou art all sweetness, * O Word of God, Son of the Virgin, * God of gods, most holy Lord of the saints. * Wherefore, we magnify Thee * and her who hath given birth to Thee.`,tones:[2]}]},ob0161a35c9:{mate:`octoechos:tone3.vespers_weekday.mon.aposticha.items[2]`,mateHash:`m09286e670a307c`,tone:3,score:.33,next:.17,evidence:[`wording 0.33 (next 0.17)`,`tone 3`,`place: vespers`],first:{doc:`2026-1024-texts-tt`,head:`Tone 3 (for the Martyrs, in the Tone of the week)`},why:[`wording below the bar`],text:`Great is the power of Thy [mar]tyrs, O Christ, | for, though they lie in their tombs, they drive out [de]mons. | They fight in defense of true [pi]ety, // subduing the Enemy’s dominion by [faith] in the [Trin]ity.`,prints:1,dates:[`2026-1024`],mateText:`Great is the power of Thy martyrs, O Christ; for while lying in their graves they drive evil spirits away; and, having struggled for piety with their faith in the Trinity, they abolished the authority of the enemy.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone3.matins_weekday.thu.canons[0].odes.1.items[2]`,mateHash:`m07f5b0cf0653a1`,score:.17,text:`O steadfast pillars of piety, set me aright who am ensnared by the deception of the enemy, for I lie upon the ground in affliction, and know not what to do to find remission for those things in which I have sinned.`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.tue.canons[0].odes.9.items[3]`,mateHash:`m05164a2d253932`,score:.16,text:`O godly martyrs of Christ, ye were shown to be sharp-edged swords cutting down the hordes of the enemy, vessels containing the radiance of the Holy Trinity, lamps shedding the light of piety upon the faithful, and true warriors of the noetic Sion.`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.wed.aposticha.items[2]`,mateHash:`m0e277814d69c6f`,score:.16,text:`Having fought the good fight, even after death ye shine in the world like beacons, O holy martyrs; wherefore, possessed of boldness, entreat Christ to have mercy on our souls.`,tones:[3]}]},ob2c2845aad:{mate:`menaion:11-16.c0.great_vespers.aposticha[3]`,mateHash:`m04f18e50cabdf5`,tone:4,score:.3,next:.27,evidence:[`wording 0.3 (next 0.27)`,`tone 4`],first:{doc:`2026-0913-texts-tt`,head:`Tone 4 Troparion (Founding)`},why:[`wording below the bar`,`a second hymn is close`],text:`Thou hast revealed the beauty of the holy dwelling place of Thy [glo]ry on earth | to be like the splendor of the heavenly [firm]ament, O Lord. | Through the prayers of the Theo[to]kos, | strengthen it for ever and [ev]er | and accept our suppli[ca]tion | which we ceaselessly [of]fer Thee therein, // the life and resur[rec]tion of all!`,prints:3,dates:[`2026-0913`],mateText:`The heavens declare the glory of God, * and the firmament proclaimeth the work of His hands.`,mateTones:[1,4,5],sections:[`at Great Vespers`,`at Vigil`,`at the Divine Liturgy`],others:[{mate:`menaion:09-07.c0.matins.canons[1].odes.1.items[1]`,mateHash:`m0c0f6278157776`,score:.27,text:`Christ hath truly revealed thee to be a most radiant star in the firmament of the Church, O all-famed martyr, illumining the whole world with the splendors of thy sufferings.`,tones:[4]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_lauds`,mateHash:`m0835d754800ce2`,score:.22,text:`Through the prayers of the Theotokos, * grant peace to the life of us who cry out to Thee: ** O merciful Lord, glory be to Thee!`,tones:[]},{mate:`octoechos:tone4.matins_weekday.wed.canons[1].odes.4.items[2]`,mateHash:`m0baf90531b2ea5`,score:.18,text:`I now entreat thee, the animate palace of the heavenly King: By thy supplications show me, who remain a den of thieves, to be a dwelling-place of the Holy Trinity.`,tones:[4]}]},ob3fa11743e:{mate:`menaion:09-08.c0.matins.praises[0]`,mateHash:`m1e5b2c2ff881da`,tone:1,score:.45,next:.26,evidence:[`wording 0.45 (next 0.26)`,`tone 1`,`place: matins`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 1 [(Oh, the Marvelous Wonder)]`},why:[`wording below the bar`],text:`[Oh], the marvelous [won]der! | The source of Life is born of a barren [wom]an, | and [grace] gloriously begins to [bear] its fruit. | Rejoice, Joachim, who have become the father of the [The]o[to]kos! | There is no [oth]er like thee among earthborn fathers, O man in[spired] by God; | for the Maiden in whom God would [come] to dwell, | the [Tab]ernacle of God, the all-holy [Moun]tain, // has been given to [us] through thee.`,prints:1,dates:[`2026-0908`],mateText:`O wondrous miracle! The well-spring of Life is born of the barren woman, and grace doth splendidly begin to bring forth fruit. Be glad, O Joachim, as thou art the father of the Theotokos! There is none to compare with thee among mortal parents, O God-pleaser! For the maiden who contained God, the divine dwelling place, the most holy mountain, hath been given to us by thee!`,mateTones:[1],sections:[`The Praises Tone 1`],others:[{mate:`menaion:09-08.c0.ikos`,mateHash:`m0cf6c0c14be734`,score:.26,text:`The supplication of Joachim over his childlessness, together with the sighing of Anna over her barrenness, were right acceptable to God: they entered the ears of the Lord and brought forth life-bearing fruit for the world. For the one made supplication on the mountain, and the other bore her reproach in the garden; and with joy the barren woman giveth birth to the Theotokos, the nurturer of our Life.`,tones:[]},{mate:`menaion:09-05.c1.vespers.aposticha[4]`,mateHash:`m0472c03db5e312`,score:.2,text:`A most glorious fruit of the womb was given by the most compassionate God to thee, a woman barren and past childbearing: the preacher of repentance. Wherefore, calling thee blessed, we magnify the almighty mercy of God.`,tones:[1]},{mate:`menaion:11-21.c0.matins.canons[1].odes.9.items[1]`,mateHash:`m16f502128517e0`,score:.18,text:`The divine maiden Mary, the fruit of the promise, issued forth from the righteous Joachim and Anna, and, a babe in the flesh, she is brought into the holy sanctuary like pleasing incense, to dwell in the Holy of holies.`,tones:[1]}]},ob74df9fdc1:{mate:`octoechos:tone2.matins_weekday.fri.sessionals[0].items[0]`,mateHash:`m01ebd1c7351183`,tone:null,score:.38,next:.34,evidence:[`wording 0.38 (next 0.34)`,`tone not printed on one side`],first:{doc:`2026-0914-texts-tt`,head:`The Second Antiphon`},why:[`wording below the bar`,`a second hymn is close`],text:`God is our King before the ages; He has worked salvation in the midst of the earth. (Ps. 73:13) (Refrain)`,prints:1,dates:[`2026-0914`],mateText:`Thou didst work salvation in the midst of the earth, O Christ God, and on the Cross didst stretch out Thy most pure hands, gathering to Thee all the nations, who cry: Glory to Thee, O Lord!`,mateTones:[2],sections:[`The Second Antiphon`],others:[{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.8.items[4]`,mateHash:`m19a196ac93c3f6`,score:.34,text:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,tones:[1,2,3,4,5,6,7,8]},{mate:`octoechos:tone4.compline.mon.canon.odes.8.irmos`,mateHash:`m14943ac74b257e`,score:.23,text:`O almighty Redeemer of all, * having descended and bedewed the children * in the midst of the flame, * Thou didst teach them to sing: * All ye works bless and hymn the Lord.`,tones:[4]},{mate:`octoechos:tone8.matins.canon.odes.7.cross_resurrection.troparia[0]`,mateHash:`m12b4717f74ba0b`,score:.22,text:`Thou hast wrought salvation in the midst of the inhabited world, O God, as the prophet said, for lifted up upon the Tree, Thou hast called back all those who cry out to Thee with faith; “O God of our fathers, blessed art Thou!”`,tones:[8]}]},ob95fafe36d:{mate:`octoechos:tone4.vespers_weekday.tue.aposticha.items[0]`,mateHash:`m04284157afbe07`,tone:4,score:.3,next:.22,evidence:[`wording 0.3 (next 0.22)`,`tone 4`,`NAMES DIFFER: the OCA text names Orthodox; ours does not`],first:{doc:`2026-0914-texts-tt`,head:`Tone 4 Kontakion`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Orthodox; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`As Thou wast voluntarily raised upon the [Cross] for our sake, | grant mercy to those who are called by Thy Name, O [Christ] God; | make all Orthodox Christians glad by Thy [pow]er, | granting them victories over their [ad]versaries // by bestowing on them the invincible trophy, Thy [weap]on of peace!`,prints:3,dates:[`2026-0914`,`2026-0920`],mateText:`Thou hast given Thy Cross to us as an invincible weapon, O Christ; and with it we triumph over the assaults of the alien one.`,mateTones:[4],sections:[`“Having beheld the Resurrection of Christ…” [is] sung, and then Psalm 50.`,`Entrance Verse`,`at the Divine Liturgy`],others:[{mate:`menaion:09-07.c0.matins.canons[1].odes.5.items[3]`,mateHash:`m144d73b5508b75`,score:.22,text:`We hold thee as an invincible weapon against the enemy, and we have thee as the foundation and hope of our salvation, O Bride of God.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.wed.canons[0].odes.5.items[1]`,mateHash:`m1db31c5087c095`,score:.19,text:`Thy precious Cross is victory over the enemy, for Thou hast given it to us for the salvation our souls who hymn Thee with faith, O Word.`,tones:[4]},{mate:`octoechos:tone4.compline.sat.canon.odes.3.items[0]`,mateHash:`m13aa08f1c2ff0f`,score:.18,text:`Having acquired thee as a mighty weapon and a rampart, O Theotokos who knewest not wedlock, I vanquish the hordes of the adversary and hymn thy mighty works.`,tones:[4]}]},ob998fd4e9e:{mate:`menaion:09-06.c0.troparion`,mateHash:`m12e32b935bf78a`,tone:4,score:.66,next:.3,evidence:[`wording 0.66 (next 0.3)`,`tone 4`,`same date`,`NAMES DIFFER: the OCA text names Michael; ours does not`],first:{doc:`2026-0906-texts-tt`,head:`Tone 4 Troparion (Archangel Michael)`},why:[`the OCA text names Michael; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`O Michael, commander of the [heav]enly hosts, | we who are unworthy be[seech] thee: | by thy prayers encompass us beneath the wings of thine immaterial [glo]ry, | and faithfully preserve us who fall down and cry [out] to thee: // “Deliver us from all harm, for thou art the commander of the [Pow]ers on high!”`,prints:2,dates:[`2026-0906`],mateText:`O supreme commander of the heavenly hosts, * we entreat thee unworthy though we be, * that by thy prayers, thou wilt encompass us * with the protection of the wings of thine immaterial glory * preserving us who fall down before thee and earnestly cry aloud: * deliver us from all misfortunes, ** for thou art the supreme commander of the hosts on high.`,mateTones:[4],sections:[`at Great Vespers`,`at the Divine Liturgy`],others:[{mate:`menaion:09-06.c0.vespers.lic[0]`,mateHash:`m1345b802904133`,score:.3,text:`O Michael, supreme commander, * shown forth as a most radiant intercessor before the three-Sunned Godhead, * thou dost cry out, rejoicing with the heavenly hosts: * Holy art Thou, O Father! * Holy art Thou, O co-beginningless Son! * Holy art Thou also, O Holy Spirit! * One glory, * one Kingdom and nature, ** one Godhead and power!`,tones:[4]},{mate:`menaion:09-06.c0.matins.canons[0].odes.8.items[0]`,mateHash:`m016dfbb3c91ee4`,score:.23,text:`O Michael, thou hast been shown to be a commander of the noetic and incorporeal hosts, a saving intercessor for all mankind, a divine servant of God, chanting unceasingly: All ye works, bless and hymn the Lord!`,tones:[4]},{mate:`menaion:09-06.c0.ikos`,mateHash:`m00cb68d20734e2`,score:.2,text:`In Thy Scriptures, O immortal Lover of mankind, Thou didst say that a multitude of angels rejoiceth in heaven over one man that repenteth. Wherefore, O Sinless One, Who alone knowest the hearts of men, amid our transgressions we ever make bold to beseech Thee to have compassion and to send down compunction upon us, unworthy though we be, granting us forgiveness, O Master, in that Thou art compassionate; for the supreme commander of the bodiless hosts doth entreat Thee on behalf of us all.`,tones:[]}]},ob9d8980306:{mate:`menaion:09-06.c0.kontakion`,mateHash:`m0089223dcd2dc6`,tone:2,score:.45,next:.21,evidence:[`wording 0.45 (next 0.21)`,`tone 2`,`same date`,`NAMES DIFFER: the OCA text names Michael; ours does not`],first:{doc:`2026-0906-texts-tt`,head:`Tone 2 Kontakion (Archangel Michael)`},why:[`wording below the bar`,`the OCA text names Michael; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`O [Mich]ael, commander of God’s [ar]mies | and minister of the divine [glo]ry, | [prin]ce of the bodiless [an]gels | and [guide] of mankind; | [ask] for what is good for us, and for great [mer]cy, // as the supreme com[mand]er of the [Bod]iless Hosts.`,prints:1,dates:[`2026-0906`],mateText:`O chief commander of God, minister of divine glory, * captain of the angels and instructor of all mankind: * beg thou great mercy and that which is profitable for us, * for thou art the supreme commander ** of the bodiless hosts.`,mateTones:[2],sections:[`at the Divine Liturgy`],others:[{mate:`menaion:09-06.c0.ikos`,mateHash:`m00cb68d20734e2`,score:.21,text:`In Thy Scriptures, O immortal Lover of mankind, Thou didst say that a multitude of angels rejoiceth in heaven over one man that repenteth. Wherefore, O Sinless One, Who alone knowest the hearts of men, amid our transgressions we ever make bold to beseech Thee to have compassion and to send down compunction upon us, unworthy though we be, granting us forgiveness, O Master, in that Thou art compassionate; for the supreme commander of the bodiless hosts doth entreat Thee on behalf of us all.`,tones:[]},{mate:`menaion:09-06.c0.liturgy.beatitudes[3]`,mateHash:`m07704f843af885`,score:.18,text:`The multitude of the faithful rejoiceth, praising thee, O Michael, and it doth glorify the most holy Word Who in His goodness hath united men and angels.`,tones:[]},{mate:`octoechos:tone2.matins_weekday.mon.canons[1].odes.1.items[3]`,mateHash:`m16ecc5950872bd`,score:.18,text:`Rejoicing, O pure Virgin, the ranks of the angels ministered at thy birthgiving, which transcendeth nature; for thou hast given birth to their God and Lord.`,tones:[2]}]},obbc631f7e2:{mate:`menaion:11-22.c0.vespers.aposticha[2]`,mateHash:`m117e1cf733bccc`,tone:2,score:.48,next:.41,evidence:[`wording 0.48 (next 0.41)`,`tone 2`,`place: vespers`,`melody “O house of Ephratha ...”`,`same date`],first:{doc:`2026-1122-texts-tt`,head:`Tone 2 (for the Feast) (O House of Ephratha)`},why:[`wording below the bar`,`a second hymn is close`],text:`The prophet pro[claimed] thee | as the spiritual [moun]tain, | the [ho]ly [ta]ble, | the ladder and jar of [man]na, // O only all-pure [Vir]gin.`,prints:1,dates:[`2026-1122`],mateText:`O prophet, receive her * who alone is all-immaculate: * the noetic mountain, * the divine table, ** the bridge and the jar.`,mateTones:[2],sections:[`Litya`],others:[{mate:`octoechos:tone2.compline.fri.canon.odes.3.items[0]`,mateHash:`m06cb5eb1bcca04`,score:.41,text:`O Virgin, we truly call thee the golden censer, the jar of the Manna, the divine mountain, the all-comely palace.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.wed.canons[1].odes.3.items[0]`,mateHash:`m021b0475562863`,score:.4,text:`O Virgin, we all truly call thee the golden censer, the jar of manna, the mountain of God and the divine and beauteous palace.`,tones:[2]},{mate:`octoechos:theotokia.doxasticon_theotokia.4.sun_eve_aposticha`,mateHash:`m097dc98a39478e`,score:.39,text:`Rejoice, O cloud of Light! * Rejoice, radiant candlestick! * Rejoice, jar wherein the Manna was kept! * Rejoice, staff of Aaron! * Rejoice, bush un-burnt! * Rejoice, bridalchamber! * Rejoice, thou throne! * Rejoice, holy mountain! * Rejoice, refuge! Rejoice, divine table! * Rejoice, mystic portal! ** Rejoice, thou joy of all!`,tones:[]}]},obfe637964c:{mate:`octoechos:tone8.vespers_weekday.thu.lic.octoechos[1]`,mateHash:`m17b429794acbfd`,tone:8,score:.38,next:.22,evidence:[`wording 0.38 (next 0.22)`,`tone 8`,`PLACE DIFFERS: OCA prints it at matins, the mate is at vespers`,`melody “O most glorious wonder”`],first:{doc:`2026-0914-texts-tt`,head:`Tone 8 (Oh, most glorious wonder)`},why:[`wording below the bar`],text:`Oh, most [glo]rious [won]der! | The Cross that carried the [Most] High | like a cluster of [grapes] [filled] with life | today is seen raised a[bove] the earth. | Through this we have all been [drawn] to God, | and death is [fin]ally [swal]lowed up. | O im[mac]ulate Wood! | Through thee we enjoy the immortal food of [E]den // as we give [glo]ry to Christ!`,prints:1,dates:[`2026-0914`],mateText:`O most glorious wonder! * Like a vine full of life, * bearing the Most High, * the Cross is seen today uplifted from the earth. * Thereby have we all been drawn to God, * and death hath been utterly slaughtered. * O most honored Tree, * whereby, glorifying Christ, * we have received the immortal sustenance ** which was in Eden!`,mateTones:[8],sections:[`The Praises Tone 8`],others:[{mate:`octoechos:tone8.matins.canon.odes.1.theotokos.troparia[1]`,mateHash:`m0bbc880f1de3ef`,score:.22,text:`The Virgin hath given birth unto Thee, O Christ, the cluster of grapes from whence drippeth the life-bearing sweetness of the world’s salvation.`,tones:[8]},{mate:`octoechos:tone8.vespers_weekday.thu.lic.octoechos[0]`,mateHash:`m174e1c967ec1aa`,score:.16,text:`O most glorious wonder! * The Life-bearing Tree, * the most holy Cross is revealed today, * lifted up on high. * All the ends of the earth glorify it, * and the hordes of the demons are affrighted. * O what a gift hath been given to mortals! * Thereby, O Christ, save Thou our souls, ** in that Thou alone art compassionate.`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.wed.sessionals[2].items[1]`,mateHash:`m1aabc53619f088`,score:.16,text:`The tree in Eden once gave rise to bitterness, but the tree of the Cross hath blossomed forth sweet life; for Adam, eating, fell headlong into corruption, but we, enjoying the fruit of Christ, are enlivened and mystically deified, receiving the eternal kingdom of God. Wherefore, we cry out with faith: Glory to Thy sufferings, O Word.`,tones:[8]}]},oc38efa1e9d:{mate:`menaion:11-15.c0.vespers.lic[2]`,mateHash:`m09bb64f28b1cd0`,tone:4,score:.5,next:.16,evidence:[`wording 0.5 (next 0.16)`,`tone 4`,`place: vespers`,`melody “Thou hast given a sign ...”`,`same date`],first:{doc:`2026-1115-texts-tt-`,head:`Tone 4 (for the Martyrs) (Thou hast given a sign)`},why:[`wording below the bar`],text:`Having gone over to the serene [har]bor, | to the quiet life and to the all-tranquil [ha]ven, | you have ex[changed] your pains for abiding dis[pas]sion, | and have received fitting [hon]ors | as a reward from [God] for your [la]bors, // O blessed passion-bearing [mar]tyrs.`,prints:1,dates:[`2026-1115`],mateText:`Having put in at the calm haven, * life untroubled * and right tranquil serenity, * O blessed passion-bearing martyrs, * ye have now exchanged * that which is below * for an abiding sojourn in dispassion, * receiving honors from God, as is meet, ** as reward for your labors and pangs.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.compline.wed.canon.odes.3.items[2]`,mateHash:`m02be15e1264cba`,score:.16,text:`Tempest-tossed amid the deep of my many transgressions, passions and temptations, O all-immaculate one, by thine aid I hasten to the most tranquil haven.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.fri.canons[0].odes.8.items[2]`,mateHash:`m04e804b33c9570`,score:.15,text:`O most comely martyrs, ye mounted your blood like a chariot and were taken up to the habitations of heaven, receiving fitting honors from Christ, and crying aloud: Hymn the Lord and supremely exalt Him throughout the ages!`,tones:[4]},{mate:`octoechos:tone4.compline.sat.canon.odes.1.items[1]`,mateHash:`m0626716e719602`,score:.14,text:`Ignorant though I am, I have found thee to be a tranquil haven repelling dangers and violent assaults, O thou who hast given birth to the God-man, and I chant hymns of thanksgiving unto thee.`,tones:[4]}]},oc826b823e9:{mate:`octoechos:tone2.little_vespers.lic[2]`,mateHash:`m018cfd78cbbda2`,tone:2,score:.42,next:.27,evidence:[`wording 0.42 (next 0.27)`,`tone 2`,`place: vespers`],first:{doc:`2026-1011-texts-tt`,head:`Tone 2 (for the Resurrection)`},why:[`wording below the bar`],text:`Christ our [Sav]ior | nailed to the Cross the bond a[gainst] us, | He [void]ed it and destroyed the do[min]ion of death. // We fall down before His Resurrection on the [third] day.`,prints:2,dates:[`2026-1011`,`2026-1206`],mateText:`Christ our Savior by nailing the record against us to the Cross * hath blotted it out, * and destroyed the might of death. ** We worship His arising on the third day.`,mateTones:[2],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.7.tue_vespers_wed_matins`,mateHash:`m005c8e536cdc0c`,score:.27,text:`Christ God Who wast crucified for us and destroyed the dominion of death, * do thou unceasingly entreat, O Virgin Theotokos, ** that He save our souls.`,tones:[]},{mate:`octoechos:tone2.matins.canon.odes.8.cross_resurrection.troparia[0]`,mateHash:`m0b0c496a3fe519`,score:.22,text:`O Lover of mankind, who art rich in mercy, Thou wast seen nailed to the Cross, and willingly buried and didst arise on the third day, redeeming all mortal mankind who singeth unto Thee in faith: “Let all creation hymn the Lord, and supremely exalt him throughout all ages.”`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.fri.canons[0].odes.7.items[0]`,mateHash:`m16fe42593ab46f`,score:.21,text:`When Thou wast lifted up upon the Cross, O Word Who art the resurrection and uplifting of all, Thou didst raise me up who had fallen through disobedience; casting down the adversary who caused me to fall, and showing him to be wholly impotent and dead. Glory to Thy dominion!`,tones:[2]}]},oc9a817bfb6:{mate:`menaion:11-14.c1.great_vespers.aposticha_closer`,mateHash:`m1f4ae4c725b616`,tone:4,score:.39,next:.2,evidence:[`wording 0.39 (next 0.2)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (Theotokion)`},why:[`wording below the bar`],text:`Look on the entreaties of thy servants, O [Blame]less One! | Stop all the terrible attacks a[gainst] us, | [free]ing us from every af[flic]tion, | for we have only thee as our sure and firm [an]chor! | Do not let us be put to [shame], O [La]dy, | for we call on thee for our inter[ces]sion! | Hasten to pray for those who [call] in faith: | “Rejoice, O [La]dy, [Help] of all: // the Joy and Shelter and Sal[va]tion of our souls!”`,prints:4,dates:[`2026-0830`,`2026-1011`,`2026-1027`],mateText:`Mercifully regard the supplications of thy servants, * O all-immaculate one, * quelling the cruel uprisings of the demons against us, * delivering us from every sorrow; * for thee alone do we have as a steadfast and sure confirmation, * and having acquired thine intercession; * let not us who call upon thee be put to shame, * O Lady. * Hasten thou to answer the entreaties of those who cry out to thee with faith: * Rejoice, thou help, joy and protection of all, ** and the salvation of our souls!`,mateTones:[4],sections:[`Aposticha`],others:[{mate:`octoechos:tone4.compline.mon.canon.odes.6.items[1]`,mateHash:`m1cfd05b48f4c5b`,score:.2,text:`Heal thou the wounds of my soul, O Virgin Lady; help me, and deliver thy servant from slander, attack and unjust assault.`,tones:[4]},{mate:`octoechos:tone4.matins.canon.odes.5.resurrection.closer`,mateHash:`m1717ba472b75fc`,score:.2,text:`We have gained thee as our anchor and the hope of our salvation, O Bride of God, for thee we set forth as an unconquerable weapon against our foes.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.thu.canons[1].odes.5.items[2]`,mateHash:`m0f2bb16145a579`,score:.18,text:`In that I have a soul broken by the passions of life, I call upon thee for help, O sacred Nicholas: Hasten thou, and grant me perfect healing, entreating the supremely good One!`,tones:[4]}]},ocbb3914a00:{mate:`octoechos:tone2.matins_weekday.wed.canons[0].odes.6.irmos`,mateHash:`m02bfb49cfde708`,tone:2,score:.5,next:.21,evidence:[`wording 0.5 (next 0.21)`,`tone 2`,`place: matins`,`same date`,`NAMES DIFFER: our text names Redeemer; the OCA text does not`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 6 – Heirmos`},why:[`our text names Redeemer; the OCA text does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`From within the belly of the whale Jonah cried to the Lord: | “Lead me up, I pray Thee, from the depths of hell, | that with a voice of praise | and in the Spirit of truth // I may sacrifice to Thee as my Deliverer!”`,prints:1,dates:[`2026-0908`],mateText:`From within the sea monster Jonah cried unto the Lord: * “Lead me up from the abyss of Hades, I pray Thee; * for with a voice of praise as to my Redeemer, * in the spirit of truth * I offer myself to Thee.”`,mateTones:[2],sections:[`Gospel`],others:[{mate:`octoechos:tone2.matins_weekday.tue.canons[0].odes.6.irmos`,mateHash:`m186f3d3570e3e2`,score:.21,text:`I am held fast in the depths of sin O Savior, * and am overwhelmed by the sea of life, * but as Jonah was delivered from the sea-monster, * so also deliver me from the passions, * and save me.`,tones:[2]},{mate:`octoechos:tone2.matins_weekday.tue.canons[1].odes.6.items[0]`,mateHash:`m1a23769f2e0ae9`,score:.17,text:`O voice who proclaimed the Word, accepting the cries of us all, ask that He grant forgiveness of sins unto those who hymn Him with faith.`,tones:[2]}]},occaa93275b:{mate:`octoechos:tone2.kontakion`,mateHash:`m1de1daa05d7040`,tone:2,score:.48,next:.17,evidence:[`wording 0.48 (next 0.17)`,`tone 2`],first:{doc:`2026-1011-texts-tt`,head:`Tone 2 Kontakion (Resurrection)`},why:[`wording below the bar`],text:`[Hell] became afraid, O almighty [Sav]ior, | seeing the miracle of Thy Resur[rec]tion from the tomb! | The [dead] arose! Creation, with Adam, beheld this and re[joiced] with Thee, // and the world, my Savior, praises [Thee] for[ev]er.`,prints:2,dates:[`2026-1011`,`2026-1206`],mateText:`Thou didst arise from the tomb, * O all-powerful Savior, * and seeing the marvel Hades was struck with fear, * the dead arose, and creation with Adam seeing this rejoiceth with Thee, ** therefore the world doth glorify Thee, my Savior.`,mateTones:[2],sections:[`at the Divine Liturgy`],others:[{mate:`octoechos:tone2.liturgy.beatitudes.troparia[3]`,mateHash:`m080647a3d75858`,score:.17,text:`By Thy death, O Lord, death hath been swallowed up, and by Thy Resurrection, O Savior, Thou hast saved the world.`,tones:[2]},{mate:`octoechos:tone2.little_vespers.aposticha.resurrection[0]`,mateHash:`m094aa8c3044bcd`,score:.17,text:`Thy Resurrection, O Christ our Savior, * hath enlightened the whole inhabited world; * and by it Thou hast called back Thine own creation. ** O all-powerful Lord, glory be to Thee!`,tones:[2]},{mate:`octoechos:tone2.matins.canon.odes.6.resurrection.troparia[1]`,mateHash:`m153ab500729b92`,score:.17,text:`Of old, through one man, the first Adam, death entered the world; and through one Man, the Son of God, Resurrection hath been revealed.`,tones:[2]}]},ocdce6fcceb:{mate:`menaion:11-16.c0.great_vespers.aposticha_closer`,mateHash:`m1395d578f6d6d3`,tone:6,score:.53,next:.22,evidence:[`wording 0.53 (next 0.22)`,`tone 6`,`place: vespers`,`same date`,`NAMES DIFFER: the OCA text names Maker; ours does not`],first:{doc:`2026-1018-texts-tt`,head:`Tone 6 (Theotokion)`},why:[`the OCA text names Maker; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`My Maker and Redeemer, [Christ] the Lord, | was born of thee, O most pure [Vir]gin. | By accepting my nature, He freed Adam from his [an]cient curse. | Unceasingly we magnify thee as the [Moth]er of God! | Rejoice, O ce[les]tial Joy! | Rejoice, O [La]dy: // the protection, intercession and sal[va]tion of our souls!`,prints:3,dates:[`2026-1018`,`2026-1113`,`2026-1116`],mateText:`Christ the Lord, my Creator and Redeemer, * Who came forth from thy womb, O all-pure one, * and clothed Himself in my nature, * hath freed Adam from the primal curse. * Wherefore, like the angel * we unceasingly cry out to thee, * O most pure one, * who art truly the Mother of God and Virgin: * Rejoice!, O Lady, ** the intercession, protection and salvation of our souls!`,mateTones:[6],sections:[`Aposticha`],others:[{mate:`octoechos:tone6.matins_weekday.fri.canons[1].odes.3.items[2]`,mateHash:`m025708b5253803`,score:.22,text:`The condemnation of the ancient curse hath been lifted by thy mediation, O Mother of God; for, having appeared to thee, O most pure one, the Lord hath poured forth all blessings in abundance upon all, in that He is supremely good.`,tones:[6]},{mate:`octoechos:tone6.matins_weekday.tue.canons[1].odes.6.items[3]`,mateHash:`m1b956411d0362f`,score:.19,text:`We now offer unto thee hymnody of thanksgiving, O Virgin; for saved from the ancient curse by thee, O pure one, we produce every blessing like fruit.`,tones:[6]},{mate:`octoechos:theotokia.doxasticon_theotokia.5.fri_eve_aposticha`,mateHash:`m1112a8d2de94d8`,score:.19,text:`To thee do we pray, as the Mother of God: * O blessed one, ** pray thou for the salvation of our souls!`,tones:[]}]},ocdd8c7faaf:{mate:`octoechos:tone4.little_vespers.aposticha.resurrection[0]`,mateHash:`m0b35da7dd04f8a`,tone:4,score:.39,next:.23,evidence:[`wording 0.39 (next 0.23)`,`tone 4`,`place: vespers`],first:{doc:`2026-0830-texts-tt-`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`],text:`By ascending the [Cross], O Lord, | Thou hast annulled our an[ces]tral curse. | By de[scend]ing to hell, Thou hast freed the eternal [pris]oners, | granting incorruption to the [hu]man race. // Therefore in songs we glorify Thy life-creating and saving Resur[rec]tion.`,prints:2,dates:[`2026-0830`,`2026-1025`],mateText:`O Lord, by ascending the Cross * Thou hast wiped out our ancestral curse, * and by descending into Hades * Thou hast set free those enchained therein from all ages, * granting incorruption to mankind; * wherefore with hymns we glorify ** Thy life-giving and saving arising.`,mateTones:[4],sections:[`Aposticha`],others:[{mate:`menaion:11-20.c0.matins.canons[0].odes.4.items[2]`,mateHash:`m168f7ad7a24bc5`,score:.23,text:`The sentence pronounced upon our ancestors hath been annulled; for, lo! a branch hath sprung forth which shall bear for us the incorrupt cluster Who shall bring the wine of gladness unto the ends of the earth.`,tones:[4]},{mate:`menaion:09-08.c0.troparion`,mateHash:`m02656e20914b82`,score:.21,text:`Thy nativity, O Virgin Theotokos, * hath proclaimed joy to all the world; * for from thee hath shone forth Christ our God, the Sun of righteousness, * Who, having annulled the curse, hath given His blessing, ** and having abolished death, hath granted us life everlasting.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.wed.canons[1].odes.1.items[2]`,mateHash:`m025d24c0fb884e`,score:.2,text:`As thou alone, in a manner transcending understanding, hast by thy birthgiving freed the race of mankind from the curse, O most pure one, by thy supplications free me who am enslaved by carnal passions.`,tones:[4]}]},od0c9d07e6a:{mate:`octoechos:tone3.vespers_weekday.fri.lic_theotokion`,mateHash:`m0e1971fa7939b1`,tone:3,score:.34,next:.17,evidence:[`wording 0.34 (next 0.17)`,`tone 3`,`place: vespers`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 (Theotokion – Dogmatikon)`},why:[`wording below the bar`],text:`How can we not [won]der | at thy mystical childbearing, O exalted [Moth]er? | For without receiving the [touch] of man, | thou gavest birth to a Son in the flesh, O immaculate [Vir]gin. | The Son born of the Father before e[ter]nity | was born of thee at the fullness of time, O honored [La]dy. | He underwent no mingling, no change, no di[vi]sion, | but preserved the fullness of each [na]ture. | Entreat Him, O Lady and Virgin and [Mo]ther, | to save the souls of those who, in the Orthodox manner, con[fess] thee // to be the [The]o[to]kos.`,prints:5,dates:[`2026-0823`,`2026-0829`,`2026-0924`,`2026-1018`,`2026-1024`],mateText:`How can we, O all-honored one, * not marvel at thine Offspring? * Who is both God and man. * For without knowing a man, O all-immaculate one, * without a father thou hast given birth to a Son in the flesh, * who without a mother was begotten from the Father before all ages, * yet in no way undergoing change, fusion or separation, * but preserving fully the characteristics of both natures. * Wherefore, O Lady, and Virgin Mother, * beseech Him to save the souls of those ** who with Orthodox faith confess thee to be the true Theotokos.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone3.nocturns.after_ode6.theotokion`,mateHash:`m026cfd643dea7b`,score:.17,text:`O supreme wonder! How did the infinite One come to be contained within thy womb, and become incarnate, and appear as a man, without enduring change or separation from the divine and immutable Divinity, O all-pure maiden? Wherefore with faith, we ever proclaim and glorify thee, the Theotokos.`,tones:[3]},{mate:`octoechos:tone3.nocturns.canon.odes.8.items[2]`,mateHash:`m0be6417839e5f2`,score:.17,text:`Perceiving thy birthgiving from afar, the sayings of the prophets praised it as being without seed, O Theotokos, and praised Him Who was born from thee in a manner transcending nature, O Lady. And with them, we also sing to Him as Lord and supremely exalt Him throughout all ages.`,tones:[3]},{mate:`octoechos:theotokia.doxasticon_theotokia.2.mon_eve_aposticha`,mateHash:`m1b08b76bf067ed`,score:.16,text:`O blessed Theotokos, * thou mystically sealed and impassible gate: * accept our entreaties, and bring them unto thy Son and God, ** that through thee He may save our souls.`,tones:[]}]},od3a1cc2f8f:{mate:`octoechos:tone2.liturgy.beatitudes.gloria`,mateHash:`m0dcc5b236edd36`,tone:2,score:.34,next:.28,evidence:[`wording 0.34 (next 0.28)`,`tone 2`,`PLACE DIFFERS: OCA prints it at matins, the mate is at liturgy`],first:{doc:`2026-1027-texts-alaska-tt`,head:`Tone 2 Ode 8 – Heirmos`},why:[`wording below the bar`,`a second hymn is close`],text:`We praise, bless and worship the Lord, singing and exalting Him throughout all ages.`,prints:2,dates:[`2026-1027`],mateText:`Let us all now glorify the Father, worship the Son and praise with faith the Holy Spirit.`,mateTones:[2],sections:[`Ikos`],others:[{mate:`octoechos:tone2.great_vespers.lic[6]`,mateHash:`m15c9d1447b4129`,score:.28,text:`Singing a hymn of salvation, * let this song rise from our lips; * “O Come all ye people into the house of the Lord,” * let us fall down in worship saying; * “O Thou who wast crucified upon the Tree, * and didst rise from the dead and abidest in the bosom of the Father, * have mercy upon us ** and cleanse us of our iniquities!”`,tones:[2]}]},od47a717c36:{mate:`menaion:11-16.c0.great_vespers.lic_glory`,mateHash:`m1dfea8f07979e0`,tone:4,score:.31,next:.22,evidence:[`wording 0.31 (next 0.22)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 Idiomelon`},why:[`wording below the bar`,`a second hymn is close`],text:`Thou wast called by Christ to heavenly dis[cip]leship, | and didst follow Him eagerly, O [chos]en of God, | for[sak]ing overnight all enslavement to the [cares] of this life. | Obediently didst thou accept wisdom worthy of the [King]dom on high, | and didst abandon the passing glory of thy former [life] [in] the world, | becoming an evangelist instead of a [pub]lican: | a light for those living in [dark]ness | and a guide to salvation for [those] [gone] astray. | Now, O Matthew, thou art a fervent inter[ces]sor for the world // and guardian of those who [hon]or thee.`,prints:1,dates:[`2026-1116`],mateText:`When Christ called thee to heavenly discipleship, thou didst diligently follow Him, O God-pleaser, casting aside without hesitation every exercise of earthly care; for, receiving with goodly submission an understanding worthy of the heavenly kingdom, thou didst put aside a base life and vain glory. And having been made an evangelist from that of a publican, thou wast revealed to be a light to those in darkness and a guide to salvation for the lost. And now thou art a most fervent intercessor for the whole world and the saving protector of those who honor thee, O Matthew.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-16.c0.matins.canons[0].odes.6.items[0]`,mateHash:`m024db436ebbe41`,score:.22,text:`By Thine omnipotent might, O Maker of all, the divinely eloquent and most excellent Matthew was transformed from a publican into an evangelist, in that he followed Thee.`,tones:[4]},{mate:`menaion:11-16.c0.great_vespers.lic[1]`,mateHash:`m1b20826b26d0b3`,score:.17,text:`When the beginningless Word * Called thee away from thy tax-booth * to be His disciple, * He cried out to thee, * commanding thee to follow Him * and promising thee a share in His kingdom; * then, O all-blessed one, forsaking all things * and abandoning the tumult of the crowd, * thou didst steadfastly follow after him. * And now, O God-seer, * thou art manifestly full of the ineffable vision of Him. * Him do thou beseech, ** that He save and enlighten our souls.`,tones:[4]},{mate:`menaion:11-16.c0.matins.megalynarion`,mateHash:`m158a8147ee1c05`,score:.16,text:`We magnify thee, O apostle of Christ and evangelist Matthew, and we honor thy pangs and labors, wherewith thou didst struggle in the proclamation of the Gospel of Christ.`,tones:[]}]},od5c3f7dcb7:{mate:`octoechos:tone4.great_vespers.lic[4]`,mateHash:`m0df0f56e892074`,tone:4,score:.36,next:.22,evidence:[`wording 0.36 (next 0.22)`,`tone 4`,`place: vespers`],first:{doc:`2026-1025-texts-tt`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`Angels and men sing of Thy Resurrection on the third day, O [Sav]ior. | By it, the ends of the earth have been il[lu]mined. | By [it] we have been delivered from bondage to the [En]emy. | Save us by Thy Resur[rec]tion! // O Life-creating and almighty Savior, [glo]ry to Thee!`,prints:1,dates:[`2026-1025`],mateText:`Angels and mortals hymn Thine arising on the third day, O Savior, * through which the ends of the inhabited world were filled with light, * and we were all redeemed from the slavery of the enemy, as we cry aloud: * “O life-giving, all- powerful Savior, ** save us by Thy Resurrection, O only Lover of mankind.”`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.matins_weekday.sat.aposticha_theotokion`,mateHash:`m050610eb061566`,score:.22,text:`Following, the words of the divinely eloquent prophets, O all- immaculate One, we believe thee to be the Theotokos. For thou didst ineffably give birth to God in the flesh, Who hath delivered us from the bondage of sin. Ever beseech Him, that He illumine thy departed servants with the radiance of His Light.`,tones:[4]},{mate:`octoechos:tone4.kontakion`,mateHash:`m167ee95ff7c8b4`,score:.22,text:`My Savior and Redeemer * from the grave, as God, * hath raised those born on earth from their chains, * and shattered the gates of Hades; ** and as Lord arisen on the third day.`,tones:[4]},{mate:`octoechos:tone4.great_vespers.lic[3]`,mateHash:`m045a54d65b6756`,score:.22,text:`Come O ye peoples, let us hymn the Savior’s rising on the third day, * whereby we were redeemed from the unbreakable bonds of Hades * obtaining incorruption and life, as we cry aloud: * “Thou, who wast crucified and buried and rose again, ** save us by Thy Resurrection, O only Lover of mankind.”`,tones:[4]}]},od806e3a8b4:{mate:`menaion:11-30.c0.vespers.litiya_closer`,mateHash:`m0619d1468f51c3`,tone:8,score:.31,next:.21,evidence:[`wording 0.31 (next 0.21)`,`tone 8`,`place: vespers`,`same date`],first:{doc:`2026-1130-texts-tt`,head:`Tone 8 (Theotokion)`},why:[`wording below the bar`,`a second hymn is close`],text:`O [La]dy, accept the prayers of thy [ser]vants, // and deliver us from all necessity and af[flic]tion!`,prints:1,dates:[`2026-1130`],mateText:`O Sovereign Lady, accept the supplication of thy servants, and deliver us from all want and grief.`,mateTones:[8],sections:[`Litya`],others:[{mate:`octoechos:tone8.nocturns.canon.odes.7.items[0]`,mateHash:`m0363baa87a4bad`,score:.21,text:`In Thine ineffable wisdom and the abyss of Thy goodness, show me Thy servant to be freely receiving mercy; and now, as of old, deliver me from affliction, sins and the passions, O God, Trinity and Unity.`,tones:[8]},{mate:`menaion:11-17.c0.vespers.lic[3]`,mateHash:`m01ec3fd55ce427`,score:.21,text:`What now shall I proclaim thee, O venerable one? * Guide of those who are astray * and physician of the ailing, * bestower of an abundance of necessities upon those who ask, * most mighty persecutor of demons, * one who urged the struggle of martyrdom, * and was prophetically illumined with graces, O right glorious one. ** Pray thou that our souls be saved.`,tones:[8]},{mate:`octoechos:tone8.compline.mon.canon.odes.6.items[0]`,mateHash:`m083b8fb445e2e7`,score:.2,text:`Look upon me with thy merciful eye, O Lady, and quickly deliver me from cruel infirmities, from every affliction and fall which now awaiteth me.`,tones:[8]}]},od8a951c5cb:{mate:`menaion:11-14.c0.vespers.litiya.stichera[1]`,mateHash:`m0a4c85d6821445`,tone:4,score:.31,next:.19,evidence:[`wording 0.31 (next 0.19)`,`tone 4`,`place: vespers`,`NAMES DIFFER: the OCA text names Luke; ours does not`],first:{doc:`2026-1018-texts-tt`,head:`Tone 4 (for St. Luke) (As one valiant among the martyrs)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Luke; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`In the form of fire the radiance of the Spirit de[scend]ed on thee, | making thee His chosen [ves]sel. | [Zeal]ously didst thou drive away the mist of [god]lessness | and didst enlighten the world with the mystery of faith by the [wis]dom of thy words, // O most honorable Apostle Luke, eye[wit]ness of Christ.`,prints:1,dates:[`2026-1018`],mateText:`The radiance of the Spirit * descended upon thee in the guise of fire, * and made of thee a divine dwelling, O blessed one, * who quickly drivest off the gloom of godlessness, * and enlightenest the world * with the splendor of thine all-wise words, * O proclaimer of the mysteries of God, * adornment of the apostles ** and beholder of Christ, O blessed one.`,mateTones:[4],sections:[`Litya`],others:[{mate:`menaion:11-16.c0.matins.canons[0].odes.3.items[0]`,mateHash:`m0d147e40f17deb`,score:.19,text:`O Word of God, thou hast shown forth Thine apostles as beacons of life which drive away the gloom of ungodliness, illumining the whole world with Thy divine glory, O Master.`,tones:[4]},{mate:`octoechos:tone4.vespers_weekday.wed.aposticha.items[0]`,mateHash:`m0d908273b47130`,score:.16,text:`Thou didst enlighten the choir of the apostles with the Holy Spirit, O Christ God. By them wash away the defilement of our sin, and have mercy on us.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.thu.aposticha.items[0]`,mateHash:`m03c45fbfc1fe99`,score:.15,text:`Thou didst enlighten the choir of the apostles with the Holy Spirit, O Christ God. For their sake, wash away the defilement of our sin, and have mercy on us.`,tones:[4]}]},od8b4400258:{mate:`octoechos:tone1.matins_weekday.wed.sessionals[1].items[0]`,mateHash:`m08eb568868f088`,tone:1,score:.67,next:.19,evidence:[`wording 0.67 (next 0.19)`,`tone 1`,`NAMES DIFFER: the OCA text names Orthodox, Christians; ours does not`],first:{doc:`2026-0914-texts-tt`,head:`Tone 1 Troparion`},why:[`the OCA text names Orthodox, Christians; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`O [Lord], save Thy [peo]ple, | and bless Thine in[her]itance! | [Grant] victories to the Orthodox [Chris]tians | over their [ad]versaries; | and by [vir]tue of Thy [Cross], // preserve Thy habi[ta]tion!`,prints:7,dates:[`2026-0914`,`2026-0920`],mateText:`Save O Lord, Thy people, and bless Thine inheritance, grant now unto the faithful victory over adversaries, and by Thy power of Thy Cross, do Thou preserve Thy commonwealth.`,mateTones:[1],sections:[`Aposticha`,`God is the Lord…" Tone 1`,`The Third Antiphon`,`Entrance Verse`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.4.wed_eve_aposticha`,mateHash:`m1d4b647ba585a3`,score:.19,text:`Having thee O Theotokos as our hope and intercession, * we fear not the assaults of the adversary, ** for thou dost save our souls.`,tones:[]},{mate:`octoechos:tone1.matins.canon.odes.9.resurrection.closer`,mateHash:`m0b5b9c117d8755`,score:.19,text:`Save Thy people, O Lord, whom Thou hast purchased with Thine own precious blood, strengthening all Orthodox Christians against enemies, and bestowing peace upon Thy Churches, O Lover of mankind, through the supplications of the Theotokos.`,tones:[1]},{mate:`menaion:11-27.c0.compline.sessional_ode6[0]`,mateHash:`m0ce546fd07514a`,score:.18,text:`Living the monastic life in God-pleasing manner, O our God-bearing father, thou didst search for God with prayer and fasting, and didst become a pure habitation of the Spirit, shedding rays of virtue upon the faithful, whereby thou dost illumine all who honor thee. Glory to Christ Who hath glorified thee! Glory to Him Who strengthened thee! Glory to Him Who performeth healing for all through thee!`,tones:[1]}]},odbb491ca31:{mate:`menaion:11-30.c0.vespers.litiya_closer`,mateHash:`m0619d1468f51c3`,tone:8,score:.46,next:.21,evidence:[`wording 0.46 (next 0.21)`,`tone 8`,`place: vespers`],first:{doc:`2026-1023-texts-tt`,head:`Tone 8 (Theotokion)`},why:[`wording below the bar`],text:`Ac[cept] the prayers of thy servants, O [La]dy // and deliver us from all grief and ne[ces]sity!`,prints:1,dates:[`2026-1023`],mateText:`O Sovereign Lady, accept the supplication of thy servants, and deliver us from all want and grief.`,mateTones:[8],sections:[`Aposticha`],others:[{mate:`menaion:11-17.c0.vespers.lic[3]`,mateHash:`m01ec3fd55ce427`,score:.21,text:`What now shall I proclaim thee, O venerable one? * Guide of those who are astray * and physician of the ailing, * bestower of an abundance of necessities upon those who ask, * most mighty persecutor of demons, * one who urged the struggle of martyrdom, * and was prophetically illumined with graces, O right glorious one. ** Pray thou that our souls be saved.`,tones:[8]}]},odd997ddd12:{mate:`menaion:11-16.c0.great_vespers.lic[1]`,mateHash:`m1b20826b26d0b3`,tone:4,score:.34,next:.17,evidence:[`wording 0.34 (next 0.17)`,`tone 4`,`place: vespers`,`melody “Called from on high ...”`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 (Called from on high)`},why:[`wording below the bar`],text:`Once a publican, now a dis[ci]ple, | thou didst accept the urgent call of the E[ter]nal Word, | and didst a[ban]don the collection of the [tax]es, | eager for the promise of communion in His [King]dom; | thou didst cast away the raging [tu]mult [of] this life, | and now thou dost behold His glory [face] to face; // pray that He may save and en[light]en our souls!`,prints:1,dates:[`2026-1116`],mateText:`When the beginningless Word * Called thee away from thy tax-booth * to be His disciple, * He cried out to thee, * commanding thee to follow Him * and promising thee a share in His kingdom; * then, O all-blessed one, forsaking all things * and abandoning the tumult of the crowd, * thou didst steadfastly follow after him. * And now, O God-seer, * thou art manifestly full of the ineffable vision of Him. * Him do thou beseech, ** that He save and enlighten our souls.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-16.c0.matins.exapostilarion_glory`,mateHash:`m04f798a5746b71`,score:.17,text:`Having wisely cast off the yoke of thy publican's office, thou didst follow Christ, O divinely wise Matthew; and following wondrously in His steps, thou didst obtain a share of His kingdom and glory through communion with Him, being an initiate of ineffable mysteries.`,tones:[]},{mate:`menaion:11-16.c0.matins.canons[0].odes.1.items[1]`,mateHash:`m1533158108df9b`,score:.16,text:`Thou didst utterly abandon the tumult of earthly things; for, having hearkened to the voice of the incarnate Word, thou wast revealed to be a steward and God-pleasing herald of His grace.`,tones:[4]},{mate:`menaion:11-16.c0.great_vespers.lic_glory`,mateHash:`m1dfea8f07979e0`,score:.12,text:`When Christ called thee to heavenly discipleship, thou didst diligently follow Him, O God-pleaser, casting aside without hesitation every exercise of earthly care; for, receiving with goodly submission an understanding worthy of the heavenly kingdom, thou didst put aside a base life and vain glory. And having been made an evangelist from that of a publican, thou wast revealed to be a light to those in darkness and a guide to salvation for the lost. And now thou art a most fervent intercessor for the whole world and the saving protector of those who honor thee, O Matthew.`,tones:[4]}]},odf2b3cacae:{mate:`octoechos:tone3.vespers_weekday.fri.aposticha.items[1]`,mateHash:`m1f49d7d882b6da`,tone:3,score:.42,next:.21,evidence:[`wording 0.42 (next 0.21)`,`tone 3`,`place: vespers`],first:{doc:`2026-1024-texts-tt`,head:`Tone 3 (for the Departed, by St. John of Damascus)`},why:[`wording below the bar`],text:`No human vanity shall re[main] after death. | Riches do not endure; glory does not [jour]ney with us. | When death comes, it shall [swal]low these. | Therefore let us sing to Christ, the im[mor]tal King: | “Give rest to those who have de[part]ed from us, // in the dwelling of all [those] who re[joice] in Thee!”`,prints:1,dates:[`2026-1024`],mateText:`All things human, which endure not after death, are vain. Our wealth will not remain, our glory will not go with us upon the way: for when death cometh, all these things will fade away. Wherefore let us cry out to Christ the immortal King: Grant rest to our departed brethren, where all who rejoice have their abode with Thee.`,mateTones:[3],sections:[`Aposticha`],others:[{mate:`octoechos:tone3.matins.canon.odes.4.cross_resurrection.troparia[1]`,mateHash:`m164b603014ddba`,score:.21,text:`Death hath given up the dead whom it had swallowed, while the dominion of Hades, which brought forth corruption, was destroyed when Thou didst arise from the tomb, O Lord.`,tones:[3]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.wed_eve_aposticha`,mateHash:`m1d9269c0de1dfc`,score:.19,text:`Thee, the most pure Virgin, who remained so even after giving birth, do we hymn as the Mother of God the Word, saying: Glory to thee!`,tones:[]},{mate:`octoechos:theotokia.doxasticon_theotokia.7.tue_praises`,mateHash:`m0aaab6fb2d0346`,score:.15,text:`O Christ, Thou Light, * Thou didst spring forth from the Virgin, * and hast illumined the human race. ** O Lord, glory be to Thee!`,tones:[]}]},oe1115c5406:{mate:`octoechos:tone1.great_vespers.lic[4]`,mateHash:`m0f222ec9c9bac5`,tone:1,score:.46,next:.23,evidence:[`wording 0.46 (next 0.23)`,`tone 1`,`place: vespers`],first:{doc:`2026-1004-texts-tt`,head:`Tone 1 (for the Resurrection)`},why:[`wording below the bar`],text:`[Let] us [praise] Him | Who voluntarily was crucified in the [flesh] for our sake. | He [suf]fered, was buried, but [rose] from the dead. | By Orthodoxy con[firm] Thy [Church], O Christ. // Grant peace for our life as the gracious [Lov]er of man.`,prints:2,dates:[`2026-1004`,`2026-1129`],mateText:`Let us sing the praise of him * who was willingly crucified in the flesh for our sakes, * suffered and was buried, and arose from the dead, * as we cry: * “Establish Thy Church in Orthodox belief, O Christ, * and grant peace unto our lives, ** as Thou alone art good and the Lover of mankind.”`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone1.matins.canon.odes.5.cross_resurrection.troparia[1]`,mateHash:`m0138d52be39b4e`,score:.23,text:`Being God, Christ united Himself to flesh for our sake, and hath been crucified, and died, and hath been buried, and arisen again, ascending up to the Father with His own flesh, with which He will come again to save those who devoutly serve Him.`,tones:[1]},{mate:`octoechos:tone1.matins.canon.odes.9.resurrection.closer`,mateHash:`m0b5b9c117d8755`,score:.2,text:`Save Thy people, O Lord, whom Thou hast purchased with Thine own precious blood, strengthening all Orthodox Christians against enemies, and bestowing peace upon Thy Churches, O Lover of mankind, through the supplications of the Theotokos.`,tones:[1]},{mate:`octoechos:tone1.matins.canon.odes.9.theotokos.troparia[1]`,mateHash:`m1eef8c1cab3e43`,score:.19,text:`O most pure one, every law of praise is defeated by the majesty of thy glory; yet, O Lady, graciously accept from us Thine unworthy suppliants, O Theotokos, the praise we offer thee with love.`,tones:[1]}]},oe28752de42:{mate:`octoechos:tone2.compline.sat.canon.odes.8.items[3]`,mateHash:`m0fdc9409cec6d0`,tone:null,score:.35,next:.35,evidence:[`wording 0.35 (next 0.35)`,`tone not printed on one side`,`place: matins`],first:{doc:`2026-0908-texts-tt`,head:`The Praises Tone 1`},why:[`wording below the bar`,`a second hymn is close`],text:`Let [ev]erything that breathes [praise] the Lord! | Praise the Lord from the [heav]ens! | [Praise] Him in the [high]est! // To Thee, O God, is [due] a song!`,prints:4,dates:[`2026-0908`,`2026-1027`,`2026-1121`],mateText:`That thy name might be glorified on the earth, O Theotokos, He Who shone forth from thee hath given thee to sinners as a mighty hope and rampart; for through thee doth everything that hath breath hasten to God.`,mateTones:[2],sections:[`The Praises Tone 1`],others:[{mate:`octoechos:tone6.matins.anabathmoi[2].gloria`,mateHash:`m1dfce8a7a772e9`,score:.35,text:`In the Holy Spirit is sovereignty over all creation; * Him the armies of hosts above worship * and by everything that hath breath below ** is He worshiped.`,tones:[6]},{mate:`octoechos:tone2.matins.praises.stichera[0]`,mateHash:`m040a251f1a42ee`,score:.34,text:`Everything that hath breath and every creature doth glorify Thee, O Lord, * for through Thy Cross Thou hast destroyed death * and thus shown the multitude of peoples Thy Resurrection from the dead, ** as Thou alone lovest mankind.`,tones:[2]},{mate:`octoechos:tone7.compline.sun.canon.odes.1.items[3]`,mateHash:`m0e17520dbdc512`,score:.27,text:`Ever effective words of praise are due thee, O Theotokos; yet we entreat thee, O pure one: From all the sorrows of life save those who have recourse unto thee.`,tones:[7]}]},oe3943d765a:{mate:`octoechos:tone3.great_vespers.aposticha[2]`,mateHash:`m0437d33b50bb33`,tone:3,score:.38,next:.25,evidence:[`wording 0.38 (next 0.25)`,`tone 3`,`place: vespers`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 (for the Resurrection)`},why:[`wording below the bar`,`a second hymn is close`],text:`Thou art the [change]less God, | Who, suffering in the [flesh], wast changed. | Creation could not endure seeing [Thee] on the Cross. | It was filled with fear while praising Thy [pa]tience. | By descending to hell and rising on the [third] day, // Thou hast granted to the world [life] and great [mer]cy.`,prints:2,dates:[`2026-0823`,`2026-1018`],mateText:`Howbeit, as God Thou art unchangeable, * yet by Thy suffering Thou hast undergone change in the flesh, * and creation, unable to bear seeing Thee hanging upon a Cross, * was shaken with fear, * groaning as it sang the praise of Thy long- suffering; * and having descended into Hades, Thou didst arise on the third day, ** granting to the world life and great mercy.`,mateTones:[3],sections:[`Aposticha`],others:[{mate:`octoechos:tone3.great_vespers.lic[4]`,mateHash:`m1a4938959f783f`,score:.25,text:`We praise the Savior who took flesh from the Virgin; * for he was crucified for us and arose on the third day, ** granting unto us His great mercy.`,tones:[3]},{mate:`octoechos:tone3.matins_weekday.tue.canons[0].odes.5.irmos`,mateHash:`m0a53bad62508a5`,score:.17,text:`Rising at dawn, we hymn Thee, O Word, * Thou only-begotten Son of God. * Grant us Thy peace, and have mercy on us * who with faith hymn and worship Thee.`,tones:[3]},{mate:`octoechos:tone3.nocturns.gregory_rubric.stanzas[0]`,mateHash:`m1d8a8b90b4a78c`,score:.16,text:`It is truly meet to glorify Thee, the Word of God, before Whom the cherubim tremble and quake, and Whom the hosts of heaven glorify. And with fear we glorify Christ, the Bestower of life, Who rose from the tomb on the third day.`,tones:[1,3,4,5,6,7,8]}]},oe561b74e4b:{mate:`octoechos:tone2.vespers_weekday.sun.aposticha_theotokion`,mateHash:`m059438c8343139`,tone:2,score:.46,next:.27,evidence:[`wording 0.46 (next 0.27)`,`tone 2`,`place: vespers`],first:{doc:`2026-1207-texts-tt`,head:`Tone 2 (Theotokion)`},why:[`wording below the bar`],text:`Rejoice, O Mary Theo[to]kos, | Temple which can[not] be destroyed; | Holy [Tem]ple, indeed, as the [Proph]et cries: // “Holy is Thy Temple, wonderful in [right]eousness!”`,prints:1,dates:[`2026-1207`],mateText:`Rejoice, O Theotokos Mary, * thou indestructible and surpassingly holy temple; * as the prophet crieth out: ** Holy is thy temple, wondrous in righteousness!`,mateTones:[2],sections:[`Aposticha`],others:[{mate:`menaion:11-17.c0.matins.exapostilarion_closer`,mateHash:`m1cd48d6b4ea966`,score:.27,text:`Rejoice, thou boast of the faithful, confirmation of the venerable! Rejoice, glory of the righteous! Rejoice, thou light of those who are in darkness! Rejoice, most holy temple! Rejoice, paradise of God! Rejoice, loosing of the curse, O blessed Mary!`,tones:[]},{mate:`octoechos:theotokia.dismissal_theotokia_annual.1.sun_vespers_mon_matins`,mateHash:`m1cc25a82608e68`,score:.23,text:`Beholding within thee O full of grace, * the wonder of wonders, * creation doth rejoice; * for thou didst conceive without seed and ineffably give birth unto Him * Whom the ranks of angels cannot see. ** Him do thou entreat on behalf of our souls!`,tones:[]},{mate:`menaion:11-21.c0.little_vespers.aposticha[3]`,mateHash:`m16a6df6503b31f`,score:.21,text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tones:[1,2,5,6]}]},oe567602634:{mate:`menaion:09-08.c0.great_vespers.litiya[2]`,mateHash:`m05cab99c84428c`,tone:2,score:.47,next:.28,evidence:[`wording 0.47 (next 0.28)`,`tone 2`,`place: vespers`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 (by Anatolius)`},why:[`wording below the bar`],text:`What is this sound of [feast]ing we hear? | Joachim and Anna mystically celebrate, [say]ing: | “Re[joice] with us today, O [Ad]am and Eve; | for if by your transgression you closed the gate of Paradise to [those] of old, | we have now been given a [glo]rious fruit, // Mary the child of God, who opens its [en]trance to all!”`,prints:1,dates:[`2026-0908`],mateText:`What is this noise of revelers? Joachim and Anna keep festival mystically, saying: “Rejoice with us today, O Adam and Eve!” For by their transgression paradise was shut, but a right glorious fruit hath now been granted unto us: Mary, the divine maiden, the fruit which openeth wide its gates unto all.`,mateTones:[2],sections:[`Litya`],others:[{mate:`menaion:09-08.c0.matins.exapostilarion_closer`,mateHash:`m18509298ffbb80`,score:.28,text:`Be thou renewed, O Adam! Be thou magnified, O Eve! Join ye chorus with the apostles and the righteous! For Mary the Theotokos, the common joy of the angels and mortals, hath shone forth today from the righteous Joachim and Anna.`,tones:[]},{mate:`menaion:09-07.c0.matins.exapostilarion_closer`,mateHash:`m0301afa8291593`,score:.28,text:`Be renewed, O Adam, and be thou magnified, O Eve! Ye prophets, join chorus with the apostles and the righteous! For the common joy of angels and mortals hath shone forth today from the righteous Joachim and Anna: Mary the Theotokos.`,tones:[]},{mate:`menaion:09-08.c0.matins.canons[0].odes.3.items[2]`,mateHash:`m15312e7a874885`,score:.21,text:`Let us hymn Mary today as the Theotokos, the fruit of Anna, the intercessor and helper of all, who gaveth birth to the life-bearing Cluster.`,tones:[2]}]},oe71fd1379c:{mate:`octoechos:tone8.compline.tue.after_ode6.sessional`,mateHash:`m1a3c4e18012eea`,tone:8,score:.45,next:.32,evidence:[`wording 0.45 (next 0.32)`,`tone 8`,`place: matins`],first:{doc:`2026-1204-texts-tt`,head:`Tone 8 Cross-Theotokion`},why:[`wording below the bar`,`a second hymn is close`],text:`O Lamb, and [She]pherd, and [Sav]ior [of] the world, | when Thy Mother [saw] Thee [hang]ing on the [Cross], she cried: | “Though the world re[joi]ces [in] its re[dem]ption, | my being [burns] as I be[hold] Thy cruci[fix]ion, // which Thou en[dur]est for [all] men, O my [Son] and my God.”`,prints:1,dates:[`2026-1204`],mateText:`Beholding Thee, the Lamb and Shepherd, * the Savior of the world, upon the Cross, * she that gaveth birth to Thee said, weeping: * The world rejoiceth, having received deliverance; * but my womb doth burn, beholding Thy crucifixion, ** which Thou dost endure on behalf of all, O my Son and God!`,mateTones:[8],sections:[`at Vespers`],others:[{mate:`octoechos:tone8.matins_weekday.wed.sessionals[0].closer`,mateHash:`m1737a546e735a9`,score:.32,text:`Beholding the Lamb, Shepherd and Redeemer unjustly lifted up upon the Cross, the Ewe- lamb cried out, bitterly weeping: “The world rejoiceth, receiving deliverance through Thee; but my womb doth burn as I behold the crucifixion Thou dost endure in the tender compassion of Thy mercy, O supremely good God, O sinless Lord!” Wherefore, we cry out to her with faith: Show thou compassion to us, O Virgin, and grant remission offenses unto those who worship His sufferings.`,tones:[8]},{mate:`menaion:11-15.c0.matins.sessional_ode3[3]`,mateHash:`m0112e509dddfd6`,score:.3,text:`Upon beholding the Lamb, Shepherd and Redeemer * upon the Cross, * the ewe-lamb exclaimed weeping, bitterly lamenting, and crying aloud: * “The world rejoiceth, having received deliverance through Thee, * but my womb doth burn, beholding Thy crucifixion, * which Thou hast endured in Thy merciful loving-kindness. * O long-suffering Lord, * Thou abyss and inexhaustible well-spring of mercy, * take pity, and grant forgiveness of sins ** unto those who hymn Thy divine sufferings with faith!”`,tones:[8]},{mate:`octoechos:tone8.matins_weekday.fri.sessionals[2].closer`,mateHash:`m1020f8e9c58698`,score:.2,text:`Upon beholding the Lamb and Shepherd suspended upon the Cross, the unblemished ewe-lamb, cried aloud: “O my Child, what is this strange and unexpected sight? How can the Life of all be condemned to death like mortals? But rise Thou from the dead on the third day, O Word, as Thou didst say, that, rejoicing, I may glorify Thee!”`,tones:[8]}]},oe814aadad5:{mate:`octoechos:tone1.matins_weekday.mon.canons[1].odes.8.items[4]`,mateHash:`m19a196ac93c3f6`,tone:null,score:.32,next:.21,evidence:[`wording 0.32 (next 0.21)`,`tone not printed on one side`],first:{doc:`2026-0914-texts-tt`,head:`The Second Antiphon`},why:[`wording below the bar`,`a second hymn is close`],text:`Refrain: O Son of God, crucified in the flesh, save us who sing to Thee: Alleluia!`,prints:1,dates:[`2026-0914`],mateText:`refrain: “More honorable than the cherubim ...,” and make prostrations.`,mateTones:[1,2,3,4,5,6,7,8],sections:[`The Second Antiphon`],others:[{mate:`octoechos:tone6.matins_weekday.tue.sessionals[1].items[1]`,mateHash:`m0ade591bf5e0c6`,score:.21,text:`Grant unto me the vigilance of the wise virgins, O Lord, and enlighten the lamp of my soul with the oil of Thy compassions, that I may chant unto Thee the angelic hymn: Alleluia!`,tones:[6]},{mate:`octoechos:tone7.matins_weekday.fri.canons[0].odes.6.items[2]`,mateHash:`m0d831a27e1760a`,score:.21,text:`We hymn Thee Who wast crucified in the flesh; we glorify Thee Who wast crowned with thorns and hast crowned us with glory, O supremely good King.`,tones:[7]},{mate:`octoechos:tone6.vespers_weekday.tue.aposticha.items[1]`,mateHash:`m05378357c525da`,score:.21,text:`Thy Cross, O Lord, hath opened paradise to the race of mankind; and delivered from corruption, we hymn Thee, our God Who wast crucified in the flesh. Have mercy on us!`,tones:[6]}]},oe90074d6d8:{mate:`menaion:11-29.c0.matins.canons[0].odes.9.items[4]`,mateHash:`m1ff56827469a06`,tone:4,score:.32,next:.2,evidence:[`wording 0.32 (next 0.2)`,`tone 4`,`NAMES DIFFER: the OCA text names Zachariah; ours does not`],first:{doc:`2026-0923-texts-tt`,head:`Tone 4 Troparion (Forerunner)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Zachariah; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`Rejoice, O barren one, who formerly did not [bear] a child, | for thou hast conceived the Lamp of the Sun, Who is to illumine the whole universe darkened by [blind]ness! | Rejoice, O Zacha[ri]ah, | and cry out with [bold]ness: // “The Prophet of the Most High de[sires] to be born!”`,prints:2,dates:[`2026-0923`],mateText:`Enlighten the eyes of my soul which have been darkened by the blindness of corrupting sin, O most pure Lady, Birthgiver of God; for thou art the help and enlightenment of the faithful, O pure one.`,mateTones:[4],sections:[`at Vespers`,`at the Divine Liturgy`],others:[{mate:`menaion:11-21.c0.matins.praises[0]`,mateHash:`m0275a10494ebd0`,score:.2,text:`Virgins bearing lamps, * escorting the Ever-virgin with splendor, * truly prophesy the future in the Spirit; * for the Theotokos, as the temple of God, * is led as a child with virginal glory ** into the temple.`,tones:[4,1]},{mate:`octoechos:theotokia.doxasticon_theotokia.3.tue_praises`,mateHash:`m05fce683321875`,score:.19,text:`Without seed didst thou conceive by the Holy Spirit; * and glorifying thee, we hymn thee: ** Rejoice, most holy Virgin!`,tones:[]},{mate:`menaion:09-05.c0.vespers.lic[1]`,mateHash:`m1b73f9f7638e24`,score:.17,text:`O divinely inspired Zacharias, * thou didst behold born of a maiden * a Babe Who is co-beginningless with the Father; * and unto thine own child thou dost prophecy manifestly beforehand: * “A prophet shalt thou truly be, * preparing His ways!” * With him we call thee blessed * and in a sacred manner we celebrate thine honored festival, ** O most noetically rich God-bearer.`,tones:[4]}]},oe9e0c5b639:{mate:`octoechos:tone3.kontakion`,mateHash:`m17a5a97e2288f5`,tone:3,score:.45,next:.22,evidence:[`wording 0.45 (next 0.22)`,`tone 3`],first:{doc:`2026-0823-texts-tt`,head:`Tone 3 Kontakion (Resurrection)`},why:[`wording below the bar`],text:`On this day Thou didst rise from the tomb, O [Mer]ciful One, | leading us from the [gates] of death. | On this day Adam exults as Eve re[joic]es; | with the Prophets and [Pa]triarchs // they unceasingly praise the divine [ma]jesty of Thy [pow]er.`,prints:2,dates:[`2026-0823`,`2026-1018`],mateText:`Thou didst arise today, O merciful One, * and hast led us out from the gates of death. * Adam danceth today, and Eve rejoiceth. * The prophets also, along with patriarchs, ** ceaselessly praise the divine might of Thine authority.`,mateTones:[3],sections:[`at the Divine Liturgy`],others:[{mate:`octoechos:tone3.matins.canon.odes.8.resurrection.troparia[1]`,mateHash:`m15ad4877dd8aca`,score:.22,text:`Thou didst rise from the tomb, O Christ, and by Thy divine power, the Tree hath restored him who had fallen through temptation as he cried aloud, “All ye works of the Lord, bless ye the Lord, and supremely exalt Him throughout all ages.”`,tones:[3]},{mate:`octoechos:tone3.matins.praises.theotokion`,mateHash:`m1dbd3589642370`,score:.16,text:`Thou art most blessed, O Virgin Theotokos, * for through Him who took flesh from thee, Hades hath been captured, * Adam recalled, the curse slain, Eve set free, * death put to death, and we have been given life. * Therefore in praise we cry: ** Blessed art Thou, O Christ our God, who hast been thus well-pleased, glory be to Thee.`,tones:[3,5,7]},{mate:`octoechos:tone3.matins_weekday.sat.aposticha.items[3]`,mateHash:`m1d8f5d862cedc9`,score:.16,text:`When Thou didst rest in the tomb as a man, as God Thou didst raise up with invincible power, those who were sleeping in the graves, and who offer Thee unceasing hymnody. Wherefore, we beseech Thee, O Christ God: Unto those who have been taken from among us grant rest where all who rejoice have their abode with Thee.`,tones:[3]}]},oebcef24e1b:{mate:`octoechos:tone3.vespers_weekday.fri.lic.octoechos[0]`,mateHash:`m1db38bb55617f2`,tone:3,score:.41,next:.14,evidence:[`wording 0.41 (next 0.14)`,`tone 3`,`place: vespers`],first:{doc:`2026-1024-texts-tt`,head:`Tone 3 (for the Martyrs, in the Tone of the week)`},why:[`wording below the bar`],text:`Contending strongly and with [cour]age, | the valiant martyrs endured both wounds and the pain of fetters, as well as [ex]ile. | By their sufferings [they] attained // the inheritance that is truly [blessed] and free of [suf]fering.`,prints:1,dates:[`2026-1024`],mateText:`Having endured wounds, fetters and divers tortures, suffering mightily, the valiant martyrs were brought to their divine inheritance which is truly devoid of pain, the heritage of their pangs.`,mateTones:[3],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone3.matins_weekday.sat.canons[1].odes.1.items[1]`,mateHash:`m05dc5165b23b42`,score:.14,text:`O Savior, Who hast strengthened the divine martyrs and by them annulled the power of delusion: By their supplications be Thou well-pleased to grant those who have reposed in Thee, immortality and a goodly inheritance.`,tones:[3]},{mate:`octoechos:tone3.liturgy_weekday.tue.beatitudes.items[3]`,mateHash:`m1983b52ff7c7a7`,score:.13,text:`Fighting the good tight, O valiant spiritual athletes, ye endured countless myriads of pangs; and thus ye ever ease the pain of all and dispel the harm wrought by the evil spirits. Wherefore, we glorify you with faith, O holy ones.`,tones:[3]},{mate:`octoechos:tone3.liturgy_weekday.wed.beatitudes.items[3]`,mateHash:`m0574d177b56804`,score:.13,text:`O valiant spiritual athletes, all-glorious martyrs, who emulated the sufferings of Christ and with divine power cast down the deception of the enemy: Ye have received heavenly glory, O saints, praying for us all.`,tones:[3]}]},oebeeb508b0:{mate:`menaion:11-21.c0.great_vespers.aposticha[2]`,mateHash:`m03d6882a4e7649`,tone:5,score:.49,next:.24,evidence:[`wording 0.49 (next 0.24)`,`tone 5`,`place: vespers`,`same date`],first:{doc:`2026-1121-texts-tt`,head:`Tone 5 (Rejoice, O Life-giving Cross)`},why:[`wording below the bar`],text:`[An]na, the [name]sake of grace, | joyfully brings into the [Tem]ple of God | the [pure] and ever-Virgin who is [full] of grace, | and [calls] young girls to go before her with [lamps] in hand. | She says: “Go, child, to Him Who [gave] thee to me; | to be an [of]fering and a sweet-smelling [in]cense. | [Go] into the inner sanctuary that none may [en]ter: | learn its [mys]teries, | and pre[pare] thyself to become the pleasing and fair dwelling-place of [Je]sus, // Who grants the [world] His great [mer]cy!”`,prints:2,dates:[`2026-1121`,`2026-1125`],mateText:`O divinely manifest grace! With gladness Anna leadeth into the temple of God the pure Ever-virgin given her by grace, and she calleth maidens to go before her, bearing lamps and saying: “Go forth, my child! Be thou an offering and incense of sweet savor unto Him Who gave thee to us! Enter into the impassable precincts and learn the mysteries! And prepare thyself to be the gladsome and comely dwelling-place of Jesus, Who bestoweth upon the world great mercy!”`,mateTones:[5],sections:[`Aposticha`],others:[{mate:`menaion:11-21.c0.matins.psalm50_glory`,mateHash:`m092b29726ce7c1`,score:.24,text:`Today the animate temple of the great King entereth the temple to prepare herself as a divine dwelling-place for Him.`,tones:[]},{mate:`octoechos:tone5.matins.canon.odes.1.theotokos.troparia[1]`,mateHash:`m0f65ee5ff0343b`,score:.15,text:`O thou who art Full of grace, and art made fair by the beauty of the virtues, thou hast received by the overshadowing of the Spirit the comeliness that bestoweth beauty, O most pure one, and which maketh the universe radiant.`,tones:[5]},{mate:`octoechos:theotokia.doxasticon_theotokia.1.sat_praises`,mateHash:`m1a5479ee61d477`,score:.13,text:`Rejoice, O holy Virgin Theotokos * who art one of us, * thou pure vessel of all the ecumene, * inextinguishable lamp, * dwelling-place of the Boundless One, * indestructible temple! * Rejoice, thou from whom the Lamb of God was born, ** who taketh away the sins of all the world.`,tones:[]}]},oecc24f1236:{mate:`octoechos:tone6.little_vespers.aposticha.resurrection[0]`,mateHash:`m00d2978802195a`,tone:6,score:.48,next:.16,evidence:[`wording 0.48 (next 0.16)`,`tone 6`,`place: vespers`],first:{doc:`2026-0913-texts-tt`,head:`Tone 6 (for the Resurrection)`},why:[`wording below the bar`],text:`Thy Resurrection, O Christ our [Sav]ior, | the Angels in [heav]en sing! | Enable [us] on earth // to glorify Thee in [pur]ity of heart!`,prints:2,dates:[`2026-0913`,`2026-1108`],mateText:`Thy Resurrection O Christ our Savior, * The angels in the heavens hymn; * grant also unto us who are here on earth ** to glorify Thee with pure hearts.`,mateTones:[6],sections:[`Aposticha`],others:[{mate:`octoechos:tone6.matins_weekday.sat.praises.items[1]`,mateHash:`m07e4633953112b`,score:.16,text:`O Lord, if we had not had Thy saints as intercessors, and Thy goodness being merciful to us, how should we have dared, O Savior, to hymn Thee, Whom angels do unceasingly glorify? O Thou that knowest the hearts of men, spare our souls.`,tones:[6]},{mate:`octoechos:tone6.matins.praises.stichera[4]`,mateHash:`m0b5f6d09872f16`,score:.15,text:`O Lord, great and fearful is the mystery of Thy Resurrection; * for Thou camest forth from the tomb * like unto a bridegroom from His marriage chamber, * overcoming death by death, * and redeeming Adam. * Wherefore angels exult in heaven * and mankind here on earth ** doth glorify Thy compassion towards us, O Lover of mankind.`,tones:[6]},{mate:`menaion:11-28.c0.matins.canons[0].odes.1.items[4]`,mateHash:`m135f74da9884f3`,score:.15,text:`With sacred voices let us glorify the holy Lady, O sacred people: the impassable portal, the pure temple of purity, her who is most comely among women.`,tones:[6]}]},oecd5fc59de:{mate:`menaion:11-20.c0.matins.canons[2].odes.4.items[0]`,mateHash:`m1e9987b6e410d9`,tone:1,score:.32,next:.22,evidence:[`wording 0.32 (next 0.22)`,`tone 1`,`PLACE DIFFERS: OCA prints it at vespers, the mate is at matins`,`NAMES DIFFER: our text names Proclus; the OCA text does not`],first:{doc:`2026-0926-texts-tt`,head:`Tone 1 (Joy of the Heavenly Hosts)`},why:[`wording below the bar`,`a second hymn is close`,`our text names Proclus; the OCA text does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`],text:`With thy [tongue] resounding as [thun]der, | thou dost declare the hidden Word of the [Wis]dom of God. | O be[lov]ed of God, thou dost open thy [mouth] to cry: | “In the be[gin]ning [was] the Word!” // Thus thou dost illumine all mankind with the [know]ledge of God.`,prints:1,dates:[`2026-0926`],mateText:`The resounding thunder of the words of thy proclamation and the teachings of thy doctrines gladden the Church of God with wisdom, dispelling the audacity of heresy, O all-glorious and sacred Proclus.`,mateTones:[1],sections:[`Lord I Call...`],others:[{mate:`octoechos:theotokia.dismissal_theotokia_annual.8.wed_lauds`,mateHash:`m1c18965a141903`,score:.22,text:`The Fruit of thy womb, O Bride of God, * hath been revealed to mankind as the fulfillment of salvation; * wherefore O Theotokos, in knowledge and with tongue, ** we the faithful glorify thee.`,tones:[]},{mate:`menaion:11-14.c0.vespers.aposticha[0]`,mateHash:`m1f8c880018cdc7`,score:.16,text:`The proclamations of thy divine pronouncements * have resounded throughout the earth, O all-blessed one, * and have filled it with dogmas; * theologizing therewith, * we mystically glorify the Son, ** Who is of one essence with the Father and the Spirit, O apostle.`,tones:[1]},{mate:`menaion:11-14.c0.vespers.aposticha[3]`,mateHash:`m04f18e50cabdf5`,score:.15,text:`The heavens declare the glory of God, * and the firmament proclaimeth the work of His hands.`,tones:[1,4,5]}]},of2e30c635b:{mate:`menaion:11-30.c0.vespers.aposticha[2]`,mateHash:`m0a0a8729ee9883`,tone:5,score:.39,next:.17,evidence:[`wording 0.39 (next 0.17)`,`tone 5`,`place: vespers`,`same date`],first:{doc:`2026-1130-texts-tt`,head:`Tone 5 (Rejoice, O Life-giving Cross)`},why:[`wording below the bar`],text:`Having [found] the [First] of things desired, | Who in compassion was clothed with our [na]ture, | O [An]drew, [wise] in God, | thou wast u[nit]ed in ardent desire with thy [broth]er, | crying out, “Come, let us [find] Him | Whom the [Proph]ets preached in the [Spir]it!” | Let us en[chant] both soul and mind with His [beau]ties, | that, being illumined by His [bright]ness, | we may [ban]ish the night of delusion and the darkness of [ig]norance, // as we bless Christ, Who bestows on the [world] great [mer]cy!`,prints:1,dates:[`2026-1130`],mateText:`The first discoverer of the virtues of Him that, in His tender compassion, was clad in our nature, O divinely wise Andrew, thou didst join thyself to Him with ardent love, crying out to thy blood kinsman: We have found Him Whom the prophets proclaimed in the Spirit! Come thou to His comeliness, that we may be rescued in soul and in thought, and that, led by the light of His radiance, we may drive away the night of delusion and the darkness of unbelief, blessing Christ, Who bestoweth great mercy upon the world.`,mateTones:[5],sections:[`Aposticha`],others:[{mate:`octoechos:tone5.matins_weekday.thu.canons[1].odes.1.items[0]`,mateHash:`m1d1b621d7a8f1f`,score:.17,text:`Uniting thyself unto God by faith and love, O father, thou didst fulfill His all- holy desires, and thereby didst become holy in all things, O wise and holy hierarch Nicholas.`,tones:[5]},{mate:`menaion:11-30.c0.matins.exapostilarion_glory`,mateHash:`m0b87057637cb64`,score:.17,text:`Most gloriously let us praise the apostle Andrew, the brother of Peter, the first of all the disciples, the beholder and servant of Him Who is the Word, for he hath enlightened the nations and, crucified, met his end as a disciple of the Master.`,tones:[]},{mate:`octoechos:tone5.matins_weekday.tue.canons[0].odes.5.irmos`,mateHash:`m14e74d7ff9f57a`,score:.16,text:`Hasten Thou and have compassion on my wretched soul, * which doth battle at night * with the darkness of the passions. * Shine in me with the brightness of the day, * O noetic Sun, * and thereby make the night give way to light.`,tones:[5]}]},of593a3fa22:{mate:`octoechos:tone4.great_vespers.dogmatikon`,mateHash:`m13ec200d417e2d`,tone:4,score:.36,next:.18,evidence:[`wording 0.36 (next 0.18)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-1116-texts-tt`,head:`Tone 4 (Theotokion – Dogmatikon)`},why:[`wording below the bar`],text:`The Prophet David was a [fa]ther of the Lord | through thee, O [Vir]gin. | He fore[told] in songs the One Who worked [won]ders in thee: | “At Thy right hand [stood] the Queen,” | Thy Mother, the medi[at]rix of life, | since God was freely born of her without a [fa]ther. | He wanted to renew His fallen image, made corrupt in [pas]sion, | so He took the lost sheep up[on] His [shoul]der | and brought it to His [Fa]ther, | joining it to the [heav]enly pow’rs. // Christ, Who has great and rich mercy, has saved the world, O Theo[to]kos.`,prints:1,dates:[`2026-1116`],mateText:`Prophet David, the ancestor of God, * spoke of thee in psalmody unto Him Who hath accomplished great things in thee. * For God was well pleased without father to become a man from thee, * the Queen who standeth at His right hand, * and He - the source of life - showed thee to be His mother, * that He might renew His own image, corrupted by the passions. * Having found the lost sheep wandering on the mountain * He hath laid it upon His shoulders, * that He may bring it to his Father; * and in accordance with His own will * unite it to the heavenly powers * and thus, O Theotokos, save the world, ** Christ, Who is richly and abundantly merciful.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:11-15.c0.matins.canons[0].odes.9.items[0]`,mateHash:`m0666112e8e1a9d`,score:.18,text:`Following the godly and divinely inspired words of Christ, O divinely radiant confessors, rejoicing, ye took the cross upon your shoulders, following in the steps of the Bestower of life, O right glorious ones.`,tones:[4]},{mate:`octoechos:tone4.little_vespers.lic[0]`,mateHash:`m14bb89f283361f`,score:.18,text:`Unceasingly worshiping Thy life-giving Cross, O Christ God, * we glorify Thy Resurrection on the third day, * for through it, O all-powerful One, * Thou hast renewed corrupted human nature * and shown us the way to heaven, ** since Thou alone art good and the Lover of mankind.`,tones:[4]},{mate:`octoechos:tone4.matins_weekday.tue.sessionals[2].closer`,mateHash:`m0ebb51e0fe993f`,score:.17,text:`By thy divine birthgiving, O pure one, * thou hast renewed the mortal nature of those born on earth, * which had become corrupt through the passions, * raising up all from death to a life of incorruption. * Wherefore, as is meet we all bless thee, ** O most glorious Virgin, as thou didst foretell.`,tones:[4]}]},of62caa79fb:{mate:`octoechos:tone5.dismissal_theotokion`,mateHash:`m1ecec253e7132a`,tone:5,score:.4,next:.28,evidence:[`wording 0.4 (next 0.28)`,`tone 5`,`place: matins`],first:{doc:`2026-1018-texts-tt`,head:`Tone 5 Resurrectional Dismissal Theotokion`},why:[`wording below the bar`,`a second hymn is close`],text:`Re[joice], Impassable [Gate] of the Lord! | Rejoice, Wall and Protection of those who [run] to thee! | Re[joice], Unshakable [Re]fuge! | Re[joice], thou who knewest not [wed]lock, | who gavest birth in the flesh to thy Cre[at]or and God! // Do not cease praying for those who [praise] and [wor]ship thy Son!`,prints:2,dates:[`2026-1018`,`2026-1115`],mateText:`Rejoice, impassible portal of the Lord! * Rejoice, rampart and protection of those who have recourse unto thee! * Rejoice, haven untouched by storms, * and who knowing not wedlock, * didst bear in the flesh thy Creator and God. * Cease not to intercede for those ** who praise and worship thine Offspring.`,mateTones:[5],sections:[`at Great Vespers`],others:[{mate:`octoechos:theotokia.doxasticon_theotokia.2.mon_eve_aposticha`,mateHash:`m1b08b76bf067ed`,score:.28,text:`O blessed Theotokos, * thou mystically sealed and impassible gate: * accept our entreaties, and bring them unto thy Son and God, ** that through thee He may save our souls.`,tones:[]},{mate:`menaion:12-01.c0.matins.canons[0].odes.7.items[3]`,mateHash:`m11267de968dc79`,score:.25,text:`The prophet beheld thee as an impassable gate, O most pure Virgin, which only One passed through. To Him do we all chant: O God, blessed art Thou!`,tones:[5]},{mate:`octoechos:tone5.matins.sessionals[1].closer`,mateHash:`m1be96a2ac95494`,score:.24,text:`The Bride who knew not wedlock, the Birthgiver of God, * who turned Eve’s grief to joy, * do we the faithful hymn and worship, * for thou hast redeemed us from the ancient curse. * And now, O all-hymned most holy one, ** cease not to make intercession for the salvation of our souls.`,tones:[5]}]},of9f5c911a9:{mate:`menaion:11-14.c0.vespers.aposticha[2]`,mateHash:`m1af5d6cc1bf53e`,tone:1,score:.47,next:.17,evidence:[`wording 0.47 (next 0.17)`,`tone 1`,`place: vespers`,`melody “Joy of the ranks of heaven ...”`,`same date`],first:{doc:`2026-1114-texts-tt`,head:`[Tone 1] (Joy of the Heavenly Hosts)`},why:[`wording below the bar`],text:`O thrice-blessed Philip, | as the light-bearer of Christ’s Apostles, | thou dost possess the bright light of the honorable Church. | Our souls, all-praised one, are enlightened by thy prayers // and delivered from fierce calamities.`,prints:1,dates:[`2026-1114`],mateText:`O thrice-blessed Philip, * having thee as the lamp-bearer of the apostles of Christ * and the radiant beacon of the honored Church, * we are all now enlightened in soul * and delivered from most grievous misfortunes ** by thy prayers, O all-praised one.`,mateTones:[1],sections:[`Aposticha`],others:[{mate:`octoechos:tone1.matins_weekday.tue.canons[1].odes.9.items[4]`,mateHash:`m0693e7ab9013f2`,score:.17,text:`Like the throne of the cherubim thou holdest Him Who upholds all things, and thou feedest Him Who feeds us. Him do thou unceasingly entreat, O divinely joyous and pure one, that thy flock may ever be delivered from earthquake, calamity, exile and every need.`,tones:[1]},{mate:`menaion:11-14.c0.matins.sessional_1[0]`,mateHash:`m08f383742ea8d3`,score:.17,text:`O Philip most wise, apostle, martyr and beholder of Christ, blessed friend of God: by thy prayers do thou free from tenacious transgressions those who celebrate thine honored memory, and grant that they may receive a heavenly inheritance.`,tones:[1]},{mate:`octoechos:tone1.matins_weekday.tue.canons[0].odes.7.items[4]`,mateHash:`m13d53db137ee11`,score:.15,text:`O all-hymned one, Christ desired thee alone out of all generations, as one pure and honorable, to be His habitation; and shining forth from thee like the sun, He hath enlightened all the earth.`,tones:[1]}]},ofae904c505:{mate:`octoechos:tone8.little_vespers.lic[0]`,mateHash:`m139371ca7300f9`,tone:8,score:.36,next:.18,evidence:[`wording 0.36 (next 0.18)`,`tone 8`,`place: vespers`],first:{doc:`2026-0927-texts-tt--`,head:`Tone 8 (for the Resurrection)`},why:[`wording below the bar`],text:`We [of]fer to [Thee], O Christ, | our evening song and reasonable [ser]vice, | for Thou didst [will] to have [mer]cy on us // by Thy Resur[rec]tion.`,prints:2,dates:[`2026-0927`,`2026-1122`],mateText:`We offer unto Thee, O Christ, * an evening hymn and spiritual worship; * because Thou wast well-pleased to have mercy on us ** through the Resurrection.`,mateTones:[8],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone8.compline.thu.canon.odes.9.items[3]`,mateHash:`m1028b8d032cf46`,score:.18,text:`With thy mystical effulgence enlighten our thoughts, hearts and reasoning powers, O maiden full of the grace of God, that treading the paths of life aright, we may obtain mercy, ever singing praises unto thee.`,tones:[8]},{mate:`menaion:11-18.c0.matins.canons[0].odes.1.items[3]`,mateHash:`m057bd7d7fa748b`,score:.16,text:`In a manner surpassing understanding thou hast given birth to the incarnate and only-begotten Word, Who is co-beginningless and everlasting with the Father, O blessed and most pure Theotokos. Wherefore, reasoning correctly, we proclaim and honorably glorify thee.`,tones:[8]},{mate:`menaion:11-25.c0.appendix[0]`,mateHash:`m146407bc55afeb`,score:.15,text:`Be it known that if the apodosis of the feast of the Entry of the most holy Theotokos fall on a Sunday, the service of Hieromartyr Peter is omitted and chanted whenever the ecclesiarch desireth.`,tones:[]}]},ofaf979846a:{mate:`octoechos:tone4.great_vespers.lic[6]`,mateHash:`m0fc3cfc0bbff3c`,tone:4,score:.47,next:.18,evidence:[`wording 0.47 (next 0.18)`,`tone 4`,`place: vespers`],first:{doc:`2026-1025-texts-tt`,head:`Tone 4 (for the Resurrection)`},why:[`wording below the bar`],text:`O Lord, Thy begetting from the Father is timeless and ever[last]ing. | Thine incarnation from the Virgin is beyond words and under[stand]ing. | Thy de[scent] into hell is terrible for the devil and his [an]gels. | Thou hast [tramp]led on death, | rising on the [third] day, // and granting men incorruption and great [mer]cy.`,prints:1,dates:[`2026-1025`],mateText:`O Lord, begotten from Thy Father without time and eternal; * Thine incarnation from a virgin is inexpressible for man and beyond telling; * and Thy descent into Hades is fearful for the devil and his angels; * for having trampled upon death Thou hast arisen on the third day, ** granting mankind incorruption and great mercy.`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`octoechos:tone4.great_vespers.lic[3]`,mateHash:`m045a54d65b6756`,score:.18,text:`Come O ye peoples, let us hymn the Savior’s rising on the third day, * whereby we were redeemed from the unbreakable bonds of Hades * obtaining incorruption and life, as we cry aloud: * “Thou, who wast crucified and buried and rose again, ** save us by Thy Resurrection, O only Lover of mankind.”`,tones:[4]},{mate:`octoechos:tone4.little_vespers.lic[3]`,mateHash:`m1914219017c19e`,score:.17,text:`Thou hast shattered the gates of Hades, O Lord, * and by Thy death Thou hast destroyed the dominion of death; * delivering mankind from corruption, * granting the world life, incorruption, ** and great mercy.`,tones:[4]},{mate:`menaion:09-05.c1.matins.sessional_polyeleos[1]`,mateHash:`m0deed11c9ae995`,score:.17,text:`Thou alone art the Mother of God, thou alone art ever-virgin. O most pure Bride of God, in that thou hast given birth as a virgin, and remainest incorrupt. Wherefore, the ranks of angels and men magnify thee.`,tones:[4]}]},ofb11bcbe8e:{mate:`menaion:11-22.c0.vespers.troparia[0]`,mateHash:`m059bf4986ae343`,tone:3,score:.34,next:.32,evidence:[`wording 0.34 (next 0.32)`,`tone 3`,`same date`,`NAMES DIFFER: the OCA text names Philemon, Apphia, Onesimus; ours does not`],first:{doc:`2026-1122-texts-tt`,head:`Tone 3 Troparion (Apostles)`},why:[`wording below the bar`,`a second hymn is close`,`the OCA text names Philemon, Apphia, Onesimus; ours does not. A general hymn with a saint's name written into it is not the same hymn for another saint (ruled 15 Nov 2026): confirm only if both texts are of the same saint and the name would be right wherever our text is used`,`a Menaion hymn in Tone 2 is closer in wording (0.63): 11-22.c0.matins.canons[1].odes.8.items[3]`],text:`Holy A[pos]tles Philemon, Archipus, Apphia, and O[ne]simus, | entreat the ^[mer]ciful God // to grant our souls for[give]ness of trans[gres]sions!`,prints:2,dates:[`2026-1122`],mateText:`O holy apostles * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,mateTones:[3],sections:[`at Great Vespers`,`at the Divine Liturgy`],others:[{mate:`octoechos:tone3.matins_weekday.thu.sessionals[1].items[2]`,mateHash:`m0f7d26b43fa299`,score:.32,text:`O holy passion-bearers, entreat the merciful God, that He grant our souls remission of transgressions.`,tones:[3]},{mate:`octoechos:tone3.compline.tue.canon.odes.8.items[2]`,mateHash:`m036582e56e5c6b`,score:.19,text:`Pray thou to Christ, O Theotokos who hast given birth to Him from thy holy womb, that He grant me forgiveness of my manifold transgressions, that I may chant: O all ye works of the Lord, hymn the Lord, and supremely exalt Him throughout the ages!`,tones:[3]},{mate:`menaion:12-01.c0.vespers.theotokos_stichera[2]`,mateHash:`m05dfcfe380ba91`,score:.16,text:`I have surpassed all in mine offenses, O Lady; but, having cleansed me of them, O Virgin, entreat thy Son and God, that for the sake of thy mercy, I may be granted forgiveness at the judgment which is to come.`,tones:[]}]},ofb2cb04d93:{mate:`menaion:09-06.c0.vespers.lic[0]`,mateHash:`m1345b802904133`,tone:4,score:.41,next:.21,evidence:[`wording 0.41 (next 0.21)`,`tone 4`,`place: vespers`,`same date`],first:{doc:`2026-0906-texts-tt`,head:`Tone 4 (for Archangel Michael) (As one valiant among the martyrs)`},why:[`wording below the bar`],text:`O Michael, the Chief [Cap]tain, | thou hast been revealed as the brightest attendant of the triply-radiant [God]head. | To[geth]er with the heavenly powers thou criest [out] with joy: | “Holy art Thou, O [Fa]ther, | Holy art Thou, O Word, also with[out] be[gin]ning, | Holy art Thou, O Holy [Spir]it: | one glory, one kingdom, one [na]ture, // one Godhead and [pow]er!”`,prints:2,dates:[`2026-0906`,`2026-1108`],mateText:`O Michael, supreme commander, * shown forth as a most radiant intercessor before the three-Sunned Godhead, * thou dost cry out, rejoicing with the heavenly hosts: * Holy art Thou, O Father! * Holy art Thou, O co-beginningless Son! * Holy art Thou also, O Holy Spirit! * One glory, * one Kingdom and nature, ** one Godhead and power!`,mateTones:[4],sections:[`Lord I Call...`],others:[{mate:`menaion:09-06.c0.matins.canons[0].odes.7.items[2]`,mateHash:`m14320936327048`,score:.21,text:`Being comely, most splendid and of godly aspect, in a manner surpassing understanding art thou the chief of the immaterial spirits, O most radiant Michael; with them, therefore, pray thou on our behalf.`,tones:[4]},{mate:`menaion:09-06.c0.matins.canons[0].odes.7.items[1]`,mateHash:`m072fa17acdf42d`,score:.2,text:`With faith let us shout the praises of the radiant Michael and Gabriel, chiefs among the angels that behold God, our good comforters, intercessors and protectors.`,tones:[4]},{mate:`octoechos:tone4.compline.sat.canon.odes.3.items[2]`,mateHash:`m1199ca19586fdb`,score:.17,text:`Attend unto the voice of thy servant who am in need of thy help, O Mother of God. O my hope, hearken unto me and rescue me from perils!`,tones:[4]}]},off4c7a212d:{mate:`octoechos:tone2.compline.mon.canon.odes.3.irmos`,mateHash:`m02725aac1c4c14`,tone:2,score:.38,next:.2,evidence:[`wording 0.38 (next 0.2)`,`tone 2`,`place: matins`,`same date`],first:{doc:`2026-0908-texts-tt`,head:`Tone 2 1st Canon, Ode 3 – Heirmos`},why:[`wording below the bar`],text:`Establish us in Thyself, O Lord; | Thou Who on the Tree didst put sin to death, | and implant the fear of Thee in the hearts // of us who sing praises to Thee.`,prints:1,dates:[`2026-0908`],mateText:`O Lord, who didst slay sin upon the Tree, * firmly establish us in Thee, * and in the hearts of us who hymn Thee * plant the fear of Thee.`,mateTones:[2],sections:[`Gospel`],others:[{mate:`octoechos:tone2.nocturns.canon.odes.3.items[2]`,mateHash:`m0db162c4a2484a`,score:.2,text:`O three-sunned Unity, establish the hearts and minds of Thy servants upon the rock of faith, and enlarge them by the depth of Thy love; for Thou art our God, in Whom we set our hope. Let us not be put to shame.`,tones:[2]},{mate:`octoechos:tone2.matins.canon.odes.3.irmos`,mateHash:`m010e9e4fff9a7a`,score:.17,text:`The desert of the barren Church of the nations * blossomed like a lily * at Thy coming, O Lord, * therein hath my heart been established`,tones:[2]},{mate:`octoechos:tone2.compline.thu.canon.odes.3.irmos`,mateHash:`m0aeef38f8265fe`,score:.17,text:`The desert of the barren Church of the nations * blossomed like a lily * at Thy coming, O Lord, * therein hath my heart been established.`,tones:[2]}]}};export{e as OCA_MATCHES_REVIEW};